/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20141027-7","meetingId":"h26-cm10","date":"2014年10月27日","dateIso":"2014-10-27","committee":"厚生委員会","time":"午前１０時００分～午後 ３時１４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の第６４号議案 品川区立シルバーセンター条例の一部を改正する条例","agenda":"はじめに、(1)の第６４号議案 品川区立シルバーセンター条例の一部を改正する条例","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"そうすると、今度また新しくシルバーセンターを建て直すということですよね。その間の、利用者のシルバーセンター等のご利用については、どのような形になるのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"これまで、さまざまな町会・自治会、あるいはその他の施設等を代替施設として検討してまいりましたけれども、この９月２５日の説明会におきましては、お近くのシルバーセンター、いわゆる五反田シルバーセンターが一番最寄りのシルバーセンターになりますけれども。","voiceIndex":8,"id":"exchange-001"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"このシルバーセンターの平面図が、今年１月の委員会で出されていたと思うのですけれども、これよりも見やすくて、もう少し詳しくなったものが、今回の総務委員会の契約のところで出ていたので、厚生委員会にもそういった資料があったらいいと思ったのです。そのうえで、だれでもトイレというのは、厚生委員会に配られた資料では見受けられないのですけれども、多目的トイレがだれでもトイレなのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-002"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"わかりました、すみません。代替施設というのは、今、答弁がありましたけれども、ほかに検討できなかったのか、もう一度伺わせていただきたいと思います。","respondent":"白鳥高齢者いきがい課長","answer":"したがいまして、これは２カ月前ですけれども、予約の手間はかかるわけですけれども、そういった中で、ご利用の案内を丁寧にさせていただいたところでありまして、そこでも、利用グループの方々からご納得いただいたと認識しているものです。","voiceIndex":12,"id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"やはりこれだけの方が、今までいた場所を変わるということでは、ほんとうにやはり大変なことだと思うのです、特に高齢者の皆さんですし。そうすると、五反田シルバーセンターのお風呂は、週何回やっていますか、五反田シルバーセンターはお風呂はやっていないのでしょうか。入浴者数のところに、五反田シルバーセンターというのがないのですけれども、そのお風呂利用のところは、どうなっていくのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"これまで大崎シルバーセンターにつきましては、入浴サービスということで、週２日間行ってまいりました。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"今、お風呂がある家はほんとうに多いので、そういう中でも、やはり高齢者の皆さんがこういうところを利用するというのは理由があると思うのです、コミュニティだったり、一人で入浴するのは不安だという。近くに浴場があるということも説明されているということですけれども、もう少し代替施設がなかったかと思うところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":16,"id":"exchange-005"}]},{"id":"topic-02","title":"の第６５号議案 品川区手数料条例の一部を改正する条例","agenda":"の第６５号議案 品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）副委員長","kind":"意見","question":"手数料条例ですので反対するものではないのですけれども、薬事法改正そのものが、インターネットで販売できるとか、もう少し慎重にやるべき問題だと思っていますが、そこは国のほうの問題ですので、この条例には賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":33,"id":"exchange-006"}]},{"id":"topic-03","title":"の第５６号議案 平成２６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"の第５６号議案 平成２６年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"３３ページのところをお伺いしたいのですが、平成２６年度当初予算に反映できなかったため補正したという理由があったのですけれども、その理由をもう少し詳しく教えていただきたい。それから、地域包括支援センター機能強化推進事業費を職員費に充当するという説明があったのですけれども、充当して、具体的にどういうことをされるのか、お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"補正の理由になりますけれども、実際、東京都のほうの予算が決定して、その後、区のほうにおりてくるのですけれども、その通知自体が、区のほうに１月末にきておりますので、当初予算の編成はもう既に終盤に差しかかっている状態でしたので、今回。","voiceIndex":40,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"そういう方々に充当することはわかったのですけれども、要は、機能強化事業ですから、介護の方々が会議体を新しくつくって、これから地域包括支援をどういうふうに展開していこうかということについて人件費が使われていくと思っているのですけれども、その具体的なことについて、もう少しご説明をしていただければと思いますが、いかがですか。","respondent":"永尾高齢者福祉課長","answer":"幸い品川区については、もともと品川区役所に地域包括支援センターを一つ置いて、そこが統括になっていて、２０カ所の在宅介護支援センターをまとめて、いろいろな施策を行っているという状況ですので、現在のこの仕組みの中で。","voiceIndex":42,"id":"exchange-008"},{"speaker":"伊藤委員","kind":"質問","question":"ということは、品川区は進んでいるから、内示をしていただけたと判断しますけれども、そうすると、やはり聞きたいのは、進んでいるところにお金が来たわけですから、それを有効に使ってほしいと議員は思うわけであって、それで何をするおつもりなのでしょうか、お聞かせください。","respondent":"永尾高齢者福祉課長","answer":"そのときに、今、各地区にきちんと２０カ所あるというその今の基盤をしっかり生かして、今後の高齢者施策の方向性を、区の統括の地域包括支援センターが中心となって議論しながら決めていきたいと考えておりますので、今やっと基盤ができているところなので。","voiceIndex":44,"id":"exchange-009"},{"speaker":"伊藤委員","kind":"質問","question":"もうご承知かと思いますが、これからは地域包括ケアというものが具体的になってくる中にあって、おそらくそういうことを全国の中で進めていく一環なのかと推測はするのですけれども、それをこれから、品川区もやっていかなければならないわけですから、こういうものを使って、次にくる地域包括ケアという大きな目標があるわけですから、それに向けて具体的な対処をしていただきますようお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今のことと関連することと、もう１点伺います。この３００万円については、先ほど、強化支援員配置ということで、その配置のための人件費等ということでいいのでしょうか、もう一度確認です。それであれば、その対象者はヘルパーやケアマネジャーになるのか。先ほど、区のケアマネジャーとか保健師がかかわるとおっしゃっていたのですが、その辺をもう１回ご説明をいただきたい。","respondent":"永尾高齢者福祉課長、川島健康課長","answer":"地域包括支援センター機能強化事業の中の介護予防機能強化推進事業のほうになりますけれども、介護予防機能強化支援員は、リハビリテーションの専門員ということで、理学療法士にお願いをする予定です。浴場の設備助成の上限と補助率を上げたというところですが、老朽化が進んでいるということで、あちこち手を入れたいところはあるのだけれども、なかなか踏み込めないところもあったところですけれども、こういった改正によって。","voiceIndex":47,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"確認","question":"包括支援センターと名前が変わったわけではないですね、そこだけ確認です。それから、公衆浴場のほうですけれども、そうすると具体的にどこか整備するところがあるということではなくて、そういうニーズがかなりありそうなので、まずはとりあえず３００万円と、こういうことでよろしいのですか。その二つをお願いします。","respondent":"永尾高齢者福祉課長、川島健康課長","answer":"品川区の在宅介護支援センターのことになります。品川区の在宅介護支援センターは、地域包括支援センターのサブセンターという位置づけになっていますので、補助金をいただくときは、そういう指定になります。今のお話ですが、浴場組合のほうからも、なかなか設備改修が大変だというお話を聞いておりましたので、どこを具体的にやるかというのは、こちらではわからない部分はあるのですが、ニーズはあると判断しております。","voiceIndex":50,"id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私も、公衆浴場のところで、設費改修費の上限が上がって、補助率も上ったということでは、私たちも求めていたものなので、ほんとうに良かったと思っているのですが、今現在の銭湯の数、平成元年には８０軒ほどあった銭湯が、だいぶ減ってきていると思うのですけれども、今になって、こういった補助を上げた理由を、ちょっと伺いたいと思います。","respondent":"川島健康課長","answer":"今このタイミングでというところなのですが、やはり長い間、例えば営業不振、それから後継者がないという話だと、なかなか支援はできないのですけれども、いろいろと苦しいという話は聞いておったのですが、今回の消費税の増税がまず一つあったというのが判断の理由です。","voiceIndex":53,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"浴場組合の皆さんの意見も聞いて、ということで、補助金を上げていくことは良かったと思っているのですけれども、全くなくなってしまった地域もあるのですけれども、そこへのお風呂の支援というか、何か考えられている対策がないのか、ちょっと伺いたいのですが。","respondent":"川島健康課長","answer":"今ある浴場の支援をしていくというところでは頑張れるとは思うのですが、ない部分をどうしていくかというのは大変な課題かと考えています。この減少を減らしていくのが第一かと考えています。","voiceIndex":55,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"何かしら対策を打っていただきたいと、私は思います。これ以上なくなっていくことを、区としてはどう考えているのか、最後にお聞きしたいと思います。それから、３３ページの生活困窮者自立支援法施行準備経費は、何をどう準備していくのか。そこに住宅支援給付事業なのですけれども、ここに住宅支援の事業として、こういった準備がされていくという関わりを教えていただきたいと思います。","respondent":"川島健康課長、伊東生活福祉課長","answer":"例えばオリンピックが開催された場合、海外から来た方も、こういったものがあると大変喜ばれる方も多いと聞いておりますし、東京都の浴場組合のほうでも。これから政省令が出されてきますので、それに基づきまして、細かな準備作業が多々出てくるということで、それに向けて、年度内にしっかりと準備を進めるということで、今回の補正を組ませていただいたものです。","voiceIndex":57,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"生活困窮者自立支援法のところで、準備経費、これから進んでいくところでの準備ということですが、今回は補正にこういうふうに出てきていますが、それから今、生活困窮者自立支援制度というものが進んでいくわけですけれども、ここに準備しているものは、今はこの部分だけなのでしょうか。","respondent":"伊東生活福祉課長","answer":"ただ、新しく法律が整備されるということで、もっと綿密なアセスメントなどもやっていかなければいけないのですけれども、そういうところをもう少し充実させた形で実施していかなければいけないということで、レベルアップといいますか。","voiceIndex":60,"id":"exchange-016"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"３７ページには、生活保護のシステム改修など、生活保護費の追加分などもあるのですけれども、これと生活困窮者自立支援法との関わりは、どういうことになっていくのでしょうか。","respondent":"伊東生活福祉課長","answer":"生活保護システムの改修につきましては、今年７月１日から、就労自立給付金が創設されたということで、それに対応するためのシステムの改修ということで行わせていただくものです。","voiceIndex":62,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"ですので、税と社会保障の一体改革のもとで、社会保障の大解体が進む中で、この生活保護もいち早く基準額が下げられて、そしてさらにこういった振り分けがされていくところでは、私たちは、こういった準備経費に使うような補正予算には反対をしていきたい、賛成できないということで、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":69,"id":"exchange-018"}]},{"id":"topic-04","title":"の第５７号議案 平成２６年度品川区介護保険特別会計補正予算（歳出）","agenda":"の第５７号議案 平成２６年度品川区介護保険特別会計補正予算（歳出）","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"一般管理費の電算システムのところで何点かお伺いしたいのですが、コード英数化対応という説明が、たしかあったような気がするのですけれども、素人なものでわからなくて、その内容を教えていただきたいということが１点。それから、これは国の要請で変わったという感じがするのですけれども、そうすると、この２,１００万円については、後で、何かしら国から手当てがされるのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それは、支給額が後で変更になったり、いろいろな対応があるため、１回使った番号をずっとそのまま使用することになりますので、もう一般の数字だけでは対応がし切れなくなったということでのコード化になります。こちらは、国全体でこの改正をしています。","voiceIndex":76,"id":"exchange-019"},{"speaker":"伊藤委員","kind":"提案","question":"これは、例えば区長会等を通して国へ要請すべきなのではないでしょうかという提案ですけれども、そう思いました。そうすると、将来、国民全てに番号が振られますよね、それの前段階のイメージなのか。つまり高齢者も、私たちもそうだけれども、番号が振られて、それがどこでも全国で共通化するための前段階として、高齢者レベルで変更をしたという理解でよろしいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"番号制のお話が今ございましたけれども、こちらに関しては、番号制に対応というよりも、現在の仕組み上、足りなくなってきていることに備えるということになります。この番号自体が、その先、番号制が入るときにどうなるのかというのは、現在、検討しています。","voiceIndex":78,"id":"exchange-020"},{"speaker":"山元委員","kind":"質問・要望","question":"しながわ出会いの湯事業追加分なのですけれども、今、区内６５歳以上の方が、毎週木曜日、ロビーなどでカラオケをやったり、体操をやったりということなのですけれども、実は、登録していると、７時まで割引があるというお話を聞いたのですが、それは具体的にどのくらい割引されるのか、教えていただきたい。","respondent":"川島健康課長","answer":"出会いの湯の時間ですが、営業が始まってしまうとお客さんと混ざってしまうので、大体浴場が始まる１時間くらい前から、その時間を使って健康体操と入浴をしていただくというサービスになっております。","voiceIndex":80,"id":"exchange-021"},{"speaker":"山元委員","kind":"質問・要望","question":"そうしますと、割引というのは、区ではなく、あくまでも組合のほうでやっているということなのですね、わかりました。そのことで質問したいことがあったのですが、それは違う形でさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-022"},{"speaker":"たけうち委員","kind":"質問","question":"この事業に限らず、ほかにも同じように、国のほうでどうしても予算の成立に合わせたりする関係で遅れてくるのがあると思うのですけれども、そういうのをうまく活用するような工夫というのですか、それは高齢者福祉課長のところだけではないと思いますけれども、とりあえず前段のほうだけ教えてください。","respondent":"永尾高齢者福祉課長","answer":"実際に間に合わなかったというところで、時期的な問題はあるのですけれども、国から来た補助金自体もかなり金額が少ないもので、区分支給限度基準額の変更については、手元に具体的な細かい数字はないのですけれども、５００万円もいっていなかった記憶がありますので。","voiceIndex":83,"id":"exchange-023"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"出会いの湯ですけれども、これは介護予防のほうでやられているということですけれども、消費税増税に伴うということですが、利用する方の軽減には、特にはつながらないものなのでしょうか。","respondent":"川島健康課長","answer":"実は、出会いの湯のほうは、消費税増税分というのは、４月から浴場組合のほうに払うお金は、それを見越した増額がありまして、直接の大きな原因は、４月１日付に浴場の料金の改定がありまして、これは総括原価方式ということで、所要経費。","voiceIndex":85,"id":"exchange-024"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"出会いの湯というのは、今ある浴場全部でやられていて、そこに補てんされるものなのでしょうか。この委託費が追加されることで、一浴場当たり大体どのくらい増になるのか、伺いたいと思います。","respondent":"川島健康課長","answer":"先ほども説明しているのですが、１カ所使わせていただいた会場利用料というところで、１回２万７,９４０円お支払いするという形に、１回当たり２,０２０円の増額となっております。","voiceIndex":87,"id":"exchange-025"},{"speaker":"石田（ち）副委員長","kind":"確認","question":"出会いの湯事業そのものは、今までは介護予防でやられていたものでしたか、ちょっとそこの確認をお願いします。","respondent":"川島健康課長","answer":"すみません、年度はあれなのですけれども、途中から介護予防事業という形で、事業をやっているところです。","voiceIndex":89,"id":"exchange-026"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、今までは一般財源でやられていたものを、介護予防にと、保険料との兼ね合いのことは、いつも区は言うと思うのですよね、保険料に跳ね返るからサービスを上げられないとか、いろいろあると思うのですけれども、これを介護予防にすることで、やはり保険料に跳ね返ることにもなっていくと思うのですけれども、この事業を介護予防にした理由を伺いたいと思います。","respondent":"川島健康課長","answer":"理由は、まさしく外出をして、入浴して健康に寄与するというところで、介護予防事業の内容に合致していたということだと思います。","voiceIndex":91,"id":"exchange-027"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"これ自体は、消費税増税に伴うものということで、浴場の負担軽減というところではあると思うのですけれども、そもそもこの事業は一般財源でやるべきだなと、私は思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-028"}]},{"id":"topic-05","title":"平成２６年請願第１８号 ウイルス性肝炎患者に対する医療費助成の拡充に関する請願","agenda":"平成２６年請願第１８号 ウイルス性肝炎患者に対する医療費助成の拡充に関する請願","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"確認したいのは、請願についてのお伺いなのですけれども、ウイルス性肝硬変・肝がんに係る医療費助成制度を創設すること、となっていますから、これが今、あるのでしょうか、ないのでしょうかという確認。それから、今あった、診断書で肝機能障害による認定基準の緩和というのは、すみません、もう少しわかりやすく説明していただけるとありがたいと思うのですが、いかがでしょうか。","respondent":"佐藤保健予防課長","answer":"制度につきましては、先ほど申しましたように、インターフェロンに係る治療、インターフェロンというのは、ある種坑ウイルス薬ということになっておりますので、Ｂ型肝炎ウイルス、Ｃ型肝炎ウイルスを完全に殺すということは難しいわけですけれども、少したたく、殺す。","voiceIndex":107,"id":"exchange-029"},{"speaker":"伊藤委員","kind":"質問","question":"理解するところもあるのですが、つまり、今の現行制度はあるけれども、非常に限定されているので、それを新しく創設してくれという請願だと判断しました。そうすると、これをもし創設することになれば、当然、国の制度なり、例えば法改正なのか、厚生労働省なのかわかりませんけれども、そういうところの対応になるのでしょうか、それが１点。その二つを、お聞かせください。","respondent":"佐藤保健予防課長","answer":"品川区での単独の独自事業ですが、そこが逆に請願の争点なのかとも思いますけれども、肝硬変・肝がん患者の医療費というのは大変高額になっております。それで、数々の患者がいる中で、そこを品川区が単独で負担するということは、財政的にはかなり厳しいかと考えております。","voiceIndex":109,"id":"exchange-030"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、この請願の中のあるように、３５０万人以上という推計からすると、これは当然、品川区単独でどうこうする話ではないわけであって、この請願の方の願いとしては、国あてにこういう意見書を提出していただきたいということなので、今も制度としてはあるけれども、それは全ての方々に行き渡っていない現状があって、それから身体障害者の手帳についても、そういう評価はされているけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":111,"id":"exchange-031"},{"speaker":"たけうち委員","kind":"質問","question":"これを読ませていただくと、やはり薬害であるにもかかわらず、それがなかなか証明できないような状況になっている方が大勢いらっしゃるということで、これは国として、しっかりもう少し手を差し伸べなければいけないと思います。そのうえで、幾つかの自治体、２３区でも多くのところで同じような意見書を出されていると伺っているのですけれども、その辺の状況をもしつかんでいたら教えてください。","respondent":"佐藤保健予防課長","answer":"私ども、非公式には多くの区で出されているということは聞いておりますが、具体的に何区で出されているかということまでは把握しておりません。","voiceIndex":112,"id":"exchange-032"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。私どもも、会派のメンバーが請願紹介議員になっておりますし、また、この方たちからもお話を伺いましたので、意見はまた後で述べしますけれども、しっかり進めていければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-033"},{"speaker":"向委員","kind":"質問・要望","question":"先ほど、伊藤委員からご質問が出ていた中で、教えていただきたいのですが、障害者手帳の認定基準のご説明がありましたが、３段階の中で一番重い分類ということで、もう少しわかりやすくというか、肝臓がどのような状態になればというか、その状態についてご説明いただいてもよろしいですか。","respondent":"佐藤保健予防課長","answer":"例えば肝性脳症といって、アンモニアが頭の中にたまってしまって意識が混濁するとか、腹水がたまるとか、腹水と密着しているのは、血清のアルブミンというたんぱく質が肝硬変の方は減ってまいります。","voiceIndex":115,"id":"exchange-034"},{"speaker":"向委員","kind":"質問","question":"アンモニアが脳にたまるとか、腹水がたまるというのも、伺うだけで結構シビアな状態ということで、その状態になると、そもそもその患者のクオリティ・オブ・ライフとか、そのあたりはもうかなり低下していると考えざるを得ないと思います。","respondent":"中山障害者福祉課長","answer":"先ほど、認定基準の医療的な考え方というところでは、既にご説明がありましたが、そもそも身体障害者福祉法に基づく身体障害者の考え方としまして、身体機能に一定以上の障害があることと、それが永続する障害であること、要するに治癒の可能性のある方については。","voiceIndex":117,"id":"exchange-035"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"今の質問に関連してなのですけれども、区として単独で交付していくのは難しいと。区内で認定を受けている方はどのくらいいるのか、わかりますか。","respondent":"中山障害者福祉課長","answer":"すみません、今ちょっと手元に、肝炎でという方の数字を持っていないのですけれども、やはり少ない数字にはなっております。内部障害の方でも、多いのは腎臓と心臓疾患の方がほとんどになっておりますので、肝炎で対象になっている方はごく一部の方となっております。","voiceIndex":119,"id":"exchange-036"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党も、結論を出していただきたいと思います。そして、採択していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-037"},{"speaker":"向委員","kind":"質問・要望","question":"今日、結論を出していただきたいと思います。民主・改革ネットといたしましても、ぜひ意見書を国のほうに出していく方向でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"共産党も、本日結論を出すということで、採択を求めます。やはりこれだけの肝炎の患者たちが浮き彫りになってきたというところでは、ほんとうに日々の運動などがこうやって浮き彫りにしてきたのではないかと思いますので、これを機に、私たちも一層勉強をして、いっしょにさらに拡充するように求めていきたいと思っています。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-039"}]},{"id":"topic-06","title":"平成２６年請願第１５号 手話言語法制定を求める意見書の提出に関する請願","agenda":"平成２６年請願第１５号 手話言語法制定を求める意見書の提出に関する請願","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"これは確認といいましょうか、もし理事者がご存じであれば、ということなのですけれども、言語法という法律に基づかなければ手話が認められないということではなくて、ここで請願として言っていることは、今、言語法の中に手話が認められていないという判断でよろしいのでしょうか。その確認を、まずいただきたいと思います。","respondent":"中山障害者福祉課長","answer":"ただ、手話言語法というものができることで、より手話を一般の方にも広く知っていただき、あらゆる社会で手話が自由に使えるような社会を目指すということで、加えてということでしょうか、今でも言語ではあるのですけれども。","voiceIndex":138,"id":"exchange-040"},{"speaker":"伊藤委員","kind":"質問","question":"これも、ご存じであれば、ということでお伺いするのですけれども、仮定として、手話言語法が成立した場合、私のイメージなのですけれども、いろいろなテレビのニュース等々で、今でもときどき手話が入っている放送がありますけれども、あれが日常的になるのでしょうか。要するに、言語として確立されるということは、どういったことが予想されるか、教えていただければと思います。","respondent":"中山障害者福祉課長","answer":"例えば耳の聞こえない子どもが生まれたときに、人工内耳の手術のご説明をする前に、手話というものもあって、それを獲得する、そういう選択肢もありますよというふうに、そういったことで手話があるということを、いろいろな場面で情報提供し。","voiceIndex":140,"id":"exchange-041"},{"speaker":"伊藤委員","kind":"意見","question":"そういうことから推測すれば、この請願自体は、今の現状をさらに一歩進めていくという感触だと思います。それから、全国の都道府県等の内容を見れば、これは非常に価値あるものではないかと、今は思っております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-042"},{"speaker":"たけうち委員","kind":"質問・要望","question":"先ほど、いろいろな自治体の動きなども教えていただいて、かなり多くの自治体で意見書を求めるものが通っているというお話もありました。東京都議会のほうでも、第２回定例会で意見書が全会一致で採択されて、意見書提出が決まったとも伺っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-043"},{"speaker":"山元委員","kind":"質問","question":"私の地元の八潮には明晴学園という聾唖学園があります。一つ質問なのは、例えば、この請願が通った場合の話ですけれども、役所的に、今手話のできる方はそんなにたくさんいないと思いますけれども、現実的に、ところどころにそういう手話ができる方たちが配置されるということは考えられますか。","respondent":"中山障害者福祉課長","answer":"あるいは、手話を使わなくても、聞こえない方、あるいは来庁された方にできる限り伝わる方法で、しっかりと情報提供していく、これは手話言語法とは関係なく、区役所として進めていくべきことであろうと考えています。","voiceIndex":144,"id":"exchange-044"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"手話言語法がさらに広がるということは、こういったことがさらに広がっていくということだと思うのです。やはり言語ですので、この間もその学習会で言われていたのですけれども、手話通訳の方は、品川区は２３区でも一番少ない区だとおっしゃっていたのです。そういったところも拡充されていくことにつながるのかなと、つなげていくべきだと私は思うのですけれども、そこら辺はいかがでしょうか。","respondent":"中山障害者福祉課長","answer":"仮に手話言語法ができて、手話が日常的なものとなっても、一方で手話を通訳できる方がいらっしゃらないと、やはりそれでは両輪となって制度を進めていくことにはなりませんので、こういった研修についても力を入れているところです。","voiceIndex":146,"id":"exchange-045"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"品川区としてできること、要は、手話についての講習会を開いていくとか、区民に対してそういったことなどを増やしていくという検討などはあるのでしょうか。","respondent":"中山障害者福祉課長","answer":"そういった中では、なかなか一足飛びにたくさんの手話通訳者を養成するのは難しい現状ではありますが、研修については、地道に行っていき、できるだけ登録者の数を増やしていく、そのような方向に向かって頑張っていきたいと考えております。","voiceIndex":148,"id":"exchange-046"},{"speaker":"向委員","kind":"質問","question":"区で助成金を出したり、そういったサポートの手厚さなど、現状をお伺いしたい。今後の展望としては増えていけばいいなと、区としてはお考えなのか、そのあたりをお伺いしたいと思います。","respondent":"中山障害者福祉課長","answer":"今後、子どもたちが実際に手話に触れたりするような機会ということになりますが、ここにつきましては、教育委員会とも協議をしながら、できるだけ手話を小さいころから身近なものとしてわかるように、手話で話している子どもたちと耳の聞こえる子どもたちが。","voiceIndex":154,"id":"exchange-047"},{"speaker":"向委員","kind":"意見","question":"今回の請願を受けて、こういった意見書が提出されることによって、実際に手話を学んで、それを必要とされる耳がご不自由な方々だけでなく、私たち健常者の一人ひとりも、いい機会ということで後押しになるようになっていけばいいということで、私たち会派としても考えております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-048"},{"speaker":"伊藤委員","kind":"質問・要望","question":"自民党としては、今日、結論を出していただきたいと思っています。態度としては、賛成をさせていただいて、採択のうえ、意見書提出をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":159,"id":"exchange-049"},{"speaker":"山元委員","kind":"質問・要望","question":"公明党も、今日、結論を出していただきたいと思います。そして、採択と同時に、意見書提出の方向性でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-050"},{"speaker":"向委員","kind":"質問・要望","question":"今日、採決をしていただきたいと思います。我が会派としては賛成でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":161,"id":"exchange-051"}]},{"id":"topic-07","title":"平成２５年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２５年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"伊藤委員","kind":"質問","question":"だから、結果はこれでいいのですけれども、その前提の部分で、どういう評価をされたのか少し気になりましたので、それをまず教えてください。","respondent":"永尾高齢者福祉課長","answer":"このモニタリングですけれども、継続して良質なサービスを行うことを目的にしておりまして、評価の中身としては、この施設の設置目的にきちんと適合されているかどうか、サービスの内容がきちんとされているかどうか、また、利用者・ご家族の声をきちんと反映しているかどうか。","voiceIndex":174,"id":"exchange-052"},{"speaker":"伊藤委員","kind":"質問","question":"今、答えられたのは結構ですが、要は、これからこういうものを出すにあたってはただ結果を出すのではなくて、こういうふうな方法で評価をしましたということについてあわせて出していただいたほうがいいと私は思っているのですが、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"品川区では、このモニタリングとは別に、サービス提供者に対してセルフチェックをするサービス向上研究会というものを設置しております。","voiceIndex":176,"id":"exchange-053"},{"speaker":"伊藤委員","kind":"質問","question":"むしろ、改善のところにありますように、営業活動を行ったとあるのだけれども、ある意味、民間の事業者と競争になってくるのかなという気もするので、幾つかの施設に同じようなことがありますよね、新規の利用者が少なかった等々あるわけですが、要は、民間の事業者と競合になる部分があるでしょう、それから、そういう中であったとしても、対象者が増えているわけですから。","respondent":"永尾高齢者福祉課長","answer":"ですので、それぞれの差別化が必要になってくるところが課題になっていて、その中で重度向けのほうがいいのか、介護予防がいいのか、そのあたりは民間も含めたニーズ調査等もしていきたいと考えております。","voiceIndex":178,"id":"exchange-054"},{"speaker":"伊藤委員","kind":"質問・要望","question":"入所している方も高齢化になっている、だけれども、地域も高齢化になっているという非常に難しい中にあって、これからこういう事業をどう展開していくか。まさに２０３０年問題でしたか、最高の高齢化になることはもう目に見えているわけですから、その傾向がはっきりと出てきつつあるので、そのことについての品川区の対応を確認しますので、ご答弁をいただきたい。","respondent":"永尾高齢者福祉課長","answer":"その辺りも、今がちょうど転換期に差しかかっているところで、医療的ニーズ、ひいては看取りの関係、そこにもつながってくるかと思いますので、これから対応していきたいと考えております。","voiceIndex":180,"id":"exchange-055"},{"speaker":"伊藤委員","kind":"質問・要望","question":"こういうお仕事はやはり大変なお仕事だと思うので、相対的にあまり収入もどうなのかというくらいでとどまっているわけであって、そうすると、ほかの事業者に対して、品川区はある意味指導ができる立場にあるわけですから、三徳会の成功例といいましょうか、そういうふうな職員の意識改革を、ほかの指定管理業者に展開するべきだと思うのですが、お考えをお聞かせください。","respondent":"永尾高齢者福祉課長","answer":"品川区内の五つの社会福祉法人ですけれども、それぞれの形で努力はされておりますけれども、それぞれいいところと、やはりまだまだなところとありますので、今までの連携の強みを生かして、それぞれいいところを取り入れるように、区としても支援をしていきたいと考えています。","voiceIndex":182,"id":"exchange-056"},{"speaker":"伊藤委員","kind":"質問","question":"もうまとめますけれども、これだけの評価結果から見て、対象者、高齢者の方々は増えていくと同時に入居者も高齢化していく、それと同時に、介護ニーズの担い手の方々はなかなか定着率が低いという、大変難しい課題がこれから出てくるわけであって、これだけの評価をされた内容を、次のステップに生かしていっていただいて、万全な態勢をとっていただけますように、改めてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":184,"id":"exchange-057"},{"speaker":"たけうち委員","kind":"確認","question":"確認なのですけれども、この評価は、基本的にはそれぞれの法人や事業をやっていらっしゃる指定管理者の方々が、自己評価というか、自分で評価されて、総括ですとか、改善とか書いていると思うのですけれども、そこをまず確認させてください。","respondent":"永尾高齢者福祉課長","answer":"こちらの総括シートというのは、区が記載をしているものです。事前にそれぞれの施設から、年１回報告書をいただくことと、それから、それぞれの施設が何らかの方法で利用者のニーズを、アンケート、または懇談等で把握して、その結果を区にお知らせをしていただいております。","voiceIndex":185,"id":"exchange-058"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。それから、例えば７ページの同じところで、改善が必要とされたという中で、利用時間の延長に取り組むとか、認知症対応型デイサービス開設に向けてとか、新しい改善ということで、いろいろ内容が出ているのも、基本的には区も了解して、そういう方向でいきますよということで、ご報告いただいていると思ってよろしいということでしょうか。","respondent":"永尾高齢者福祉課長","answer":"区と各事業所とは、２カ月に１回連絡会を開いております。それ以外でも、区のほうにご相談がある場合も多いし、連絡会のときに、そういうご報告をいただきながら、区と一緒に進めているところです。","voiceIndex":187,"id":"exchange-059"},{"speaker":"たけうち委員","kind":"質問","question":"少し細かいところで一つ伺いたいのが、５ページの中延在宅サービスセンターなのですけれども、やはりここの総括のところで、認知症および身体機能面から云々と書いてあって、より介護が必要な方や他のサービスセンターでの受入困難と判断された利用者を積極的に受け入れたとあるのですけれども、この他のサービスセンターというのは、品川総合福祉センターの他のサービスセンターで、いわゆる法人として。","respondent":"永尾高齢者福祉課長","answer":"実際は、現実、そういう方が何名かいると、もうこれ以上は難しいというところも出てくる可能性はありますけれども、そのあたりは、それぞれの在宅サービスセンターでお互いに連携を取りながら対応したりするケースもあります。","voiceIndex":189,"id":"exchange-060"},{"speaker":"たけうち委員","kind":"質問","question":"わかりました。ほかも、わからないけれども、もちろん同じようにできる範囲で受け入れていただいていると思ってよろしいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"それぞれのサービスセンターで努力はしていると認識しております。特にこの在宅サービスセンターの施設長が強くそのあたりを強調したというところで、ここに記載がされているところです。","voiceIndex":191,"id":"exchange-061"},{"speaker":"向委員","kind":"質問・要望","question":"私からは３点ほど。最近、特に大雨などいろいろ災害意識も高まっている中で、過去数年間のこういったモニタリングの結果も見直しましたけれども、そういったところの視点の一つとしても、個別に指定管理者にそういった対応を任せていくのか、評価の一つとして今後盛り込むような意識があるのか、少しそのあたりをお伺いしたいのです。","respondent":"永尾高齢者福祉課長","answer":"評価の書き方なのですけれども、特にうまくいっているところは、やはり自分として力を入れているところだということで、こういうときに表に出ているのですけれども、区といたしましては、そうではないところも、当然やっているとは思うのですけれども、今後。","voiceIndex":193,"id":"exchange-062"},{"speaker":"向委員","kind":"質問","question":"よくわかりました、ありがとうあります。ぜひ、次年度以降、さらに反映していっていただくことを、まずお願いします。これはほんとうに由々しき問題だと、私個人としても感じますし、このあたりは、必要であれは成年後見など、何かしら第三者を入れて管理することも可能だと思うのですが、このあたりについて区としては、どういった指導を具体的にはされるお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"つばさの家に入られている方の中には、成年後見がついている方もいらっしゃるのですけれども、成年後見がついていても、そういう日々の細かいお金の管理ということになりますと、やはり世話人の業務ということにもなってまいりますので、やはり細かなことではありますが。","voiceIndex":195,"id":"exchange-063"},{"speaker":"向委員","kind":"質問","question":"成年後見や第三者の方に委託するとか、何かしら、金銭管理はしっかりとしていくお考えがあるということは、よくわかりました。品川区内、成年後見などを先進的にやられていて、ただ高齢者に対する成年後見の活用と、精神疾患や知的障害の方への成年後見の対応の仕方はほんとうに全然違うと、第一線におられる方のご意見、ご苦労の話をよく伺っています。","respondent":"川島健康課長","answer":"マシンをずっと占有している人がいると、人気のあるマシンがあるそうなのですけれども、そういったことがあったので、その辺を改善するように、巡回を増やしたり、ポスター等でマナー向上の啓発をするような形をして、ある程度改善してきたと聞いております。","voiceIndex":197,"id":"exchange-064"},{"speaker":"向委員","kind":"意見","question":"ほんとうにさまざまな区民がいらっしゃって、利用者のマナーについても、民間のジムのような施設でも、やはりさまざまなご苦労をされているようなので、このあたりはかなり努力が必要かと思いますけれども、引き続きよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":199,"id":"exchange-065"},{"speaker":"鈴木（博）委員","kind":"質問","question":"３８ページにワーデン業務というのがあるのですが、これは全然別の施設で、３３ページの一番下に、夜間休日はワーデンがいるが、と書いてあるのですが、これはどういう意味なのか、ひとつお伺いしたい。それから、４６ページの４にＯＪＴ研修を中心に、と書いてあるのですが、前後を見てもよくわからないのですが、これはどのようなものなのでしょうか。","respondent":"白鳥高齢者いきがい課長、中山障害者福祉課長","answer":"いわゆる管理人、ワーデンということで、管理人業務、ワーデン業務ということで、それを記載しているものです。それぞれ二通りの呼び名があるという部分につきましては、特にその辺のところの意味合いは深いものではございません。ですので、改めて施設で時間を取って何か講演をするとか、そういうことではないのですけれども、例えば介護の現場で、介護のスキルをアップするためにそこに先輩職員がついて指導する。","voiceIndex":200,"id":"exchange-066"},{"speaker":"鈴木（博）委員","kind":"質問","question":"今のご説明を聞いてわかったのですけれども、ほかの方はご存じなのかもしれないのですが私はよくわからなかったので、例えば２７ページに、バリデーション（尊敬と共感を持って関わる）、タクティールタッチ（手によるふれあい・優しいマッサージ）とありますが、このようにちゃんと意味が書いてあるので、よくわからないような単語に関しては、これはほか人に読んでもらうものだから、ある程度。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":203,"id":"exchange-067"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"介護職員の離職率などは、ここのところどうなっているのか、お聞きしたいと思います。それからやはり、実際の運営状況や、施設の要望だったり苦労だったりというところがもう少しわかるようになっていてほしいと、私は思うのです。その辺の、評価そのものの改善について、いかがでしょうか。","respondent":"永尾高齢者福祉課長","answer":"離職率についてですけれども、全国的には大体１７％くらいと聞いております。直近のものは今まだ調査中なのですけれども、昨年調査をした段階では、品川区はほとんどの施設で１０％にいっていないので、全国的に見れば定着率はほかのところよりはいいとは考えております。","voiceIndex":204,"id":"exchange-068"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"管理運営委託料のところですけれども、前年と比べて大きく変動があるところが、１７ページの戸越台特別養護老人ホームとか、大崎在宅サービスセンターなどは移転したからかなという若干の推測はつくのですけれども、委託料が大きく変動しているところは、どういった原因で何がどうなっているのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"ただ、維持管理の考え方は一定していますので、主なものとしては、そういうものは挙げられます。","voiceIndex":206,"id":"exchange-069"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も、時折現場に行ってお話などを伺わせていただくのですけれども、やはり職員の確保がほんとうに難しいと、定着させていくのも難しいということで、先ほどもいろいろお話がありましたけれども、人材確保のところでは、この間、品川区には介護福祉専門学校もありますからというお話もあるのですけれども、今後さらに増えていく高齢者に対しての人材確保というのは、ほんとうに急務だし、課題だと思うのです。","respondent":"永尾高齢者福祉課長","answer":"今後、そういう研修をもう少し工夫して、せっかく資格がある方がいらっしゃいますので、そういう方がまた区内で活躍できるような仕組みを検討していきたいと考えております。","voiceIndex":208,"id":"exchange-070"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"一般質問でもいろいろさせていただいたのですが、そういった大もとの介護そのものを解体していく制度が進んでいけば、品川区の介護福祉もどんどん後退していくのではないか、大変なことになるのではないかと、私は思います。ですので、せめて今の介護報酬で進めていくとか、区が自治体裁量で決めていけるのですから、私は、今までどおりを求めたいと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-071"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"防災のところは、皆さんいろいろ先ほども力を入れているところだとおっしゃっていたので、そういった大もとのマニュアルというものはできているのかどうか。","respondent":"永尾高齢者福祉課長","answer":"ですので、昨年度からやっておりまして、よりよい内容にするということで、継続して検討を続けているところです。","voiceIndex":212,"id":"exchange-072"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"ほんとうに早急に進めていただきたいと思いますので、そこはよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":214,"id":"exchange-073"}]},{"id":"topic-08","title":"その他","agenda":"その他","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"１０月２４日の委員長がご質問された高齢者施策の中で、特別養護老人ホームの入所基準の中で、在宅と施設の関係が、比較的早い時期に変更になるようなご答弁もあったので、その辺の経緯とか、まだ決まっていなければ結構ですけれども、どういう方向になっていくのかとか、その辺を少しお聞かせいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-074"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も、今のたけうち委員と同じところです。入院や入所者に配慮した入所調整をしていくというものが、具体的にどういうことなのかということ。それから、飯沼議員の２３日の特別養護老人ホームの質問のところで、適地は検討していますという旨の答弁だったと思うのですけれども、具体的にどういったところを取り上げて、どう検討されたのか、ちょっと伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3398#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":65594,"voices":227}},{"id":"h26-20141027-8","meetingId":"h26-cm10","date":"2014年10月27日","dateIso":"2014-10-27","committee":"建設委員会","time":"午前１０時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を62件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１「議案審査」を行います。 初めに(1)、第６６号議案、品川区空き家等の適正管理等に関する条例","agenda":"の１「議案審査」を行います。 初めに(1)、第６６号議案、品川区空き家等の適正管理等に関する条例","exchanges":[{"speaker":"あくつ委員","kind":"提案","question":"待望のといいますか、待ちに待った空き家、いわゆるごみ屋敷の対策条例案という形で、今回、本委員会の調査項目になっているということですけれども、提案を大変うれしく思っております。それで、今回調査項目になっているので、逐条的な質問になるところもあると思うのですけれど、若干長くなってしまうことをご了承ください。１点目です。","respondent":"矢木住宅担当課長","answer":"今の委員のご質問につきましては、特定空き家ということで一般的な名称でないので、管理不全状態にある空き家と、要は意味をあらわすような、説明をするということで、もし法案が成立したとしても。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"質問・要望","question":"法律ができたとしても対応はしているという説明だと受け取りました。ただ、後ほどちょっとまた質問しますけれども、どういうものを空き家とするのか基準というところにもかかわるので、また後ほどお伺いしたいと思います。後ほどこれも伺いますが、区民への周知というところにもかかわってくるので、その辺についても伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"委員ご指摘のとおり、空き地等の中に空き家以外の建築物が入ってしまうのは、ちょっと一般的にはどうなのかという考えもあると思うのですが、この区分の趣旨というのは、廃棄物等に起因する管理不全状態と、それ以外の理由での管理不全状態を分けて。","voiceIndex":7,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問","question":"「放置廃棄物に起因する悪臭、ねずみ、害虫等」とあるのですけれども、幾つかほかの自治体の条例を見てみたのですけれども、ネズミという固有名詞で入っているところがあまりなかったものですから、ただ実際、私ども相談を受ける中で、本当にネズミで困っている方はたくさんいらっしゃるので、あえてネズミと入れてくださったことに関してはうれしい気がするのですけれども、逆にそれ以外は考えられないのか。","respondent":"矢木住宅担当課長","answer":"ネズミと規定した他の自治体の条例としては、環境条例のほうで荒川区が入れております。ネズミはあくまで例示でございまして、そのほかということでその他の害獣等も対象となっております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"第３条（区長の責務）のところですけれども、管理不全状態の解消と防止ということがうたわれていますが、解消についてはよくわかるのですけれども、防止について、空き家が管理不全状態になる、また空き地等いわゆるごみ屋敷も含めて、管理不全状態になることの防止ということについてのイメージがなかなか、ちょっとわかりにくいところがあるのですけれど、先ほども若干ご説明があったかもしれませんが。","respondent":"矢木住宅担当課長","answer":"廃棄物等に起因する管理不全状態になることの防止というのは、現在実態調査をしていること自体が防止の一つになり得るかなということと、今後これも方針を立てていきますのでその中で、歩いて行く中で、そんなにひどくはないけれども。","voiceIndex":11,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"第４条第２項で再発防止というところ、先ほど全庁的な対応をということでしたが、これはあまり条例で見たことないのですけれども、いろいろ今までご答弁の中でも出てきているので、片づけても再発してしまうというところ、所管の建設委員会だけでなく、いろいろなところがかかわってくることだと思うのですが、具体的にはどういうものを想定しているのか、教えてください。","respondent":"矢木住宅担当課長","answer":"具体的には、例えばその方の根本的な問題の解決をしなければ、これは繰り返されるという中で、その方とお話をじっくりいたしまして、その方の問題が何なのか、例えば生活に困窮していらっしゃるのか、障害を持たれているのか。","voiceIndex":13,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問","question":"第５条で、これもイメージ的な問題ですけれども、区民の役割で、管理不全状態にならないように近隣の区民等と相互に協力とあるのですけれども、先ほど品川区の住民自治、団体自治の気風に合わせた独特の規定だということで、最近防災のほうでも同じような考え方で、自助・共助・公助とあると思うのですが、共助の観点なのかなと思うのですが、実際にここでは通報ということを指しているのか。","respondent":"矢木住宅担当課長","answer":"もちろん通報というようなことも考えているのですが、通報というのは一方通行的なものでございまして、それだけではなく、やはり地域の課題は地域で解決するという基本のもとに。","voiceIndex":15,"id":"exchange-006"},{"speaker":"あくつ委員","kind":"質問","question":"そういうことで、自分のところがもしかしたらと判断ができるということがあるのですけれども、今回はそういう判断基準というものがないのですけれども、今後そういうものを考えていく想定なのかどうか、まずそういう判断基準というのはどういう基準なのか、それについて伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"区長が諮問する機会といたしましては、この空き家がいわゆる管理不全状態の空き家、ないし廃棄物等に起因する管理不全状態の空き地等であるかないかを認定する、あと管理者等の名称等を公表する、あといよいよ代執行を行う、この３点の場合に区長が諮問をして。","voiceIndex":17,"id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど第１条ですか、この言い回しが、いわゆるごみ屋敷、ごみ屋敷という言葉自体使えるのかどうかということもあると思いますし、またその判断基準をやはり区民に知らせないと、なかなか周知というところでの効果が薄いのかなということがあるのですけれども、そこについてごみ屋敷という表現が果たしてできるのかどうか、ここのところは多分慎重に、人権問題も絡んでくると思うのですけれど。","respondent":"矢木住宅担当課長","answer":"いずれにいたしましても、４月１日に条例を施行予定ですので、その間に基準でありますとか、ＰＲを含めまして、今後速やかに決定して周知してまいりたいと考えています。","voiceIndex":19,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問・要望","question":"まとめて言ってしまいます。第１２条（代執行）ですが、これは非常に重要なところで、名古屋市は議員条例にもかかわらずこれを入れなかったということで、それはいろいろな判断があったと思うのですけれど、区として、部長の答弁でもいろいろな、強い思いというのを伺ったのですけれど改めて、代執行を入れ込んだという意図、目的、その強い意志というか、そこのところを確認させてください。","respondent":"矢木住宅担当課長","answer":"第１０条第２項につきましては、委員ご指摘のとおり、また具体的な事案によって何を緊急に行うかは別といたしましても、例えばネットを張るということですとか、最低限の措置をとるということでご理解いただければと思います。","voiceIndex":21,"id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"委員会としても代執行を入れてほしいということは申し上げてきたところですけれども、これは非常に効果的な、名古屋市でも所有者からの取り合わせが、条例を施行することによって増えたり、気にする方が増えたと。先ほども何度か申し上げたのですが、適正に管理するために必要な支援というところで、先ほど例示もちょっとあったと思うのですが、もう一度その具体的なイメージを教えていただきたいと思います。","respondent":"矢木住宅担当課長","answer":"ごみを一旦撤去したとしても、やはり根本的な問題を解決しなければ、その方の問題を解決しなければ根本的な解決に至らないので、そういったことを福祉的な観点からも丁寧にお聞きして、対応を考えさせていただきたいと、そういうことです。","voiceIndex":23,"id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"一旦終わりますけれども、ほかの委員のご質問も聞いて、またつけ加えるところがあれば質問させていただきたいと思います。ただ本当に、先ほどもありましたけれども、今までもやってこられたというところで、４月１日施行だからといって、それまで何もやらないということではなくて、今でも相談とか調査とか、そういったものもしっかりやっていただきたいと思いますので、一応私からは終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第５条（区民等の役割）ということで、先ほど通報以外にもいろいろ、地域の方の力をかりて解決していくという話がありましたけれども、これからのことなので、現状においても町会とか自治会の協力をかなりいただきながら、なかなか苦慮して先に進まないというところなのですけれども、その辺は地域の方々とともに前に進むようなことをいろいろつくっていく、仕組みと言えるかどうかわかりませんが。","respondent":"矢木住宅担当課長","answer":"第１１条（公表）ですが、一般的には公示のような、区役所前に氏名を公表するということがありますが、今後のまた検討ですが、やはりホームページ、広報誌等も場合によっては媒体として利用することも検討してまいりたいと思います。今後の検討課題にさせてください。","voiceIndex":26,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"第５条（区民等の役割）ということは、また新たな仕組みということで、なかなか地域の方の協力を得ないと進んでいかないというところにおいては、現状においても町会、自治会はすごく大変な中で、さまざまな事業にご協力いただいているので、そういう点は十分地域の方のお声を聞いて進めていただきたいと要望します。そういった面で人的な問題はどうしていくのか、その辺も含めて教えてください。","respondent":"矢木住宅担当課長","answer":"これにつきましては、当然のことながら課長級職員が一つひとつに対応していくということは、時間的にも能力的にも合理的ではないということが多々ありますので、今後、実務者レベルのケース診断会議的な機関も設置予定です。","voiceIndex":28,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つ、審議会のメンバーを具体的に教えていただきたいのが一つ。優先順位的に区の側が求める事業なのか、地域の住民の方の願いを実現するためのものなのか、この「区が実施する事業への協力を求めることができる」という一文はとても違和感があるのですけれども、このところの基準はどのように考えているのか、教えてください。","respondent":"矢木住宅担当課長","answer":"第１４条（有効活用）につきまして、「区が実施する事業への協力を求めることができる」ということですが、もちろん区が実施する事業というのは、私どもが勝手に考えてやるものではございません。","voiceIndex":30,"id":"exchange-014"},{"speaker":"飯沼委員","kind":"質問・要望","question":"現状においても十分地域の方の意見を聞いて進めていくのだったら、「区が実施する事業への協力を求めることができる」といった文言をわざわざ入れなくても、現状で十分できると思うのですね。開発地域。そういった意味で、私たちはここはなくても十分、空き家といわゆるごみ屋敷問題の解決は、ほかの条文で十分できるのではないか、ここは要らないのではないかと思っているのですけれど。","respondent":"矢木住宅担当課長、藤田都市環境事業部長","answer":"今後の有効活用策につきましては、具体的にはいろいろなメニューがあります、他区市町村で先行自治体もありますので、その辺を調査、研究しながら、既存の事業とも整理した上で、施策を打っていきたいと考えています。ですので、民から民への部分との区分けという意味でも、区が実施する事業の協力という形になっております。","voiceIndex":32,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"意見","question":"そこを力入れていきたいという気持ちはわかるのですけれども、だからといってこういう文言を入れていくことで解決するのかといったら、しないと思うのですね、現状。今回つくるので、もちろん空き家とかいわゆるごみ屋敷を解決はしてほしいけれども、一緒くたにしてあれもこれもと入れてしまうことで、私はとてもここに疑問が残って、払拭できないのです。","respondent":"藤田都市環境事業部長","answer":"そのためには、この条例をつくる中で、支援ですとか有効活用ですとか、そういうメニューを打ち出すことで、あるいはこの後規則等でしっかりその中身を定めていくことで、地域にお住まいの方々、空き家にしてしまっている人たちについても。","voiceIndex":35,"id":"exchange-016"},{"speaker":"原委員","kind":"質問","question":"ほかの委員からも出ていますように、私は早く条例化には、当然賛成です。全体といたしましては。その中でちょっと気になる点が幾つかあります。目的、定義はわかったのですけれども、その中の用語の位置づけがちょっと甘いのかなというところで、第２条第５号の、所有者等についてもう一度説明いただけますでしょうか。","respondent":"矢木住宅担当課長","answer":"所有者等ということで、「空き家または空き地等を所有し、占有し、または管理する者」ということで、所有者、占有者、管理会社、そういったものを想定しています。","voiceIndex":37,"id":"exchange-017"},{"speaker":"原委員","kind":"質問","question":"そのままですね、定義ですから。というのは、今までほかの委員との会話の中でずっと出てきたのは、所有者がはっきりしている場合であって、いわゆるごみ屋敷ですか、所有者がわからないとか、わかってはいるのだけれども手が出せない、または表現が適切かどうかわかりませんが、わかってはいるのだけれども手を出してはいけない案件も、出てくる可能性があるのではないかなと私は思うのです。","respondent":"矢木住宅担当課長","answer":"現時点で１,０００件ほど調査中のものがありますので、それは空き家を主にしておりますが、今後もその件数は増えていくと判断しております。ただ、所有者がはっきりしないかどうかは、今後の結果次第ということになります。","voiceIndex":39,"id":"exchange-018"},{"speaker":"原委員","kind":"質問","question":"以前の委員会の中で質問させていただいたと思うのですけれども、やはりどこまで区として調べに入っていくのか、法務局にあればそれでいいのか、公信力の問題はこの前も話したと思うのですけれども、そうではないケース、ですからあまり入り過ぎてしまって、一言で言っちゃいますと税金を無駄遣いにしていいのかどうかという、この辺についてのお考えが一点。お願いします。","respondent":"矢木住宅担当課長","answer":"ただ当然のことながら、解決し得ない問題というのも出てくることは認識しております。","voiceIndex":41,"id":"exchange-019"},{"speaker":"原委員","kind":"質問・要望","question":"第１４条の「区が実施する事業への協力を求めることができる」、これですけれども、私も地域といろいろな活動に携わっている中で、やはり先ほども質問がありましたけれど、協力を求めるという義務規定までは行かないですけれど、逆に区民に区が協力をしていきますというような文言でないと、このまま行くということであれば、そういうお考えもあるのでしょうということですけれど、私自身はなかなか。","respondent":"矢木住宅担当課長","answer":"先ほど申し上げましたように区が実施する事業については、区民の方のご意見を十分拝聴しながら進めていくわけではありますが、この活用規定を設けたことによりまして、これまでの問題、課題もありますが、今後空き家になりそうなおうちをお持ちの方に。","voiceIndex":43,"id":"exchange-020"},{"speaker":"原委員","kind":"質問","question":"第１４条につきまして、後段の部分は担当課長にご説明いただいたとおりだと思います。ですが、できれば、この表現も適切かどうかわかりませんけれども、霞が関の文言のようにはなってほしくないなという思いがありますので、入れたことによって区民がマイナスになるという方向にならないようにだけお願いをして、質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":45,"id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"もう皆聞いたので一つだけ、第７条第３項の犯罪捜査のために認められたものということで、警察だったり、税務署だったりするのでしょうけれども、これを認める主体は、警察とか税務署とか、そういうところでよいということですか。教えてください。","respondent":"矢木住宅担当課長","answer":"ですので、令状なしに犯罪捜査ができるというふうに解釈してはいけませんと、そういう意味合いです。","voiceIndex":46,"id":"exchange-022"},{"speaker":"大沢委員","kind":"確認","question":"だからここは、認める主体というのは税務署だったり警察だったりですよねということを確認するための質問をさせていただいたので、それでよろしいかどうか。","respondent":"藤田都市環境事業部長","answer":"今回のこの立ち入り調査は、空き家が適正な管理をなされているかどうかを区が判断するために、区として立ち入り調査をするものですので、全く別なものであります。ですから犯罪調査を行うような警察のほうが、この立ち入り調査をしてもいいというようなものではございません。","voiceIndex":48,"id":"exchange-023"},{"speaker":"大沢委員","kind":"意見","question":"先ほどご答弁いただいたときに、この文言というのは決まり文句のようなものですということでご答弁いただいたかに私、聞き覚えをしているのですけれども、ここまでお話があって、課長にご答弁いただいて、部長がご答弁いただいて、この文言を入れるのはただ単に決まり文句だから入れましたというご答弁は、適切なご答弁ではないように思うのですけれど、そこのところはどういうふうに思われますか。","respondent":"藤田都市環境事業部長","answer":"先ほどもちょっとお話の中でありましたけれども、私たちは適正な管理がなされているかどうかということが目的に入っていますので、そこの中で得た情報がそのまま犯罪捜査のための証拠物件となるような形には、なってはいけないものと考えています。","voiceIndex":50,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"言葉の云々かんぬんという、これは一つの例としてお話をしましたけれど、先ほど来２回か３回、テクニカルという部分があって、まさにこの条例というのは、私の財産に公の権力で手を入れられるような状態になるわけですから、先ほどの財産権の侵害にならぬようにしっかりとやっていきたいというようなご答弁もいただきました。","respondent":"矢木住宅担当課長","answer":"この立ち入り調査の中での第３項、犯罪捜査のために認められたもの、先ほど勘違いいたしまして税金の関係のほうのことも言ってしまったのですが、原理原則に戻しますと、犯罪捜査には捜索令状が必要でございまして、これは裁判所等が出すものと思いますが。","voiceIndex":52,"id":"exchange-025"},{"speaker":"大沢委員","kind":"質問・要望","question":"つくるご苦労を考えれば、ああだこうだ物申すこともちょっと申しわけない気もするのですけれど、要は何が言いたいかというと、ここで各委員がいろいろなことを聞いている、条例なりこういうもろもろの規定というのは１０人は１０人、１００人は１００人の判断の仕方があるがゆえに、やはりそこのところを、先ほど確かにテンポよくご答弁いただいたのですけれども。","respondent":"矢木住宅担当課長","answer":"区役所前の掲示板という公示場所がありますので、そちらのほうでの公示をメインに考えております。これはどのような場合に公表するのかという具体的な内容につきましては、今後また検討事項とさせていただきたいと思います。","voiceIndex":54,"id":"exchange-026"},{"speaker":"大沢委員","kind":"質問","question":"今、どのような場合に公表するかということですが、一応この１号から４号ということで場合は想定されているのですけれど、このほかにも場合がある、これは「その他区長が必要と認める事項」ということで、含みと解釈していいでしょうか。教えてください。","respondent":"矢木住宅担当課長","answer":"原則的には、委員ご指摘のとおりでよろしいかと思います。","voiceIndex":56,"id":"exchange-027"},{"speaker":"大沢委員","kind":"質問","question":"例外があるのであれば、この原則、１号、２号、３号、４号とありますけれども、あくまでも原則で例外があるのを想定しているのであれば、例外事項が審議できる、あるいは何か話ができるような規定というのを盛り込まなければいけないと思うのですが、それは条例の作成上、通例必要ないのでしょうか。","respondent":"藤田都市環境事業部長","answer":"先ほど公表はこういう場合というお話と、公表する事項のお話と、ちょっと一緒になってしまったかなと考えています。","voiceIndex":58,"id":"exchange-028"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはりごみ屋敷の文言ですよね。廃棄物等に起因する管理不全状態にある「空き地等」、この「等」であらわしているというのですけれど、やはりこの辺のところが、廃棄物等に起因する管理不全状態にある「空き家等」ならわかるのですけれど、何で「空き地等」になっているのか、ここをもう一度お知らせいただきたいと思います。","respondent":"矢木住宅担当課長、藤田都市環境事業部長","answer":"「空き地等」は廃棄物に起因する管理不全状態、具体的に言えば空き地に、これは廃棄物という範疇なのかということもあるかもしれないですが、例えば雑草が繁茂している状態であるとか。ただ、今お話があったとおり、じゃあ、これからこれをどういうふうに区民の方々にお知らせしていくかというときは、条例上の文言の整理の話と、わかりやすさという面と、二つあると思いますので、わかりやすい説明についてはもう少し。","voiceIndex":60,"id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"そこをどうしてもらえるのか。一番いいのは、買い取って何かつくって、何年かしたら、１０年過ぎたら隣近所に売却するとか、そういうような形にしていけば、実際にこの条例の趣旨が生きていって、これがなくなっていくかなと思うのですけれど、そこまで考えていかなくてはいけないと思うのですけれど、そういうようなお考えはあるのでしょうか。","respondent":"藤田都市環境事業部長","answer":"現在も都からいろいろな情報をいただいておりますけれども、そういう中でこれからもう少し、今は既存の枠の中ではそういう制度が私どもはありませんので、それをどういう形でやっていくのがご本人にとっていいのか、それについてはいろいろ研究をしてまいりたいと考えています。","voiceIndex":63,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"先ほどの第１４条の有効活用のところですけれども、区の姿勢によっては、まちづくりにおいて開発地域の中に含まれる空き家を更地にするとか、特定整備路線などの道路上にある空き家を更地にしていくといった、まちづくりの事業を推進するための一つのツールにしていく、誘導していくといったことに捉えられるのですけれども、そこのところを、私はここが払拭できていないので、再度お伺いしたいです。","respondent":"中村都市計画課長、溝口都市開発課長","answer":"ただし特定整備路線上に沿った近隣周辺に迷惑がかかるような空き家があった場合には、これは適正な判断のもとに行っていくと、これは意味合いとしては、特定整備路線だからということではないというふうに考えてあります。決して、今回の空き家があるからといって再開発事業を進めていくというものではありません。","voiceIndex":65,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった意味では、だから当初の空き家を有効活用していきたい、地域の人が求めているものに転用できないかという当初の目的においては、ここの文言がなくても現状においてもお互いに、支援とかもあるので努力を重ねていけば、この文言を入れることなく私はできると思うのですよ。道路とかにするものではないというお話がありましたけれども、それに利用していく方向にもとれる中身だと思っているのです。","respondent":"藤田都市環境事業部長","answer":"それを区長が有効活用として何ができるかというふうに考えたときには、区長がその民と民の間に入って、何らかの形でつないであげるための施策、それは区としてはやはり、これからまさに進めようと思っている事業に協力していただける、例えば地域の町会で、町会会館がないので。","voiceIndex":68,"id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"解決をしていくための条例というのは本当に求められていると思いますが、でも先ほどから第１４条（有効活用）のところ、やはりここの文言は要らないと思っています。再三ご説明をいただいた有効活用に関してはこの第１４条がなくても、区の努力、また住民の方々の合意を得るといった話し合いは、現状でも十分できます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-033"}]},{"id":"topic-02","title":"第５６号議案、平成２６年度品川区一般会計補正予算（歳出 建設委員会所管分）","agenda":"第５６号議案、平成２６年度品川区一般会計補正予算（歳出 建設委員会所管分）","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"３９ページの財源更正のところですが、「職員給与費に対する諸収入増額に伴い」というところがよくわからないです。先ほど排水施設とおっしゃいましたが、もうちょっと詳しく、どういう収入になっているのかを具体的に教えていただきたいのと、４１ページもちょっと、この工事費が増額されたのはどういう工事にお金がかかるのかという、具体的に教えてください。","respondent":"奥田河川下水道課長","answer":"発進立坑の区民公園の工事をやっておりますときに地下水脈があって、水があふれてくるということがございまして、到達側の大森貝塚遺跡庭園のところの立坑を掘るときに、止水性にすぐれた工法ということで、工法を変更したことで増額となっています。","voiceIndex":84,"id":"exchange-034"}]},{"id":"topic-03","title":"都市計画区域の整備、開発および保全の方針・防災街区整備方針","agenda":"都市計画区域の整備、開発および保全の方針・防災街区整備方針","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"そのことを受けて、品川区の今後がどう変化して、まちづくり、都市づくりでどんな問題点をはらんでいると捉えているのか、１枚で簡単に報告はされたのですけれども、品川のまちが大きく変わっていくと思うのですが、その点をどう捉え、問題点をどう思っていらっしゃるのかというところをちょっとお聞かせください。","respondent":"中村都市計画課長","answer":"この方針の将来像ですけれども、ここではおおむね１０年、２０２５年までを見据えた計画としています。これは知事が替わったということとは直接は連動しておりません。","voiceIndex":102,"id":"exchange-035"},{"speaker":"飯沼委員","kind":"提案","question":"大きな地球規模の問題では、地球の温暖化とヒートアイランド現象、これは確実に激化をしていて、本当に地球規模で解決をしなくてはいけないというところにおいては、東京都が進めるから一緒に進めていっていいものか、その辺は一緒に考え、立ちどまって提案をしていかなくてはいけないのではないかと思うのですけれども、その辺の都市再生。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"最初のご質問、都の言いなりですけれど、また一極集中ということでございまして、全国的に見れば東京に一極集中というところ、これはちょっと私としてもコメントがなかなか難しいところですけれども、少なくとも品川区におきましては。その中では、まちづくりをどんどんどんどん進めていくというだけでなく、右側の第４のところの５番、６番にありますとおり、都市の低炭素化、自然的環境というようなことで、緑の計画だとか環境の施策等についても。","voiceIndex":104,"id":"exchange-036"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはりさまざまな問題点を改善しながらまちをつくっていく、だから問題というのは地域にいっぱいあるわけですよね。そういった面で、問題意識をどう持っているのかというのをぜひお伺いしたい。その辺、やはり改めていただきたい。総合的と言うならば、燃えない、倒れない家づくりのところをもっと真剣に、地域の方の声を聞いて、実現をしていただきたいと思うのですが、この２点お答えください。","respondent":"中村都市計画課長、藤田都市環境事業部長","answer":"先ほど委員のご質問にもございました保育所ですとか、あるいは高齢者施設等、そういったものの整備ということもありますけれども、そういったまちづくりにつきましては。それから東京都が行っている特定整備路線についても、連携しながら、少しでも早く安全、安心なまちにできるように努めていきたいと考えています。","voiceIndex":107,"id":"exchange-037"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから燃え広がらない道路以前に、燃えないまちの対策という、これがやはり予防対策だし、国でもそこのところを強調していますよね。だからそこをぜひ、いつまでも固い頭でいないで、切り替えていただきたいと思います。そういった意味では、道路とビルばかりのまちづくりにもう反省をしなくてはいけない時点になっていると、私たちは強く強くこれからも求めていきます。ここは意見で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-038"}]},{"id":"topic-04","title":"の(3)、東京都市計画道路都市高速道路第１号線・湾岸線","agenda":"の(3)、東京都市計画道路都市高速道路第１号線・湾岸線","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"もちろん騒音に関しては配慮をしていただきたいという意見を、言ってくださいという意味での質問ですけれども。それと、たしか６,３００億円ぐらいの大規模修繕であるというようなご説明がそのときあったと思うのですが、工事の期間の予定というか、完成の時期も含めて教えてください。","respondent":"中村都市計画課長","answer":"首都高速道路株式会社では、最近では車が通過する音を軽減するといった舗装材があるということ、それから防音壁といったものを必要に応じて採用していくことを検討していくというふうに説明会の中で回答したということで、区のほうでも確認しています。","voiceIndex":117,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問","question":"都市計画審議会ではアセスメントをしないというご説明でしたが、そこをもう一度伺いたいと思います。","respondent":"中村都市計画課長","answer":"環境アセスメントにつきましては、道路が２車線ということで、車線数について変更がないということで、環境アセスメントの対象外です。","voiceIndex":119,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問・要望","question":"その都市計画審議会の中でも意見が出ましたけれども、１０年間にわたって工事があって、工事の上での騒音も心配なのですけれども、これは多分、工事の説明会等あると思いますが、道路自体が高くなることによって騒音の問題が大きくなるのか、小さくなるのか、ちょっとそこは私もはっきりわからないのですけれども、それはしっかり、特に東品川の皆様、東大井の方も入るでしょうが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":121,"id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そういった面で、高くなっていくことでの騒音問題、今、新しい技術というご答弁をいただいたのですが、その範囲で大丈夫なのか、トンネルとか防音壁とか、どうなのだろうかという意見も出ているので、具体的にわかったらそこもお答えいただきたいと思います。","respondent":"中村都市計画課長","answer":"今後この首都高速道路株式会社でも、遮音壁ですとか、あるいは高機能舗装という騒音が低減されるような舗装などの対策を検討していくということで、今後使用する材料等の詳細が決まる中で、この騒音等に対する影響につきましては首都高に対しまして可能な限り。","voiceIndex":122,"id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問","question":"今、既存の騒音が５７から６８デシベルということですけれども、この測定箇所はどうなのですか。結局周辺の方は、いろいろな条件によって騒音が広がって響いていくという状況なのですけれども、この６月２７日と２９日の説明会の範囲というのは、どこまでだったのですか。そういうままでよろしいのかと思うのですが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"今現在、具体的な説明の範囲については把握してございませんけれども、この道路に面したところには、少なくとも影響のある範囲については説明会の範囲と設定しているということになったと思います。","voiceIndex":124,"id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一通りの説明はされたのかと思いますけれども、首都高の説明ですけれども、区としてはやはり、区民の皆さんにちゃんと中身が届くような手だてをしっかりと求めていただきたいと思いますし、最新の技術で騒音を軽減する、それは当たり前のことですけれども、やはり具体的に区民の皆さんから問い合わせがあったときに答えられるように、ある程度しっかりと聞いておいていただきたいし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-044"}]},{"id":"topic-05","title":"第２回地域交通検討会開催の状況","agenda":"第２回地域交通検討会開催の状況","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"私からは１点だけ。まさにこの議題2)についてもされておりますけれども、第１回のとき、交通不便地域のことについて、７００メートルであるとか、５００メートルであるとか、というようなお話もあったと思うのですけれども、これはまた今後の検討課題なのかなと思うのですが、どういう形でそういうものが検討されていくのか、議題の選定ですね、どういう形でやられているのか、ちょっと教えてください。","respondent":"中村都市計画課長","answer":"交通不便地域の対応ですけれども、こちらにつきましては今、いろいろな調査の方法もあったり、あるいは区民の意向も調査するというような案もありますけれども、現在第１回目の検討会の中で、コミュニティバスにつきましては時期尚早だとか。","voiceIndex":132,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"今、事業者と一緒に協力体制でやっていきたいというご答弁でしたけれども、これは交通検討会の中で俎上に上げていくという、今後そういうことでよろしいのでしょうか。","respondent":"中村都市計画課長","answer":"今現在、このバス事業者への働きかけだとか、そのほか新たな交通手段などはないだろうか、こういったものを研究している段階ですので、また必要に応じてということになるかと思います。","voiceIndex":134,"id":"exchange-046"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私もインターネットで第１回の資料を見させていただいたのですが、改めてこの交通検討会の目的を教えていただきたい。参加者の中からもあまり明確ではないというような意見を出されていたと思うのですが、改めてこの開催の目的をお知らせください。","respondent":"中村都市計画課長","answer":"交通環境につきましてはさまざまな課題がありますので、そういったものを一つひとつ検討していければと考えています。","voiceIndex":136,"id":"exchange-047"},{"speaker":"飯沼委員","kind":"提案","question":"そういった意味で今、交通事業者の方たちにいろいろルートなども、バスとかタクシーの活用などを求めていくのか、出してもらうのか、これから議論されると思うのですけれど、具体的にこの困難地域を解決していくために、バス事業者に区の側から提案しているような、例えばここの地域を通すようなことは考えられないかとか、具体的に提案しているようなことがあるのかどうか。","respondent":"中村都市計画課長、若林委員長","answer":"この中で今後、バス事業者あるいはタクシー事業者につきましても、区のほうから新たな提案というよりも、まずはそれぞれの事業者からの提案、こういったものも区としては検討するというところで、検討を進めてまいりたいと考えています。飯沼委員、今回は第２回の検討会の開催状況についての質疑になりますので、それを踏まえてお願いします。","voiceIndex":138,"id":"exchange-048"},{"speaker":"飯沼委員","kind":"提案","question":"第２回の報告ですけれども、流れがあるのと、何を目的にして到達していくのか今後もありますよね。そういったところで実際に事業者のほうから提案がないとき、そういった問題点を区はどう捉えて解決していくのかというところが、区民の側としてはとても関心が高いので、そこのお考えをお聞きするためです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-049"},{"speaker":"松澤委員","kind":"質問・要望","question":"委員長、議事進行について。今、コミュニティバスなど、第１回目の話が出ていますけれども、私たちはそれに対する資料がございませんので、その件について質問されるのはちょっと困るのですよね。我々は討議しようがないので。報告事項ですので。お願いいたします。","respondent":"若林委員長","answer":"そのような方向で進めていただきたいと思います。","voiceIndex":142,"id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"でも、委員長、第２回目も実際に資料がない、これだけですよね、報告の中身が。実際に地域交通検討会というのがどう行われているのかという中身に対して、私たちは地域からいろいろ声をいただいているわけです。事前に資料が出ていないから、わからないというのは当然ですよ。でも資料があって問題点を指摘しているのですから、それはそれでとめることはないと思いますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問・要望","question":"だから私は、今後の方向性についてお伺いいたしましたので、お答えいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-052"},{"speaker":"飯沼委員","kind":"質問","question":"流れの中での質問ですもの。狭くしないでください。","respondent":"中村都市計画課長","answer":"今後のバス事業者への働きかけですが、やはり区のほうから働きかける必要があると考えております。必要な研究などを踏まえて、バス事業者あるいはタクシー事業者に働きかけを行っていくという、先ほどと同じ答弁になります。","voiceIndex":148,"id":"exchange-053"}]},{"id":"topic-06","title":"平成２５年度指定管理者による管理に関するモニタリング・評価","agenda":"平成２５年度指定管理者による管理に関するモニタリング・評価","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"品川宅建管理センターから伺いますけれど、真ん中の表のところに滞納者１件当たりの対応回数というのが書かれていますが、先ほどご説明で１カ月目から早目に対応をするように指導していますと、その点は前回のときもお願いしたので、重傷にならないうちに早くから対応して、いろいろ手だてをとっていただきたいというところでは、行ってお声をかけて指導してくださるということでありがたいと思うのですが。","respondent":"矢木住宅担当課長","answer":"正直言いまして昨年度は、西中延区営住宅の建て替えに伴う仮移転という問題がございまして、この辺の丁寧な対応をしたという関係で、専従管理者４人の時間がある程度とられてしまったというところもあります。","voiceIndex":156,"id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"自転車駐車場ですけれども、表面の自転車定期利用と当日利用のパーセンテージが出ているのですけれども、場所によっては当日利用が少なくて不足しているとか、そういうのがあると思うのですが、なかなかこのパーセンテージだけでは読み取れないところがあるのですが、その辺の問題はどういうところに出ているのか、また改善はどうなのかというのをお知らせいただきたいと思います。","respondent":"田口交通安全担当課長","answer":"ＮＣＤとも協議を今後進めていきたいと考えております。","voiceIndex":158,"id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問・要望","question":"シルバーとの関係はわかりました。働いていらっしゃる方々の福利厚生などは、ぜひ雇用の問題なので、向こうの問題とせず、やはりよりよい環境で働いていただくこと、賃金のこととか時給のこととか、なかなか把握をするところではないとおっしゃるかとも思いますけれども、よりよい環境で続けて仕事をしていただけるように、ぜひ目配りをしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-056"},{"speaker":"松澤委員","kind":"質問","question":"住宅のほうですけれど、滞納者の訴訟ということで、ここのところ訴訟が結構あったのですけれども、今現在、訴訟になりそうな長期滞納者というのはどれぐらいいるのですか。この数字は捉えていますか。","respondent":"矢木住宅担当課長","answer":"それで強制執行を最近実施したのが１件あります。それ以外の件数につきましては、若干はありますが、極力訴訟に移行しない形で、まず速やかに自主退去というのが、時間的にもコスト的にも一番いいことなので、それに向けて鋭意努力をしている最中です。","voiceIndex":161,"id":"exchange-057"},{"speaker":"原委員","kind":"質問・要望","question":"ただ、今ご説明があったように７４人ですか、管理者によって大分その度合いが違うということがあるものですから、そこの点だけ、やはり何でも人なのでしょうけれども、その辺を一言いただければと思います。続けて質問します。片方はブロックになっているし、片方はばらばらになっているし。ですから、その辺のところまでお聞きしたいものですから、先にそこまで質問をします。","respondent":"田口交通安全担当課長、矢木住宅担当課長","answer":"そういったことをやりながら、今後もマナーアップに努めていきたいと考えております。経営会議における検討結果が同じですが、改善はしているのですが、やはり滞納額、特に退去者の滞納のほうがいまだ回収が進んでいないという中で、大きな視点のもとで同じようなコメントになったものというふうに理解しております。","voiceIndex":163,"id":"exchange-058"},{"speaker":"原委員","kind":"質問・要望","question":"要は管理されているその方よりも、社の方のほうが区民の方に対して非常にいい接し方をされていたので、今後ともトレーニングのほうをしっかり徹底させてください。これはお願い事です。ですから経営会議のときに、多分いろいろ具体的なことも上がってこようかと思いますので、それを要は専門職、言ってしまえば弁護士とかに行くような形にならないように運んでいただきたいのですね。","respondent":"矢木住宅担当課長","answer":"その方々を早く見つけて、丁寧に生活状況をお聞きして、できることであれば生活再建なりのサポートをいたしまして、退去していただくなり、その他の手だてを一緒に考えするなり、丁寧な対応を心がけて信頼関係を築いて、なるべく早く自主的に退去していただいて。","voiceIndex":166,"id":"exchange-059"},{"speaker":"大沢委員","kind":"質問・要望","question":"この使用料のところで、区営住宅、区民住宅とファミーユ西五反田ですけれども、区営住宅、区民住宅の総戸数が事務事業概要の平成２６年４月現在で１,４７７、それでファミーユ西五反田の東西をカウントすると４９８と、使用料の安い、高いはあるのですけれど、にもかかわらず使用料が同じぐらいの金額に落ち着いて、戸数は圧倒的に離れているのですけれど、これはどういう処理によるものなのでしょうか。","respondent":"矢木住宅担当課長","answer":"こちらは区営住宅のほうがかなりお安いというか、生活困窮者のための住宅ですので、この関係で戸数にかかわらず使用料のほうが同額に近い金額になっているものです。","voiceIndex":168,"id":"exchange-060"},{"speaker":"大沢委員","kind":"質問","question":"たまたまこれが同額になってしまったのか、それともある程度釣り合いをとるべく……、要は戸数にしてみれば４９８と１,４７７で、約９００戸ぐらい違うのですけれども。同じぐらいになるような設定なのですか。","respondent":"矢木住宅担当課長","answer":"委員のご質問もごもっともでございまして、私も見てびっくりしたところではありますが、まず区営住宅は先ほども申し上げたように低廉な使用料であるということと、全ての区民住宅において所得に応じまして５段階に使用料が減額していくという制度があります。","voiceIndex":170,"id":"exchange-061"}]},{"id":"topic-07","title":"の３、「その他」","agenda":"の３、「その他」","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"ＪＲ東海の説明ですけれども、この説明会の周知はどのようにされているのか、品川区にはこういう情報提供とかがあったわけですけれども、わかったら教えてください。ほかで説明をされているのかどうか。","respondent":"中村都市計画課長","answer":"ホームページの掲載、それから実際にこのビラの配布をなされていると伺ってあります。ただ、その範囲につきましては、情報をつかんでございません。","voiceIndex":186,"id":"exchange-062"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4120#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":57709,"voices":189}},{"id":"h26-20141027-9","meetingId":"h26-cm10","date":"2014年10月27日","dateIso":"2014-10-27","committee":"文教委員会","time":"午前１０時００分～午後 １時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の第６０号議案 品川区女性福祉資金貸付条例の一部を改正する条例","agenda":"の第６０号議案 品川区女性福祉資金貸付条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"この女性福祉資金貸付金というものの活用状況、利用実態というか、それをちょっと教えていただきたいというのが１点です。父子家庭を対象にするべきではないかとちょっと思っているのですけれども、その辺についてここの内容、女性福祉資金、条例のタイトルがそういうあれなので、その関係でどういうふうに理解したらいいのかというのを教えていただきたいというのが２つ目です。","respondent":"伊崎子育て支援課長","answer":"ただ、父子福祉資金は別途ありますので、父子家庭は対象となっております。それから、説明資料ですが、そういったことで特に条例の内容、目的、定義等に変更があったわけではございませんので、今回説明資料はご用意いたしませんでした。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"資料については法律の改正だけだということなのだけれども、それはここに書いてあるのですが、この条例改正が本当に区民にとって条例改正の文言だけでいいのかどうかというところを確認する上で、説明資料というのがなかったために非常に私としては苦労したというのがちょっとあったので、いただけたらありがたかったかなと思いますので、それはこれからのことも含めてお願いをさせていただきたいと思います。","respondent":"伊崎子育て支援課長","answer":"成り立ちから申し上げますと、そもそもは女性の売春防止法の関係から転じまして女性の生活の転落を阻止するためにということで現在も継続しているものです。ですので、社会的に厳しい状況に置かれることが多々ある女性世帯への支援ということでの女性福祉資金です。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"東京都との関係はわかりました。そういうふうに整備しているというところはわかりました。ちょっと今の利用実績で、通常の年は１桁で平成２５年度は３２件と、ごめんなさい、これがちょっとよくわからない……。","respondent":"伊崎子育て支援課長","answer":"すみません、言葉が足りませんで失礼いたしました。先ほどは、平成２５年度末の貸し付け件数が３２件とご説明いたしました。平成２５年度の末の時点で区が債権を持っている件数が３２件で、それまでに貸し付けをしていて貸し付けが継続している数が３２件という意味です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"意見","question":"私が聞いたのは、この間の利用実績ということで、トータルではなくて毎年毎年の状況を知りたかったので、私の言葉が足りなかったのかもしれないけれども、ちょっとそういうことで聞きたかったので、３２件で平成２６年度は半年たって１件というのは大きな落差があるなという理解をして、１桁との関係でわからなくなってしまったので聞いたのですけれども、そういうつもりだったので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-004"},{"speaker":"つる委員","kind":"質問","question":"１点だけ教えてください。今の議論の中でも言葉として出てきた東京都の父子福祉資金制度なのですが、１０月１日からスタートということで、品川区のホームページとしては１０月７日更新でホームページで周知されているようですけれども、最近窓口に行ってないのでわからないのですが、東京都でつくっているチラシだとかが窓口に置いてあるのか、その辺の周知方法を１点だけ教えてください。","respondent":"伊崎子育て支援課長","answer":"ただ、チラシなのですが、東京都からまだこういった非常に簡単な、「始まります」というものしかできてきておりませんで、中身が入っております、こちらが東京都母子福祉資金なのですが、これは今作成中ということで。","voiceIndex":12,"id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"今までの保育園のずっと前からの経過では地域の名前を冠したりしているのが中心なのですけれども、今までどおりにしてきていない理由というのがあれば教えていただきたいと思います。それから、この五反田第二保育園というのは区立保育園として設置する保育園としては最後になるのかどうか、ちょっとそのあたりを確認したいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"私ども五反田第二保育園、今最後の品川区立の保育園かというお尋ねでございましたが、ここまでも種々答弁しておりますとおり、今後も公私立認可保育園につきましては、保育需要や人口動向などを鑑みまして引き続き開設していく考えに変わりはございません。","voiceIndex":31,"id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"それと、今後も認可保育園はつくるという話なのですが、区立としてつくっていく保育園としてはこれが最後であってほしくないという思いがあるので、その辺を確認しておきたいと思いますので、再度同じような角度なのですが、教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"繰り返しのご説明になって恐縮なのですけれども、第二保育園につきましては、やはり五反田地域に２つ目という意味で第二とつけております。","voiceIndex":33,"id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"第二のほうなのですが、保育需要を見つけてつけるということで、１つの地域に２つ目ということなのだけれども、では例えば保育需要が低下したときにはどうなるのかというのはちょっと気になるので、その辺を確認をしておきたいと思うのですね。保育需要との関係で地域につくったと。その辺をちょっと確認したいです。聞いている趣旨を受け止めて答弁していただきたいと思います。","respondent":"金子子ども未来事業部長","answer":"これについては、公立あるいは私立、これだけを建てていくのだ、開設していくのだというのは最初から持っているわけはありませんで、あくまでも総合的に検討して総合的に展開していく、このようにご理解をいただきたいと思います。","voiceIndex":35,"id":"exchange-008"},{"speaker":"南委員","kind":"質問・要望","question":"今年は、さきの本会議で私たちが質問したら、１０月１日時点で申請数が去年より２９１人上回っているということなのですよね。しかし、そのことについては答えずに、私立もやるのだ、総合的展開だと、今までの路線だからそれではだめだということを思っていて確認を、きちんと区立でつくるべきだということを、ちょっと区の姿勢として示していただきたいと思うから繰り返し言っているのですけれども。","respondent":"金子子ども未来事業部長","answer":"これもだいぶこだわっていらっしゃいますけれども、私どもとしては、将来、ちょっとまだ見えないのですけれども、保育需要が低下したときにどうするのかということに関しては、やはりその時点その時点でどういう建物が建っているのか、つまり。","voiceIndex":37,"id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"やっぱり一定程度の、とりわけ今年はすごく子どもさんが入れなくてお母さんも辞めたくないのに辞めざるを得ないという状況に追い立てられてしまった、そういう状況を見たときに、やっぱり待機児ゼロを目指すというふうにおっしゃっているのであれば、本当にそれは努力するべきだと思うんですよね。今までの路線上じゃないですか、総合的展開では。やっぱりそういう不誠実な態度はやめるべきだと思うのですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"区長に対してもしっかりと、目指すなんて言葉だけ目指したってしょうがないですよ。本当にやらなければ意味がないことで絵に描いた餅に過ぎないわけですから。区民との信頼を勝ち取るには本当にきちんとした体制をとる。しかし、詰め込み状況を解消しないうちに、地域バランスと言ってなくすことはやめていただきたいということは強く要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-011"},{"speaker":"渡辺委員","kind":"質問","question":"すみません、名称のところで、今、第二というご説明の前に、五反田のところで出てきます、五反田という名称が頭にあって立地が北品川五丁目という中で、これは懸念があったと思うのですね。大きな意味のエリアではわかりやすいという中で、行政区分だとかその後の学区域だとか地域事情はいろいろあったと承知をされた上でのことだと思うのですが、どんな観点で決断というか名称を決定したのか教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"先ほど、部長からもお話があったとおり、五反田、東五反田、西五反田とありますので、五反田保育園とは実際には本当に坂等を挟まずに目黒川沿いに五反田保育園はありますので。","voiceIndex":41,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"態度としては、保育園が増設されるということで、賛成はしたいと思います。しかし、さっき言ったような問題点をしっかり受け止めて、取り組んでいただきたいということを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-013"}]},{"id":"topic-02","title":"の第６２号議案 品川区保育の実施等に関する条例の一部を改正する条例","agenda":"の第６２号議案 品川区保育の実施等に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"現行は、お母さんなり保護者の就労が何日間であろうとも、労働時間プラス通勤時間がその子の保育時間となっているのですけれども、新しくできた法律の中で、１１時間労働と８時間労働というふうに２つに分けたというそのあたりの状況というのはどういうことなのか、どういう意味を持つのかというのをちょっと教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今、委員ご質問の預かり時間の件ですけれども、現在、子ども・子育て新制度の説明の方でされていますとおり、現行、基本保育時間というのはこれまでどおり児童福祉法でも８時間ということになっておりますが、現行でも１１時間まで基本介入しておりまして。","voiceIndex":73,"id":"exchange-014"},{"speaker":"南委員","kind":"確認","question":"それで、第２条のところで４８時間、最低を４８時間にしたという下限就労時間をそこに設定したと、そのこと自体はそんなに多く働いていない方も保育園に預けることができるという点では、それはそれとして評価していい、現行をそのまま続けるという点ではよかったかなと思っているのですけれども。","respondent":"今井制度改革・待機児童対策担当課長","answer":"この就労につきましては、現在も就労の場合は勤務時間プラス通勤時間がお子さんをお預かりする保育の時間の基本となりますので、これは今後、短時間、標準時間、区別ができたとしても基本のお預かり時間の原則は変わるものではございません。","voiceIndex":75,"id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"ちょっと私、よくわからなかったのだけれども。それで８時間以内、例えば就労プラス通勤を含めて４時間とか５時間とかそういう時間が保育に欠けるということであればその時間しか預からないということになるのかどうかということを確認したいのです。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今後、そういう方が保育の短時間を選んでいかれると考えておりますので、逆に言うと、保育の短時間の方はこのほうに、保育短時間認定をお受けになれば保育短時間認定という形で今までどおりのご利用がいただけますし、たまたま例えば、今もそうですけれども、８時間以上。","voiceIndex":77,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"それは、この間の説明会でもそういうご質問が出て、そういうふうに答弁されていたのでそれはそれで了解というか、ああ、よかったわと思って聞いていたのですけれども。今は保証されているのだけれども、保証されなくなっちゃうのかなと、ちょっとそういうことが不安になったので質問しているので、そこを教えていただきたいと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区としましても、食事時間などやお昼寝時間も配慮しながらお預かり時間というものを保護者と十分に相談しながら決めていますので、例えば、１３時半とか１４時、５時間しか必要ないから、もう１４時にきちっと預かり、来てくださいというところのお話がありましたが。","voiceIndex":79,"id":"exchange-017"},{"speaker":"南委員","kind":"確認","question":"わかりました。じゃあ、確認したいのですけれども、保護者の意向があればそれはそれとして受け止めるけれども、子どもの生活リズム、そういうことは最大限受け止めて保育をしていくということでいいわけですよね。そこが確認できればいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"共産党は、これは反対です。反対の理由は、やっぱり働くお母さん、お父さんたちの就労保障というところが今の実態と大きくそごが出てくるという、こういう認定を含めてということで、そこのところが非常に気になるところなので、反対をしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":91,"id":"exchange-019"}]},{"id":"topic-03","title":"第６３号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第６３号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問","question":"反対理由としては、子ども・子育て支援法というものが、やっぱり子どもと働くお母さんたちにとって利益にはならないという問題点がいっぱいあるという点と、それからとりわけこの地域型家庭的保育事業のところでは、地域型保育事業ということについて、やっぱり中身が体制的に十分な状況にはなっていないという点で、この条文そのものの訂正だとか追加についてはそれはそれとして伺うところですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":107,"id":"exchange-020"}]},{"id":"topic-04","title":"第７６号議案 指定管理者の指定","agenda":"第７６号議案 指定管理者の指定","exchanges":[{"speaker":"石田（し）委員","kind":"提案","question":"２点教えていただきたいと思います。指定期間なのですが、指定管理者の制度は基本的に５年間の指定管理の期間だと思うのですけれども、なぜ３年なのかというのを教えていただきたいのと、裏面の指定管理者の候補者として選定をした理由の中に、図書館サービスの提案内容が優れていると書いてありますが、具体的にもし何かあれば教えていただきたいと思います。よろしくお願いします。","respondent":"中元品川図書館長","answer":"適正な区が求める要求水準ができるかどうかというところをきちんと確認させていただいて、次のタイミングからは５年ということで検討をしています。","voiceIndex":117,"id":"exchange-021"},{"speaker":"吉田委員","kind":"意見","question":"３グループに分けて、３グループとも同一事業者となったというのは、いいものかと、それを１点。グループを分けたというところがどうなのかということを聞きたいので、お願いします。","respondent":"中元品川図書館長","answer":"こちらといたしましては、各グループごと、地域のサービスのところ、地域の児童施設や学校との連携も含めまして、なるべく近いエリアということで３グループに分け。","voiceIndex":119,"id":"exchange-022"},{"speaker":"吉田委員","kind":"提案","question":"何も１社が全部請け負うということに関しての判断基準というのですか、それをお聞きしたいのですけれども。","respondent":"中元品川図書館長、田村教育次長","answer":"それが評定の中でも選定委員の皆さんの採点にもあらわれたのかなと考えているところです。ちょっと説明が不十分なのでご説明しますと、３グループに分けたのですけれども、全部の３グループに手を挙げている企業と地域性で１カ所しか手を挙げないグループとかまちまちでした。","voiceIndex":121,"id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"その関係を教えていただきたいと。それから、損害賠償責任という、さっきは退職した警察官を配置している他の自治体があるということなのですが、この共同事業体はそういう方を採用するというふうになっているので、損害賠償責任の関係ではそういう体制をしくんだなと思うのですけれども、とりわけ保険への加入というのはどういうふうに求めているのかという、そのあたりを教えていただきたいと思います。","respondent":"中元品川図書館長","answer":"住民の意見を聞いてきたかですが、こちらのほう、住民の方の代表の議会のほうにご提案、ご説明を申し上げてこの間ご説明申し上げご意見をいただいてきたところですので、そのような形で意見を聞いてきていると認識しております。","voiceIndex":125,"id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"それで、今まで私が質問したことについては、やってきている、大丈夫だという答弁なのですが、前の委員会でたしか言ったと思うのだけれども、ほかの、例えば使用料を取るそういう事業に対する指定管理者に委託するという部分では、何ていうのでしょうか、運営そのものがやりやすいというのかしら、独自の事業を展開することもしやすいけれども、図書館に限っては利用料金を取るわけではないですから。","respondent":"中元品川図書館長","answer":"１点目の共同事業体としては、募集要項の中できちんと明記をしておりまして、応募者は代表事業者が募集届け出を行った複数の事業者による運営も可としますということで、きちんとオーケーを出しており、こちらで募集要項に記載しているものです。","voiceIndex":127,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"法令遵守を求めるとか保険加入は当然と言えば当然のことなのであれなのですけれども、法令遵守ということについては、やはり一定程度価格が、何というんでしょうか、公でやるよりも安く抑えることができるということもあって、指定管理に民間に委託を、これは指定管理ですけれども、委託も含めてそういう考え方があってやってきているというところでは。","respondent":"中元品川図書館長","answer":"選定委員会の中でも実際に配置人数が少ない場合、きちんと配置していただけるのかというところも、配置しますというお答えをいただいているところです。今後につきましては、モニタリング等で確認をさせていただきたいと考えています。","voiceIndex":129,"id":"exchange-026"}]},{"id":"topic-05","title":"続きまして、(7)第５６号議案 平成２６年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"続きまして、(7)第５６号議案 平成２６年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"防犯カメラなのですが、この運用コストが対象外ということになっているので、防犯カメラを設置すると、その後運用コストというのがさまざまかかってくる中で、これというのはどこが最終的に負担をしていくのかお知らせいただきたいのと、あと、前提条件にも書いてありますが、ＰＴＡ・町会長等々と検討していくという中で。","respondent":"品川庶務課長、竹田保育課長","answer":"先ほどご説明いたしましたとおり、ＰＴＡ等周辺と調整を図るという点ですが、確かに町会の防犯カメラというのが周りに設置してありまして、当然そういうところとかぶってしまえば防犯カメラの意味がございませんので。その際、区立の幼稚園につきましては、そもそも入園料・保育料が低く設定されているということで検討していたところですけれども、多子世帯に対する支援をさらに厚くするべきだとの考えのもとから。","voiceIndex":151,"id":"exchange-027"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"例えば、大人の人が何かあったときというのはすぐ反応するのだろうけれども、子どもの場合というのは一定期間おいた後に実はというふうに保護者に言うケースもあったりするのかなと思うので、この辺の記録の保管の考え方というのを改めて教えていただきたいのと、あと１点、特色ある教育活動の中でまた補正が出ているのですけれども、特色ある教育活動というのは、補正にあまりなじまないのではないかと。","respondent":"品川庶務課長、渋谷指導課長","answer":"当然、こういう防犯カメラですからずっととっておくわけにもいかないですし、データの容量も限られておりますので、まずは１週間ということで事業を進めていきたいと考えております。特色ある教育活動に関するご質問ですが、これは区・都のそれぞれの委託事業でございまして、学校特色に関するものについてはこの部分で予算の項目に入れざるを得ないというところが実態です。","voiceIndex":154,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"ＰＴＡ・町会長さんと連携して通学路というところでの設定がかぶらないようにとあったけれども、あくまでも事業が東京都から来ていることなのだけれども、それを一つのきっかけとして網羅できるような、防犯カメラがたくさんあるというのはいろいろな議論があると思うのだけれども、そういうところについて、ないのであれば通学路についてはこの事業を活用してやっていくよと。","respondent":"品川庶務課長","answer":"委員も先ほどおっしゃいましたとおり、今回の事業につきましては、通学路に設置をするという事業ですので、またこういったカメラの設置につきましてはいろいろ安全上やはりやっていかなければいけない点というのもありますので、地域活動課とも連携しまして。","voiceIndex":157,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"今、最後の学校でとありましたが、なかなか専属でそれをずっと見ているよという人というのは難しいと思うのですけれども、職員の人が見ていくのかなとか、警備員はいなかったですかね。そういった、どういう形でそれを常時監視とかあとは適宜とか、どんな感じでイメージされているのか教えてください。","respondent":"田村教育次長","answer":"その範囲で５台程度ということになると、おのずとそういう仕組みというのが大前提になりますので、誰かがずっと通常そのカメラを見つつ、よく警備員の人が万引きしないように見ているとそういう話じゃなく。","voiceIndex":159,"id":"exchange-030"},{"speaker":"つる委員","kind":"質問","question":"今学校でやって、そうするとそのデータ自体は学校で保存してあって、何かあったときにというのは学校にある端末か何かをそこから引っ張れば、それはデータで追って１週間分は見られるよ、こういう仕組みですか。","respondent":"田村教育次長","answer":"だから、ちょっとそれについては管理の手引きのマニュアルが東京都のほうでひな形がありますので、各学校、先ほどの１週間もそうなのだけれども、東京都のひな形に沿って各学校管理マニュアルを各学校ごとに整備して、ただしできないこともありますので。","voiceIndex":161,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"つる委員の後なのですけれども、設置場所の話が出ていましたけれども、検討決定に対してＰＴＡ・町会等、また地域活動課という話もありましたけれども、警察の話も出ましたが、警察庁の街頭の防犯カメラの設置に関しては、防犯設備士等または警察の方も含めてという話し合いをして、中立的な専門家の助言が必要ではないかという話が出ていたのですが、それに関してどのようにお考えか教えてください。","respondent":"田村教育次長","answer":"ちょっと説明しますと、東京都の小学校の通学路の防犯カメラが出る前に、この事業をやる前に、先ほど石田委員からもありましたように、各町会が地域活動課の生活安全担当が窓口で町会負担で防犯カメラというのがありました。それは、必ずしも通学路に限定していません。","voiceIndex":163,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"そこでですが、小学校３年生以下と設定したそこのところがちょっとよくわからなかったので、限定するということでなくて、あっていいのではないかと思うので、その辺の考え方についてと、それから保育園のほうは上の子どもが在園している子どもさん、２子・３子目ということがたしか対象だったと思うのですが、そことの関係で、保育園のほうの対象をちょっと確認して。","respondent":"竹田保育課長、品川庶務課長、村尾学校支援担当課長、渋谷指導課長","answer":"今多くの子どもたちの状況を見ますと、兄・姉の年齢差等を考えまして、小学３年生が適当と考え、ここで範囲を定めたものです。芳水小学校は建築から約５０年たっております。学校と家庭の連携推進事業のお尋ねですが、これにつきましては目的がいじめ、不登校等さまざまな学校の課題に対応するために児童・生徒、学校。小中一貫教育に関する啓発物品の中身についてですが、今検討中ですが、特に寄附者のご意向により。","voiceIndex":165,"id":"exchange-033"},{"speaker":"南委員","kind":"質問・要望","question":"芳水小学校の関係なのですけれども、５０年たっている学校だということなのですが、一つ確認したいのは、これまで学校改築をしてきた学校、例えば荏原第五中学校とか、今回は芳水小学校は小学校ですけれども、そういう今までやってきた単独校の改築をしてきた学校が５０年あるいは５０年以上なのか、ちょっとそのあたりの、大ざっぱでいいのですけれども。","respondent":"竹田保育課長、田村教育次長","answer":"幼稚園の就園奨励費の関係ですが、こちらは国の制度でございまして、国の制度設計が小学３年生までを対象とするということになっておりますので、こちらでこのように定めたものです。そうでないと擁壁工事が１００％できないと、その２つの要素で、順番的には約５０年で、年数的にはまだもっと古い学校もあるのですけれども、やはり早急に着手せざるを得ないということです。","voiceIndex":170,"id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"本当はもう少し拡大してもらいたいなと思うのですけれども、これから品川区としてもそういう方向で検討していただきたいということは要望としてお話ししておきたいと思います。したがって、在園児という枠をやっぱり払って小学校３年生、少なくとも幼稚園と同じように対象拡大をしていただきたいと思っていますが、そのあたりの見解を最後に伺っておきたいと思います。","respondent":"竹田保育課長、田村教育次長","answer":"そもそも国の保育料の設定よりも、品川区におきましては保育料を低く軽減しております。第２子に関しては、第１子の半額等を既に保育料等で実施しています。ただ、今後補正予算が通りますと、通常どおり建設準備会と、地元の町会長だとかＰＴＡといった方で建設準備会を立ち上げますので、やはりそういう趣旨も当然一部にあったと認識していますので。","voiceIndex":173,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"そういう点でぜひ幼稚園のほうと少なくとも年齢は合わせるぐらいの配慮が、温かい姿勢があっていいのではないかと思いますので、そこはぜひ検討していただきたいという要望をさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":176,"id":"exchange-036"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"だから、品川区としては、既にあったところについての維持管理については区が区費として見ていきますよという話をしながら、新しい子どもさんたちの安全な通路をつくっていくための防犯カメラを公設するというような考え方に持っていってもらわないと、区民から見たら何となくぎくしゃくした状況を、この通学路に対して町の中がまた変な話になってきてしまうだろうと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":177,"id":"exchange-037"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、私、法律を理解しているかわからないのですけれども、認定枠というのがそもそも４月から存在するのか、認定保育園で認定こども園枠というのはあるのかどうかというところがちょっとわからなかったので、移行、４月ごろこの認定こども園の法的な位置づけはどのようなことになっているのでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"前回、そして今回第６１号・第６７号議案の資料の裏面にも記載しているのですけれども、認定こども園北品川第二保育園は、類型としまして保育所型の認定こども園ということで検討を進めております。","voiceIndex":178,"id":"exchange-038"},{"speaker":"高橋委員","kind":"質問","question":"ということは、保育所という認識でよろしいのですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これは保育所ではなくて、認定こども園の保育所型認定こども園です。認定こども園法上で保育所型、それから幼稚園型、幼保連携型、地方裁量型とありますので、認定こども園法上でいう保育所型認定こども園になります。","voiceIndex":180,"id":"exchange-039"},{"speaker":"高橋委員","kind":"質問","question":"ということは、新しい形、新制度の下での認定こども園だとすると、教育・保育要領やあるいは幼保連携型認定こども園と同様の仕組みづくりをしていく必要がある、これは私、そうかどうかというのは勉強したのですがちょっといまいちわからないので、そういった状況にあるのではないでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"今回、国の制度設計で幼保連携型認定こども園が、これまで保育所等や幼稚園がそれぞれの所轄官庁が別々でしたものが１つになりまして、新たな幼保連携型認定こども園という制度をつくりました。これには、この保育所型の認定こども園は該当いたしません。","voiceIndex":182,"id":"exchange-040"},{"speaker":"高橋委員","kind":"質問","question":"それで、認定こども園という名称を使うとすると、非常に今も混乱している状況なのですけれども、そういったところから、何ていうのですかね、今お話があったように、新しい条例上とかそういうのを区のほうでは準備しないで、今までどおりの形で認定こども園になっているということでよろしいのですか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"これまでどおり、一本橋やほかの品川区の保育所型認定こども園と同様に、保育所型の認定こども園として保育所を母体として運営してまいります。児童福祉法上の保育所の中で運営してまいります。","voiceIndex":184,"id":"exchange-041"},{"speaker":"高橋委員","kind":"確認","question":"じゃあ、児童福祉法の中の保育所としての運営をしていくということで、子ども・子育て法とか新認定こども園法の話の中ではないということで、確認できました。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":186,"id":"exchange-042"}]},{"id":"topic-06","title":"の報告第３３号 専決処分の報告","agenda":"の報告第３３号 専決処分の報告","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１点だけ。今回の件も老朽化が原因ということでして、以前にも話をさせていただいたのですけれども、例えば校庭にあるバスケットゴールですか、ああいったものもなかなか予算がかかることですので、適宜老朽化したものに関しては更新をされているとは思うのですけれども、その点はもう一度、今回の事件を踏まえてしっかりと対応していただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-043"},{"speaker":"高橋委員","kind":"意見","question":"本当に大事、大きなけがだったのですけれども、命に関わらないあれなのでよかったと思うのですが、今区内の各校をチェックしていただいたということで、老朽化しているのはロープを変えたというのもあったそうなのですが、どれぐらいあったかわかりますか。","respondent":"野呂瀬学務課長","answer":"学務課のほうから各校に調査を依頼しました。どれくらいというよりも、いわゆる設置年度が１０年以上あるのかとか、あとはどのぐらいの老朽度合いというのを出させていただきました。それによって、今回１４校、本年度予算で対応したものがあります。","voiceIndex":209,"id":"exchange-044"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、これは今授業中だったのですけれども、いわゆる一般開放のときに起きたら、これはこちらの話ではなくなるのですか。","respondent":"渋谷指導課長","answer":"この事故そのものはバレーボール、部活動中の事故ですが、備品ですとかネットについては授業用、一般開放を問わず点検をしたです。","voiceIndex":211,"id":"exchange-045"},{"speaker":"須藤副委員長","kind":"質問","question":"そうすると治療費は出てないのだけれども治療費というのはどうなのかなということ。慰謝料というのは、区として何か定めがあるのかな。事故があったときにどうするのだという定めがあって、この費用、いわゆる３４万４,４４７円といううちに治療費がもしかかるのだったらこういう治療費ですよ、慰謝料はこうなりますよという、何か基準があってこういう数字になっているのか教えてください。","respondent":"渋谷指導課長","answer":"損害賠償金の基準等については、総務課が対応になっていますので今詳しい資料がないので後ほどご説明させていただければと思います。","voiceIndex":213,"id":"exchange-046"},{"speaker":"須藤副委員長","kind":"質問","question":"今言ったベッド代とかタクシー代、そういうのが幾らになって、トータルが出てくるということですか。そうすると、そのほかがいわゆる慰謝料という考え方になると思うのだけれども、そのあたりの数字が出ますか。出なかったらいいけれども。ただ、慰謝料というものの考え方がどういうふうになっているのかなと思うので、それを聞かせてください。","respondent":"渋谷指導課長","answer":"今、手元に資料がないので調べさせていただきたいと思います。","voiceIndex":215,"id":"exchange-047"}]},{"id":"topic-07","title":"のその他","agenda":"のその他","exchanges":[{"speaker":"南委員","kind":"質問","question":"１つは、午前中の条例のところでも若干質問させていただいたのですが、保育園の飯沼議員の待機児解消の問題です。２つ目は、小中一貫校の６年生の卒業式、一貫校全校でやっているということなのですけれども、具体的な形態について知りたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-048"},{"speaker":"石田（し）委員","kind":"質問","question":"今の質問だと、待機児童解消について何なのかというのが質問されていないので、本会議と結局同じになってしまうのではと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":224,"id":"exchange-049"},{"speaker":"南委員","kind":"質問","question":"具体的な品川区の対策、どういうふうに考えているのかという。午前中でもちょっと質問はしたのですけれども。そこをさらに詳細に伺っておきたいと思って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-050"},{"speaker":"こんの委員長","kind":"質問","question":"今、石田委員からもご質問があったように、確かに今私も南委員の質問はお受けしたのですが、対策という部分では、今のご質問から言いますと確かに繰り返し、同じ質問。確かに詳細というのはそうなのでしょうけれども、同じ質問になってしまいますので、そうではない角度であればお受けしますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"本会議では、再質問、再々質問２回しかできないし、時間もかなり２分ということで制限されていますので、具体的に詰めると、詳細を求めていくというのはなかなかできないわけです。従って、ここで……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-052"},{"speaker":"南委員","kind":"質問","question":"同じことを聞くことになると思いますよ、それは。フォロー質問ということで、あそこで追求しきれなかったところをやっていきたいということですから。フォロー質問ということでいいと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":228,"id":"exchange-053"},{"speaker":"須藤副委員長","kind":"質問","question":"そこは皆さんで配慮しながら、余り同じことを続けたらほかの委員の意見も聞いていただいて、じゃあ次の質問に行こうよということでやっていかないと。せっかく委員会の活性化ということを目的で僕らはやってきたつもりなので、それをばしんと切るわけにはいかないだろうけれども。そのあたりは委員長にお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":229,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"だから、須藤副委員長がまとめていただいたとおりだとは思うのですけれども、平行線のままだから、それはその時点でやっぱり切るしかないわけですよね、質問者としては。それ以上の答弁が出てこないというのであれば、それは要望にとどめるとか、どういう収束の仕方かはわからないけれども、それはそういう良識の範囲で議員としてやっていけばいい話だと思うのです。","respondent":"渋谷指導課長","answer":"今、南委員のご質問の確認なのですけれども、小中一貫校の卒業式については、答弁では本年度から全小中一貫校で実施することとし、既に６校の校長に通知しておりますということで。","voiceIndex":230,"id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"私たち共産党としては、問題意識として６年生だって一定の節目ですから、今まで一貫校じゃない分離校でやっていたような卒業式を一貫校だからといってそういう場がないということはやっぱり好ましいことではないので、きちんと卒業式をやるべきだということは繰り返し質問をしてきたのですよね。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":232,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4836#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":49479,"voices":233}},{"id":"h26-20141027-5","meetingId":"h26-cm10","date":"2014年10月27日","dateIso":"2014-10-27","committee":"総務委員会","time":"午前１０時００分～午後 ４時３１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査の(1)、第５８号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","agenda":"議案審査の(1)、第５８号議案 品川区情報公開・個人情報保護条例の一部を改正する条例","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"それと、パブコメですけれども、このタイミングで行うのはなぜかということと、内容がなかなか難しいので、ぜひ説明会を実施してほしいということなのです。伺いたいのは、この個人情報の漏洩ですけれども、４月の説明では厳格な本人確認の義務づけと個人カードに顔写真をつけていることで防げるという説明だったと思いますけれども、これでなぜ防げるのか伺いたいと思います。","respondent":"荒井広報広聴課長、秋山情報システム課長","answer":"説明会をする予定はございません。法的に決められているということが、なぜ漏洩が防げるかという質問ですけれども、そういう点から情報漏洩が防げるということで考えておりますです。","voiceIndex":9,"id":"exchange-001"},{"speaker":"中塚委員","kind":"確認","question":"それと、導入の必要性ですけれども、４月の説明では、時間もコストも節約できるとメリットを説明していましたが、具体的な事業について、生活保護や介護給付の支給や特定障害者特別給付の申請、たくさんあると、障害児福祉手当の支給や児童福祉手当、いろいろ紹介して、所得証明や住民票が省略できるというふうに、そういうご説明がありましたけれども、要するに、時間とコストが節約できる。","respondent":"秋山情報システム課長","answer":"どれぐらいのシステムが添付書類等が必要がなくなるかですけれども、現時点では、およそ２０程度のシステムで改修をかける予定ですので、そこの中のシステムの数としては２１ですけれども、その中の書類の申請の数については、複数の申請等がありますので、変更とか新規とか。","voiceIndex":12,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"本日はまず議論ですので、とりあえずどういう中身なのかということは改めて伺いますけれども、詳細はしっかり資料で出していただきたいということは伝えておきます。だから、区が準備している用紙で書くことも、自分がつくった用紙でも、口頭による申請も、緊急時での行政の判断による緊急保護も可能なわけであって、これ以上何か申請で物が少なくなるという手続は見当たらないのです。","respondent":"秋山情報システム課長","answer":"システムの話ですけれども、システムでどういう情報連携をするのかということが、先ほどもご説明しましたけれども、国からの詳細が現在、細かい項目等が出ていないというのが状況でして、なかなか見積等がしにくいということがありますが、コストの面については。","voiceIndex":14,"id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"具体的な書類が簡略化されるとは言うものの、何がどうされるのかということを今の説明でも示されていないわけで、とりあえず２１事業をこういうものではないかという検討がされている以上、それはしっかりと資料で出していただきたいと改めて求めておきます。導入にかかる費用や維持費も不明で、これでどうして時間やコストの節約と言えるのか、私にはわかりません。改めてそこを伺いたいと思います。","respondent":"秋山情報システム課長","answer":"手間を省いていないのではないかですけれども一律に添付書類がなくなるということのほかに、行政の中での名寄せの部分であるとか、それから、扶養家族の調査であるとかというところの調査の部分も、今度の個人番号を使えばオンラインで調べることができるということで。","voiceIndex":16,"id":"exchange-004"},{"speaker":"中塚委員","kind":"確認","question":"だったら、総合相談窓口をつくって、いろいろなパソコンの端末やデータをそのパソコンに持ってくればいいわけですから、わざわざこの番号法を導入しなければそれができないという説明には成り立たないと思うのですけれども、最後にいかがでしょうか。","respondent":"秋山情報システム課長","answer":"これは先ほども広報広聴課長から説明がございましたけれども、情報提供記録というものを個人がパソコンで見ることができるようになる。要は、情報の提供が自治体間、それから国との間でどんな情報がやりとりされているのかということを区民が自分のパソコンから見ることができる。","voiceIndex":18,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"ただ、今、委員からありましたが、やはり情報漏洩等々すごく敏感になっております。まだ国からのきちんとした、どういうものにどういうふうに利用して、どう運用ということがまだ出ていないやに今お話をされてお聞きしましたが、そこが一番心配だと思いますので、その点についてはしっかり管理できるような運営方法でいっていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か伺いたいと思いますけれども、はっきり言って、これを読んでいても、どこがどういうふうに、具体的なものが現実問題よくわかっていない部分もあるのだけれども、例えばこの番号制をつくっていこうとしたときの経緯を考えると、例えば先ほど言った年金を入れ込む、それから先ほど言ったいろいろな法がつくられても、簡単に言うと、法律違反をする人がいるから漏洩もしたり。","respondent":"秋山情報システム課長","answer":"それについてはいろいろなところで、民生委員の方に名簿を渡せるようにするにはどうすればいいかということも考えていますので、そちらのほうで対応して、そういう町会の方には。","voiceIndex":21,"id":"exchange-007"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひこれは私などは、もちろん賛成をしていく形ですけれども、ぜひ運用が、どうしても、住基カードのときも最初の導入に関しては、思ったよりも進んでいないと思っている部分があったり、今度はまた違った意味で、これがしっかり進んでいくことによって、本当に先ほど言った年金のこととか、適切な納税の部分とか、そういうことが改善されてきて、国民の意識も変わってくるということであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"幾つかお願いします。それと、読み替えて改正している項目の(1)、この意味がよくわからない。細かい話になってしまうかもしれませんが、本人の同意がある場合は提供するということですか。任意代理人における自己情報開示はいいですと言っているのか、今度、次の文章も、利用停止請求の対象から除外するというのは何ですかという、ここの例とかがあったらわかりやすくなるかと思います。","respondent":"荒井広報広聴課長","answer":"それ以外は利用または提供できない、ですから、この場合は利用、提供ができるというふうに読んでいただければいいと思います。","voiceIndex":24,"id":"exchange-009"},{"speaker":"西本委員","kind":"確認","question":"パブコメもかなりやり方はいろいろ工夫しないと難しいのではないか。先ほどもありますように、メリット、デメリットも出てくると思うので、その辺の工夫は何かされているのか。それと、予算です。本当のことはまだわからないということなのですが、国からの補助というのは何かあるのか、１０分の１０なのか、それとも負担がかかってしまうのかという辺を確認したいと思います。","respondent":"荒井広報広聴課長、秋山情報システム課長","answer":"ただいまの質問になりますが、パブコメのやり方につきましては、広報紙、ホームページ等を通じて行っていくところですが、なるべく多くの方からご意見をお寄せいただけるような工夫をしていきたいというふうに考えているところです。ガイドラインの件ですけれども、ガイドラインは策定はしておりますが、住基のシステムが今回このガイドラインに基づいて評価書の作成からパブコメ、第三者点検等を実施しますので、それを踏まえて改訂をするということで。","voiceIndex":26,"id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう種類だと思っているので、事前にいろいろと広報活動をしていただきたいというふうに思っております。それから、予算の３分の２というところもあるということなので、これはいたし方ない状況ではありますけれども、国のほうの何か動きがかなりおくれているような感じがありますので、品川区で進めていくべきところについては、どんどん進めていっていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-011"},{"speaker":"いながわ委員","kind":"質問・要望","question":"条文から入ると非常にわからないのは本当に現状そうだと思います。個人情報に関しては、漏洩は絶対あってはならないという部分は常識なところであって、先ほど、顔で承認できるからという話も、そもそもその時点でその人でない可能性もあるわけですから、それを完全に漏洩はそこではしないとか、なりすましはないというようなことは言い切れないのではないかと思います。その辺について１点。","respondent":"秋山情報システム課長","answer":"例えば、個人番号を用いて、個人番号で名寄せとかというものができてしまうと、個人情報が漏洩したときにすぐにわかってしまうということがあるので、名寄せができないように、個人番号は使いますけれども、情報が流れていく行き先の間では。","voiceIndex":30,"id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"意見","question":"１点だけ。今の話で、さっきもちょっと触れたのだけれども、あまりそこを言わないほうがいいと思う。それのほうがいいと思いますということだけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-013"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"もう１つはシステム面でやっていく、２つの両サイドでやっていくというお話があったと思うのですけれども、一応確認したいのは、例えば情報制度面で言うと、少なくとも情報が誰がどこで見ていったのかというその履歴というものがきちんととれるようになっているのかというところを確認したい。抜かれたことがわからない、コピーされたことがわからないで世の中に出回ってしまっているということが実はある。","respondent":"秋山情報システム課長","answer":"１つずつのご説明はあれですけれども、対応しているということを、先ほどお話ししましたＰＩＡという評価の中でリスクを分析して、それに対する対応をきちんとその中に書き込んで公表する、要は。","voiceIndex":33,"id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"一言。この条例改正は、番号法を進める環境整備です。番号法は個人情報漏洩のプライバシーの侵害や、本日の質疑でもなぜ導入が必要なのか、具体的に何がどうメリットがあるのかも不明、費用対効果も不明、結局、徴税強化や社会保障給付削減の手段になりかねません。よって、進めるべきではないということで反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-015"}]},{"id":"topic-02","title":"議案審査の(2)の第５９号議案 品川区特別区税条例の一部を改正する条例","agenda":"議案審査の(2)の第５９号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"いながわ委員","kind":"質問","question":"これは決算の話になってしまうのですけれども、たしか決算書を見ると、軽自動車税の中で滞納繰越分というのですか、それの徴税率というか、あれがパーセンテージがすごく低い状況だったと思うのですけれども、それを考えると、また税金が上がったことによって滞納額が増えてしまうのではないかと思うのですけれども、その辺を教えてください。","respondent":"黒田税務課長","answer":"区民税がある方は一緒に納税交渉というところがあるのですが、例えば、軽のバイクしか持っていないという方にアプローチする機会がなかなか、督促状、催告書等々をお送りして徴税努力は続けておるのですが、なかなかそこのところが難しいというところを感じておりまして。","voiceIndex":47,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"改正の内容としては５つですけれども、大きくは軽自動車について伺いたいと思います。軽自動車は、庶民の移動の足としてとても大切です。増税による区民生活への影響をどう考えていらっしゃるのか、原付バイクは２倍、軽自動車の四輪以上では、営業用が５,５００円から６,９００円、自家用乗用車が７,２００円から１万８００円と、この区民生活への影響をどう考えているのか伺いたいと思います。","respondent":"黒田税務課長","answer":"環境負荷の軽減、環境に与える負荷という意味では、軽自動車も自動車もそれほど差異がないのではないかというところがいわゆる税制の検討のところになりまして、その中で総務省のほうから、今の税率を２倍にするであるとか、３倍にするという案を示して。","voiceIndex":50,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"あわせて、ほかのことですけれども、公益法人に対する課税の特例ということが３番目にありますけれども、継続として非課税ということですけれども、継続というのは、これはどういう事情といいますか、いつかはこれが定着するというのか、その辺の状況がよくわからなかったので、この継続の意味を解説していただきたいのと、あと、５番目の優良住宅地造成等のためということですけれども。","respondent":"黒田税務課長","answer":"２点目の自営業者の方、軽自動車を商売に使われていてというところは重々承知ですが、今回の税率の改正に至った背景は、先ほど申し上げたとおり車体課税全体のということが国のほうで検討されておりまして、そもそもは持っている方と持っていない方がいる中で。","voiceIndex":52,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"自営業者の方が使っている事情はつかんでいるということですけれども、先ほど伺ったのは、環境への負荷ということであれば、庶民生活に求めるのではなくて、別のところがあるでしょうと、私はその点は指摘しておきたいと思います。それだけにこういう軽自動車税というのは、どうして検討されないのか、そこがよくわからなかったので、そこだけご説明いただきたいと思います。","respondent":"黒田税務課長","answer":"軽自動車税につきましては、地方税法の中でも法定普通税ということに位置づけられておりますので、いわゆる市町村の財源の１つですので、標準税率につきましては、税法の改正がありましたので、それにあわせまして標準税率を定めるというものですので。","voiceIndex":54,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"税金の種類の説明はわかったのですけれども、軽自動車税増税に対する生活への影響の対策、それを検討しない理由は何かということなのですけれども。もちろん検討してほしいという要望で聞いております。しない理由があるのだったら、それはそれで説明いただきたいと思います。","respondent":"黒田税務課長","answer":"先ほど、いながわ委員からのご質問で答弁申し上げたとおり、平成２７年度で２,６００万円ほどの収入増を見込んでいるですので、全体で２,６００万円ということもありますし、品川区の軽自動車の登録台数は若干減っているところもありますので。","voiceIndex":56,"id":"exchange-020"},{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。私も大変不勉強で、初めて、例えば特例とか延長とかが出てきて、肉用牛とか、こんなものもあったのだと思ったのだけれども、こういう特例とか軽減、軽減税率をしていて延長とか、軽減税率があるのだけれども、こういうものの項目というのは幾つぐらいあるのですか。これだけ教えてください。","respondent":"黒田税務課長","answer":"正直申し上げますと、この特例につきましては、いわゆる税法の本則がありまして、付則の中で規定されているもの、これは全部一律の軽減措置なのですが、あとは租税特別措置法の中で、いわゆる政策誘導的に指定されている項目があるほかに、全く別の法律をつくってということで。","voiceIndex":58,"id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問","question":"私も初めて、いろいろいっぱいあるのだろうと思ったのだけれども、今どうしてこういう質問をしたかというと、ふと思ったのは、今みたいに増税、増税という話が来るわけです。これは感想だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-022"},{"speaker":"西本委員","kind":"質問","question":"今、４と５の延長というところ、３年延長しているのですけれども、延長した理由は何かあるのか、その背景がもしわかったら教えてください。それと、付則のところが今回かなり変わっているということで、「今のお話で、そうか、だから付則のところが条例のところで変わっている」と思いました。これが全部なくなっているのです。これはどういうことでなくなっているのか、理由があったら教えてください。","respondent":"黒田税務課長","answer":"４番と５番で、３年間延長するということで、あえてですが、税制調査会の資料を見ましても細かい背景はちょっとわかりかねるところがあるのですが、特に４番につきましては、これは所得税も同じく３年間延長されておりまして、個人事業で肉用牛を生産されている生産農家に対して。","voiceIndex":61,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"そんな中でそれぞれ区民、国民を含めて区民も大変な状況なのですから、この辺、何か別の、そういうことを、その大変さということを国のほうにも、私は意見としてしっかり伝えてほしいし、何かほかの救済策等がありましたら、それは政策として反映させていただきたいということを私は区からきちんと要望していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-024"},{"speaker":"中塚委員","kind":"意見","question":"一言述べます。庶民生活や自営業者、商店の足に欠かせない軽自動車への増税は間違っていると思います。その増税の影響について、それを減らす区の対策もないと。今回の条例改正は、公益法人に対する特例など必要な対応もありますけれども、全体としては庶民への増税強化、優遇税制の延長であり、反対です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-025"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ご説明ありがとうございました。前々からよく辞退が多いとか、１００％の落札だとか、いろいろ質問はありました。物価スライドとかで調整をしているということもお伺いをしています。そのため、また改めてお伺いしたいのですが、複合施設の新築工事の落札が１００％、番号の１、３は辞退という、辞退の理由、１００％の理由をお聞かせいただきたいと思います。お願いします。","respondent":"立川経理課長","answer":"２点ご質問いただきました。１点目の辞退の理由ですが、区が公告している予定価格よりも事業者の積算価格が上回るです。１００％の理由ですか、これは事前に予定価格を公表してありますので、落札事業者につきましては１００％の金額で札を入れたというものです。","voiceIndex":78,"id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そもそも１００％で落とすということが、その額でできますという話なのか、考え方ですから、それは先方の考え方だからわからないと思いますけれども、この額がぎりぎり、それでも赤字なのだけれども、これでもとらざるを得ないという、金額を低く抑えたいのだけれども、それすらも無理で、これでもマイナスをもしかしたら受けている可能性もあるわけですね、会社側からすると。","respondent":"立川経理課長","answer":"辞退がある中で、応札が１社ですけれども、札を入れてくれたということは、この価格が妥当であるというふうに考えております。","voiceIndex":80,"id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"まだ何か物価、資材とかが高騰は続いているという話もありますので、全体的に、これは早急につくって地域の人に資する施設にならなければいけないと思いますので、また、適時、物価が上がったという部分であれば、スライド条項を適用していただいて、補正を組むなりしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-028"},{"speaker":"石田（秀）委員","kind":"意見","question":"入札不調を迎えないようにということで、２割以上の補正予算を組んで上げたときがあったわけです。そうすると、工期がおくれることがいいのかどうかという判断をすると、この１００％の１社入札は、最終的にあとは辞退というのは、私はここの部分については見解は述べてほしい。それの思いをもう１回改めてどうだったかという、補正から含めて、思いをちょっと言ってほしいと思います。","respondent":"立川経理課長","answer":"積算に当たりましては、国の算出の労務単価、また、実勢価格を反映した資材単価等を用いてやっているところですけれども、やはり業者によりましては、一次下請け、二次下請け等との価格等の折り合いがつかないというような声も聞こえてきておりますので。","voiceIndex":83,"id":"exchange-029"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、この工事についてはおくれるわけにいかない。これは不調を招くと、当初言っていた補正予算のときも、ここで何かあっておくれてはまずいのだと、これはこの中でやっていきたいというお話、期間の問題も含めて、だから中途があるわけで、だから、それがこういう状況になったということは、何らかの見解は言っていただきたいという質問なのだけれども。","respondent":"小林施設整備課長","answer":"それとあと、１００％で落としたというのは、私のほうも１００％で落としたというのはわからないのですけれども、私のほうは、不調が回避できたということで一安心しています。","voiceIndex":85,"id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私も１つぐらいは確認しているのだけれども、漏れ伝わってくるところによると、例えば、民間というか、区が、例えば南品川の保育所とかもこれぐらいでと、あれは民間になってくるけれども、その以前だったら杜松小学校のときもそういうことがあったり、最終的には落ちたけれども、今も参加がなかったとか、ほかのところでなかなか入札が１回落ちなかったとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"それと、補助金の関係でもあるのですけれども、特養ホーム部分では、高齢者人口比の特養の整備率で、通常は１ベッド当たり５００万円だけれども、人口比で一定おくれているところは１.５倍の７５０万円と伺っているのですけれども、平塚橋のこのケースではどちらを使っていらっしゃるのか、恐らく東京都の関係では１.５倍のほうではないのかと思っているのですけれども、そこを伺いたいと思います。","respondent":"立川経理課長、大串福祉計画課長","answer":"総額ですけれども、この４議案足し込みますと、約４５億円になります。こちらの特養整備における補助金の促進係数へのご質問だと思います。こちらの促進係数につきましては、１.４、こちらを使っているところです。","voiceIndex":88,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"利用者の声を反映して、車いすの利用の方も、また、さまざまな方が使えるように新設されるとともに、今あるところも改善を進めてほしいと思うのですけれども、こういう区の意向というのは、契約の中でどういうふうに業者に伝わっていくのか、また、区としても、トイレの形はそんなに平米は変わりませんので、何らかの定式化をつくって、ちょうどいい備品の配置など。","respondent":"小林施設整備課長","answer":"ただ、いろいろなご意見がありますので、今後、現場のほうでレイアウトを検討する際は、その意見も取り入れた形で今後検討して考えていきたいと考えています。","voiceIndex":91,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"だれでもトイレについては、ぜひ利用者の声を反映して使いやすいものに工夫していただきたいと思います。もう１点だけ、こういう大きい公共事業、小さい公共事業もそうなのでしょうけれども、積算の中に建設業退職金共済制度というものがこういう積算の中に位置づけられていると思うのですけれども、その状況を伺いたいと思います。","respondent":"立川経理課長","answer":"全体金額からこの辺の経費をどれぐらい見ているかですけれども、業種により、また、工事内容により、こういった制度の適用ができる人数が変わってくるところですけれども、目安としましては、建築で契約金額の０.２％、また土木では０.３％、電気工事では０.０５％。","voiceIndex":93,"id":"exchange-034"},{"speaker":"中塚委員","kind":"質問","question":"それだけに、区としても、もちろん契約に基づいて履行するようにというのは当然なのですけれども、状況も把握しつつ、交付、そういう制度がありますので、ぜひ受け取ってくださいみたいなポスターとか、現地での説明会とか、そういう一般的に安全第一というのはたくさんありますけれども、こういう制度を活用しましょうという、そういうものを伝えていくべきではないかと思うのですけれども。","respondent":"小林施設整備課長","answer":"やはり会社のほうに入って下請けとして会社の中で一員としてやっているところが現状多いということで、その証書というのか、張るという、それを求めてくる人が少なくなったというのはいろいろ聞いております。","voiceIndex":95,"id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"１点だけお聞きしたいのですけれども、これだけ毎回議案審査するのですが、入札辞退が増加して、入札不調の心配が増えている。どう思っているのか。","respondent":"立川経理課長","answer":"今、制限付きでやっている、その目的ですけれども、まず第１は、工事比率の敢行ということでございまして、過去に類似の受注実績があるかどうかです。もう１点は、区内の中小企業社の優先ということで、区内に本店または営業所を持っている、そういったところが主な制限内容です。","voiceIndex":97,"id":"exchange-036"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけで。先ほど、ほかの委員からもありましたが、予定価格１００％で落札するとか、辞退、辞退、辞退というのが毎回ページに書いてあるわけです。そこら辺は何か改善していかないとまずいのではないかと思いますので、まだそこは工夫していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"教えてください。新築工事のところで、所在地がありますが、共同企業体が、大きな仕事なので、当然そういう企業体を使って入札してくることだと思うのですが、江東区、港区、渋谷区というのが入っているのですね。これは別に共同体に品川区が入っていればいいのかという、どこに線があるのでしょうか。","respondent":"立川経理課長","answer":"この理由ですけれども、区では、ある一定の金額以上、建築では４億円、また設備については１億３,０００万円以上なのですけれども、こういった場合に、いわゆる重要な工事ということでジョイントベンチャーを組んで、いわゆる区外でゼネコンと呼ばれているところですけれども。","voiceIndex":100,"id":"exchange-038"},{"speaker":"西本委員","kind":"意見","question":"でも、少し方法を変えて品川区だけではなくてもというところは、ある程度の許容範囲を、いろいろな条件は必要だと思いますけれども、今後も１つの区民の皆様方にとっては、還元できることができるようになる場合もあるかというふうに思うのですが、今後、検討していただけるものなのか、今検討しているのか、絶対品川区ではないと、品川区業者ということを限定していくのか、その辺の考え方を。","respondent":"立川経理課長","answer":"そういった場合は柔軟に区外の事業者にも呼びかけて、制限付きではありますけれども、一般競争入札を実施しています。","voiceIndex":102,"id":"exchange-039"},{"speaker":"西本委員","kind":"意見","question":"区内の企業を発展させていくということ、難しいことではありますけれども、もう少し、不調にならない、今回はなっていませんけれども、辞退が多いということになると、いろいろな意味で相手方に対しての許容範囲も広げていくことも今後考えることが必要になってきている時代なのかと言われていますので、今後の課題という形でお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-040"}]},{"id":"topic-03","title":"議案審査の(7)の第７２号議案なのですが、先に(10)、第７５号議案を先にいたしますので、よろしくお願いいたします。 それでは、議案審査の(10)","agenda":"議案審査の(7)の第７２号議案なのですが、先に(10)、第７５号議案を先にいたしますので、よろしくお願いいたします。 それでは、議案審査の(10)","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"御殿山小学校の件ですけれども、昨年の第２回定例会で工事を始める契約が示されました。それともう１点、外構工事と一緒に解体工事も契約の中に入っておりますけれども、外構と解体と一緒になる議案というのは、どういう事情というか、理由なのか、それぞれの議案の組み方ということになるのでしょうけれども、そこを伺いたいと思います。","respondent":"立川経理課長","answer":"今回、外構と解体をセットで発注ということになりました。前回の御殿山小学校関係の入札に際しましては、こちらの外構と解体についての全体調整がまだ整わなかったということが考えられます。","voiceIndex":122,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"全体調整が整わないということですけれども、通常いろいろな工事も外構工事は最後から来るので、大体初めからここだけはいつも最後でもう１回議案で出るのかというふうに私などは感じていたのですけれども、本来だったら全部一括が基本なのだけれども、それともそもそも外構工事というのは後から議案として出すという、そういうものなのか、そこの違いをご説明いただきたいと思います。","respondent":"小林施設整備課長","answer":"それと、先ほども言いましたが、本体工事と外構工事というのは、外構工事も金額が大きいものですから、幅広く品川区の業者にとってもらうということで別発注をしているということです。","voiceIndex":124,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つ最後に伺いたいのは、この敷地の形なのですけれども、左側に棒のように伸びておりますけれども、ここは引き続き学校の用地として何らかの、入り口なのか、何らか使われるかわからないですけれども、引き続き学校の用地として使われるのか、それともこの角に、今いろいろ計画が進んでいるところと一体的になるのか、その辺の流れがわからないので、もしわかれば教えていただきたいと。","respondent":"小林施設整備課長","answer":"委員のご質問は、この旧校舎の下のほうの部分の通路のことでしょうか。","voiceIndex":126,"id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうことを考えるなら、今までの経緯も考えれば、外構はどういうふうに進めていくのだというのは、その都度変わってくるのは、それはそれでこの時期になってくるのはいいと思うのだけれども、先ほど、まさに言ったけれども、契約のあり方が、何でもかんでも入札という形とは、私はいつもここの部分はちょっと違った見方をしても、それのほうがコストも下がるだろうし。","respondent":"立川経理課長","answer":"取り合いの部分の調整が難しい工事については、一般競争入札はふさわしくないのではないかというご指摘です。この辺の考え方につきましては、今後検討が必要かというふうに思っているところです。","voiceIndex":130,"id":"exchange-044"},{"speaker":"中塚委員","kind":"意見","question":"問題のある再開発を進めるために学校を改築することは反対です。今回の議案は、開発を進めるという性格ではなく、御殿山小学校をつくる追加の工事ですので、今回の件は、この性格の違いも踏まえて賛成です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-045"}]},{"id":"topic-04","title":"議案審査の(7)、第７２号議案 大崎シルバーセンター等改築および解体工事請負契約","agenda":"議案審査の(7)、第７２号議案 大崎シルバーセンター等改築および解体工事請負契約","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"これ、契約方法が指名競争入札、今までずっと見ていると、制限付き一般競争入札なので、どうしてかということを教えていただきたいことと、あと、この２０ページで入札金額が１回目でこのＹ・Ｋ・Ｎの額が一番安くて、ここで終わるのではなくて、なぜ２回目をやって落札をしたのかということと、これの予定工事価格というのがないのですけれども、それは契約方法によって。","respondent":"立川経理課長","answer":"第２点目のご質問ですけれども、まず、指名競争に切り替える時点で一般競争と異なりまして、予定価格の事前公表は実施しないということになっております。それで、第１回目は全て予定価格を上回ったということで、第２回目を同日に実施しているです。","voiceIndex":144,"id":"exchange-046"},{"speaker":"中塚委員","kind":"質問・要望","question":"同時に、隣のもともと地域センターだったところが、その後どうなっていくのか、この図面を見ると、自転車置場が随分少ないようにも思うのですけれども、図面だけで見ると６台でしょうか。この空いたスペースのところに自転車を置くような形になるのか、それも誘導していくのか、建物だけではなく施設が隣り合わせですから、そういうところの検討がどうなっているのか伺いたいと思います。","respondent":"小林施設整備課長","answer":"そのために、今回は大崎在宅介護支援センターの上屋だけを撤去しまして、そこを防災的な広場にする計画です。先ほどの駐輪場の話については、その広場の一角に利用者の駐輪場をつくる予定です。今、そのような計画を立てています。","voiceIndex":147,"id":"exchange-047"},{"speaker":"中塚委員","kind":"質問・要望","question":"フローリングも大変使いやすい、たたみもやはりとてもよいですから、利用するにも、ぜひたたみの和室や和式というのは検討できなかったのどうか、検討していただきたいと思うのですけれども、いかがかということと、あと、だれでもトイレは１階平面図の真ん中あたりにあるのですけれども、この備品については先ほど指摘したとおりなので。","respondent":"小林施設整備課長","answer":"説明会につきましては、多分このまま議会の承認が１１月の末になりますので、その後の早い時期に工事説明会を開催する予定です。","voiceIndex":149,"id":"exchange-048"},{"speaker":"中塚委員","kind":"質問・要望","question":"たたみ敷きの和室ですけれども、ぜひつくっていただきたいという意見をよく伺いますので、十分検討していただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-049"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"今の防災広場というとずっとそのままになってしまうかもしれないのだけれども、例えば地域の高齢者の方々がゲートボールとか、いろいろな何かで使う場合の、それは使えるようにしてくださいと要望したと思うのだけれども、シルバーセンターはシルバーセンターでそれはあるのだけれども、ここの部分は、そういう使い方だと私は理解していたのだけれども、今の話だと、ちょっと違ってしまったかと。","respondent":"小林施設整備課長","answer":"済みません、答弁の中で、先ほど、防災的という「的」をつけましたので、基本的には目的は防災で、あといろいろな多目的に使えると思われます。申しわけございません。「的」が入ったと思います。","voiceIndex":152,"id":"exchange-050"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう形で安全を考慮していただきたいということがありますので、お願いしたいということと、それと、入札金額のところで、辞退が５件あって、ほか３件は金額が書いてあるのです。結果、先ほど、１回目は辞退されたというのは、１回目の３社が残って、２回目は辞退ということですか。そこをもう一度説明をお願いします。","respondent":"立川経理課長、小林施設整備課長","answer":"この１回目、２回目というのと、その前に制限付き一般競争入札で１回実施しておりまして、そういった意味合いです。１点目のご質問、奥まったところの安全性のカメラというのは、現在、カメラを設置する予定はございません。","voiceIndex":155,"id":"exchange-051"},{"speaker":"西本委員","kind":"質問・要望","question":"安全性については、状況を見ながら、ご近所の方々が安心になりますので、考慮していただきたいと思います。そうなると、この設定されている金額が、やはり無理のある金額という心配はあるのですが、そういうことは積算上問題ないという形で出されているのでしょうか。","respondent":"立川経理課長","answer":"本案件は、指名競争入札ということでございまして、そうしますと、予定価格というのは示されておりませんので、各社、試算をしていただきまして札を入れていただいたその結果がこの数字になっているです。","voiceIndex":158,"id":"exchange-052"},{"speaker":"西本委員","kind":"意見","question":"なので、そこら辺も前からの案件で話がありますけれども、適正価格というところが本当に大丈夫なのかというふうに感じてしまったのですけれども、その点に関しては、これでいいというふうになってしまうのか、やはり価格については少し考慮していかなければいけないというふうに思っているのか、その考え方をお聞かせください。","respondent":"小林施設整備課長","answer":"積算については、そのとき適正な積算方法だと思います。ただ、状況がやはり労務単価ないしは資材、それらが右肩上がりでまだ上がっているというところをどこで読むかというのは非常に難しいです。","voiceIndex":160,"id":"exchange-053"},{"speaker":"塚本副委員長","kind":"確認","question":"今の最後のところで確認ですけれども、制限付き一般競争入札で不調になって、この指名競争入札になったときに、予定価格は公表しないということですけれども、最初の制限付き一般競争入札のものというふうに思える、そういうものとして思っていくのでしょうか。","respondent":"立川経理課長","answer":"最初の制限付き一般競争入札についての予定価格につきましては、３億５８０万２,０００円です。それで、今回の落札額がそれよりも若干高いですので、予定価格は公表しておりませんけれども、前回よりは予定価格については適正にやっているです。","voiceIndex":162,"id":"exchange-054"}]},{"id":"topic-05","title":"議案審査の(8)、第７３号議案 東品川橋架替工事（上部工）請負契約の変更","agenda":"議案審査の(8)、第７３号議案 東品川橋架替工事（上部工）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"変更内容の２番と３番なのですけれども、撤去数量の変更が１,５９０万円の減、スクラップ数量の変更は２,３２７万円の増ということですけれども、この中身をもう少し詳しくご説明いただきたいと思います。","respondent":"稲田道路課長","answer":"この表の中の２段目と３段目の変更内容についてです。２段目ですが、仮設構台、本橋の周りに仮に車道部分を設けまして、西側に車道、東側に歩道の仮設構台、仮の道路を設けておりました。竣工を迎えるに当たりまして、それを撤去していくという工事があります。","voiceIndex":176,"id":"exchange-055"},{"speaker":"いながわ委員","kind":"質問","question":"関連で、構台撤去で護岸工事のために使用するという話だったのですけれども、でも、いずれは撤去するわけではないですか。それは東京都が負担する話になるということで、いずれまた品川区が撤去費用を出すのか、それはスクラップのほうもそうなのかもしれないですけれども、いずれ護岸工事が全部済んできれいな護岸ができたときにどうなるのか、それは東京都なのか。","respondent":"稲田道路課長","answer":"こちらの護岸なのですが、この東品川橋の橋梁架替工事で我々が護岸を壊した部分、壊したものの復旧をするというものです。というところで、我々区のほうで護岸を復旧していくというところで、この仮設構台も撤去して鉄材は売り払うです。","voiceIndex":178,"id":"exchange-056"},{"speaker":"いながわ委員","kind":"質問","question":"最終的にはこれがまたどこかで、品川区の予算なり、補正なり何なり、減額等がまた出てくるということで、今回はこういうことになったということでよろしいですか。","respondent":"稲田道路課長","answer":"今回は、この上部工の設計ではこのような形になっております。","voiceIndex":180,"id":"exchange-057"}]},{"id":"topic-06","title":"議案審査の(9)、第７４号議案 浜川雨水排水管建設工事請負契約の変更","agenda":"議案審査の(9)、第７４号議案 浜川雨水排水管建設工事請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"先ほどのお話なのですけれども、防音ハウスの撤去費と舗装復旧工事の変更についての中身をもう少し説明していただきたいと思います。","respondent":"奥田河川下水道課長","answer":"次の舗装復旧工事等の変更等ですが、今回、主要なトンネル部のところでは、国道１５号を横断するところがございまして、そこの部分を本復旧する予定でございましたが、これが次期工事でも一部掘削するということが出てありますので、本復旧しないということで。","voiceIndex":194,"id":"exchange-058"},{"speaker":"石田（秀）委員","kind":"質問","question":"今の件なのだけれども、昼夜やる予定だったと、次期の工事では夜はやらなくなったから、今度の工事でというのだけれども、もう一段理由を教えてほしい。もう一段理由を、ここの部分だけは教えてほしいと思っているのだけれども。","respondent":"奥田河川下水道課長","answer":"失礼いたしました。こちらの工事ですが、東京都から受託している工事でございまして、立会川周辺の浸水対策の軽減と、水質の改善のための事業でございまして、下流部を東京都がやる予定でございまして、上流部を品川区のほうでやっている工事です。","voiceIndex":196,"id":"exchange-059"},{"speaker":"石田（秀）委員","kind":"意見","question":"本当にそういう意味ではご苦労いただいて、東京都全体からもその意見書が各区それぞれ出ていく中、また、区議会に対しても出していくというようなご努力をいただいている中で、意見書がそろって初めて軽減措置を継続しているという状態が続いているわけで、我々としては、これは今、その状況下の中では、これについては採択をして、しっかり意見書を出していくべきだと、このように思っていますし。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":212,"id":"exchange-060"},{"speaker":"須貝委員","kind":"質問","question":"私もやはり同様で、毎年毎年こういうふうに出していくのではなくて、一般の人、事業をやっている人もそうですけれども、本当に大変な思いをして生活をしているわけですから、そういうことで恒久減税という方向に動いていってもらうように、区のほうからも区民の要求を生活実態を見てお願いをしていくべきではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":213,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問・要望","question":"１点伺いたいのですけれども、品川区としては、この軽減措置の今回の請願は継続ということなので、継続を東京都に求めているのでしょうか。","respondent":"黒田税務課長","answer":"冒頭の説明でも申し上げたとおり、地方税法の中で固定資産税等につきましては東京都が課税するというような前提となっておりますので、基本的には東京都の制度の中で検討されているものです。","voiceIndex":214,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"東京都が決めることなのですけれども、それに対して区としてここに書かれているように、非常に自営業者の状況が厳しいと、ぜひ継続してほしいと、こういう要請は東京都にはしていないということですか。","respondent":"黒田税務課長","answer":"いわゆる固定資産税につきましては、税法上の位置づけは市町村税ですので、本来であれば、市町村が自主的にいろいろ上限を制定するというような性格のものであろうと思いますが、税法上の特別区の区域内は都が課税するというものですので。","voiceIndex":216,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"要するに、区としてもこれを東京都に求めているということですか。いや、求めていないのであれば、毎回切実に寄せられているのに、区は一体何をやっているのだろうと思うのですけれども、しているのか、していないのか、そこがはっきりしないのでご説明いただきたいと思います。","respondent":"中山総務部長","answer":"自治体としてというふうに言えば、このように議会でご審議されて、議会によるお力を借りながら意見が出ているですので、区そのものの自治体としての要望はしていませんけれども、こういう形での姿勢は示されているということてあります。","voiceIndex":218,"id":"exchange-064"},{"speaker":"いながわ委員","kind":"意見","question":"これですと、品川青色申告会と荏原青色申告会の方が毎年毎年この請願を上げてこられて、本当に地域のためにいろいろご尽力いただいていることに敬意を表するところでありまして、この願意も理解するところがありますし、それに対しての理由づけも区でしていると。今回は、採択するかしないかの話ですので、うちの会派としては採択する方向で理解しております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":220,"id":"exchange-065"},{"speaker":"塚本副委員長","kind":"意見","question":"本日、結論を出します。今までるる議論あったとおり、恒久減税ということも視野に入れて、これはやるべきだということで、わが会派も同じですので、採択します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":223,"id":"exchange-066"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論を出すということと、態度は採択です。理由を一言述べますと、長期的な景気の低迷、雇用不安の拡大、生活基盤の圧迫、税や社会保障など負担の増加、この実態に即してこの事業は継続を求めるべきだと思いますので、賛成ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":225,"id":"exchange-067"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたいということと、採択するということで、私もこれは毎年毎年ご苦労なされて提出されているということは、本当にありがたいと思っています。継続は力なりということで、恒久的なというところもありますが、今後とも地域の方のご意見をどんどん区議会のほうにも申し出ていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-068"}]},{"id":"topic-07","title":"平成２６年請願第１６号 消費税率の１０％増税の中止を求める請願","agenda":"平成２６年請願第１６号 消費税率の１０％増税の中止を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"区議会としてぜひ意見書を上げて、消費税増税１０％をとめようと各委員に呼びかけたいと思います。それだけに、やはりマイナスをつくっている一番の原因が消費税増税ですから、ぜひこの区議会としても、与党も野党も一緒に力を合わせて、今、１０％に上げるのはやめようと、そういう経済状況ではないでしょうと、そこの１点で協力し合いたいと思いますので、ぜひ各委員の意見も伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-069"},{"speaker":"いながわ委員","kind":"意見","question":"先ほど、委員長が冒頭おっしゃったように、国で議論されていることであって、今、国も総理の判断をどうするかという話で、今やっている最中だと、たしか記憶しているのですけれども、そういう状況の中で区からそういった意見書を上げるというのは、しなくていいと思います。見守りたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":236,"id":"exchange-070"},{"speaker":"須貝委員","kind":"質問・要望","question":"中止を求める請願についてということで、請願の趣旨は、ここに書いてあるところは、おおむねは私は合っているのではないかと思うのですが、ただ、今、実際、医療、介護、子育てを含めて、社会保障費が毎年１兆円ずつ国全体で膨らんでいる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-071"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、いながわ委員に伺いたいのは、議論中だからこそこういう意見書を地方議会として区民の意見を上げるべきだと私は思うのですけれども、ぜひその旨を伺いたいと思います。ぜひ身を削るとか、借金を増やすというのは、私はそういう状況はないと思うし、税金を求めるところが違うのではないかと、別の道があるでしょうというふうに率直に思うのですけれども、聞かせていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-072"},{"speaker":"石田（秀）委員","kind":"意見","question":"それで、今、意見書の話は最終的に言うとしても、私の感覚で言うと、これは委員間の感覚だからそれで言うと、税というのは、応能負担による相互扶助がもちろん一つあっていいのと、あとは国民全体で税負担の公平性を持っていく部分と、そうなると、直接税と間接税の感覚、これはさまざま議論がされているところであって、必ず財源、財源という話が出てくるけれども、今。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":239,"id":"exchange-073"},{"speaker":"須貝委員","kind":"意見","question":"先ほど、大企業の話が出ました。でも、日本にとって、企業が生き残らないと雇用は残らない。うちも町工場ですけれども、では、会社が赤字になってお金がなくなったら国が助けてくれますか。その借金を背負ってくれますか。もしあのときデフレのまま行っていれば、消費税３％のままで国民負担はそんなに大きくなかったと私は思っています。燃料を含めて。私が、それは中塚委員に対する答えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-074"},{"speaker":"中塚委員","kind":"質問","question":"身を削るということですけれども、身を削るというのであれば、須貝委員はちょっとあれかもしれませんけれども、政党助成金をなくすこと、１年間３２０億円ですから、何年もやっているわけですから、身を削るというのであれば、こちらをやめるべきだというふうに思います。政府も認めているとおり、逆進性が強いということですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":241,"id":"exchange-075"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういう意味で言うと、相互扶助、それについては私も何とも思わないけれども、だけれども、日本国民として全体でみんなで負担をして、今、この社会保障、これが増えていくということもわかっているわけで、それをではどういうふうにしていくのですか、それを一企業の先ほど言ったように、大手企業からその部分で利益から、もちろん中小企業だって利益がやっと出たけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":242,"id":"exchange-076"},{"speaker":"中塚委員","kind":"提案","question":"大企業への課税は先ほどから指摘しているとおりで、共産党の消費税増税ではない別の道があるだろうというのは、大きく２つです。その内需主導の経済成長で税収を確保していくというのが我々の提案です。今の内部留保の様子を見ますと、結局国内で使い道がなく、どんどん増えているわけです。こういうところを正していくということが大事だと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":243,"id":"exchange-077"},{"speaker":"石田（秀）委員","kind":"意見","question":"これでやめるけれども、先ほど来、私も経済学者ではないと言って肌で感じているということを言っているので、各国の、今、中塚委員が言ったのは、私は何度も聞いている話をしないでと言ったつもりだけれども、今の話は何度も聞いている話であって、それは法の中で許されて話し合いでこういうふうにして、制度をこうしようとか、それはすぐ手が打てる話なのかどうなのかわからないけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":244,"id":"exchange-078"},{"speaker":"西本委員","kind":"意見","question":"意見書を上げてほしいということですが、消費税率の件につきましては、今、国のほうがいろいろやっているということは皆様からも出ていると思うのですけれども、主婦の一人である私としても、１０％になるというのは具体的につらいですよね。では、社会保障をこれからどうしていくのという中で、区民の皆様方も、上がるのは嫌だけれども、でも、仕方ないという方もたくさんいらっしゃるのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":245,"id":"exchange-079"},{"speaker":"中塚委員","kind":"意見","question":"紹介議員に共産党の議員がなっている関係もあるので、この消費税は福祉に使われず大企業への減税の材料に、わからないところなので、簡単に言うと、これは生活している者のすごく実感ではないのかと思うのですけれども、少なからずも消費税を４月に８％に上げるときに、全額社会保障に充てると安倍首相は盛んに説明されていて、今も言ってはいるのですけれども、４月以降どうかというと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":246,"id":"exchange-080"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"低所得者への負担感もある、先ほど、いわゆる逆進性という話もありましたけれども、そういうものは軽減税率とか、いろいろな形で補う部分はもちろんあるべきだと思うし、また、１０％に上げる時期、これは本当に経済に大きなインパクトを与えるので、これは取り組みによって国がしっかりと判断していただきたいというふうに思いますけれども、その点は別にあるとしても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":247,"id":"exchange-081"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、国でまさに議論されている最中ですので、本日、結論を出すということと、消費税１０％増税中止を求める意見書を上げるべきだと思いますので、採択を主張いたします。一言添えると、アベノミクスで好循環と言いますけれども、４月、５月のＧＤＰは通念換算で７％もダウン、この２０年間最悪ですよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-082"}]},{"id":"topic-08","title":"平成２６年請願第１７号 所得税法第５６条の廃止を求める請願","agenda":"平成２６年請願第１７号 所得税法第５６条の廃止を求める請願","exchanges":[{"speaker":"いながわ委員","kind":"意見","question":"今、税務課長がおっしゃっている、私もいろいろ調べたのですが、特に第５６条廃止をする必要性もなく、それに該当する方はさまざまな特例、要件に該当すれば特例を受けられるという説明がございましたので、先ほどおっしゃっていた青色申告会で申告をするなどすればよろしいかと思いますので、第５６条の廃止に関しては、私どもは必要ないと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":263,"id":"exchange-083"},{"speaker":"中塚委員","kind":"質問・要望","question":"質疑に入る前に、消費税については区の説明はなく、所得税については区の説明がある、消費税はなくて所得税はあるというのは、どういう理由があるのか。どちらも意見書を上げるものですから、委員会質疑の中で必要な説明を求めるというのは、それは質疑の中であると思うのですけれども、消費税と所得税と、その辺がよくわからなかったので、何か特段事情があったのでしょうか。","respondent":"渡部委員長","answer":"今回、所得税法第５６条ということで、実際、内容がわからない部分がありましたので、税務課長のほうにお調べいただいて、今回、説明を委員長として所得税法の第５６条についての説明をしていただきました。ただそれだけです。","voiceIndex":264,"id":"exchange-084"},{"speaker":"中塚委員","kind":"質問・要望","question":"議論を進めるに当たって説明を求めました。品川区議会でも所得税法第５６条の廃止を求める意見書を上げたいと私は思います。国会の中でもこの第５６条の廃止について、人権問題として、何らかの対応が必要だという議論や大臣の発言で言われているわけです。だから、特段の考えや理由があるのか、そこは率直に伺いたいと思います。所得税法の第５６条は、廃止すべき意見書を私は上げるべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":266,"id":"exchange-085"},{"speaker":"石田（秀）委員","kind":"質問","question":"それと、では、区として、別にそれは白色でも青色でもいいのだけれども、もし踏み込んで、例えば今言った青色になった場合だとしても、いろいろ特例とか、第５７条もあるわけで、第５７条、それから青色の特典、こういうことの話を突っ込んでするというようなことはあるのかとか、そこら辺の点をもうちょっと突っ込んで教えてもらっていいですか。","respondent":"黒田税務課長","answer":"所得税法第５７条についてですが、基本的に個人住民税の所得を算出して、それに応じて住民税率を掛けて税額を計算するですので、あくまでも所得の計算については、所得税法に基づいているですので、区のほうで何か言及するということではないというふうに考えております。","voiceIndex":267,"id":"exchange-086"},{"speaker":"石田（秀）委員","kind":"意見","question":"私はこういう形の中で、第５６条、白色で行っているよ、だけれども、この中で恣意的に、先ほど、所得税の話もあったけれども、恣意的にということであれば、お互い白も青も今は帳簿をつけなさいということにはなっているのだけれども、白の部分だけそういう部分が残っているという、だからそれは人権にという、こういうお考えだと思うのだけれども、私が思うには。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":269,"id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"私も同じで、紹介議員の方もここにいらっしゃって、今、中塚委員からもお話がありましたけれども、青色申告をすると、帳簿はきちんとつけて、そしてやると、いろいろこういう特典がありますということを私はやはり今、白色で申告されている方に、私は逆に教えてあげて、こういうふうに変えたらどうですかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":270,"id":"exchange-088"},{"speaker":"西本委員","kind":"質問・要望","question":"多分なのですが、請願の趣旨から読みとると、ここの第５６条の中に配偶者、括弧づけのほうですが、これがまさに女性差別的ではないのかということだけなのかとは思うのです。ただ、その思いをこの文章だけ、この第５６条だけ見た場合には、それを感じるというのはわからないでもないと思うのです。ただ、品川区では、廃止を求めるまでの意見書というのは出す必要性は私は感じておりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-089"},{"speaker":"中塚委員","kind":"質問・要望","question":"区に聞きたかったのですけれども、青色、白色ありますよね。私はそれぞれの事業所が自分の考えに基づいて判断することだと思うので、そこを教えていただきたいのと、それと、なぜ配偶者や家族だと恣意的な調整があるというふうに見ているのか、すごく失礼な話だと思うのです。それは、というのか、先ほどからの所得税法の説明の中で失礼だと、私はそれについても改めて説明していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-090"},{"speaker":"中塚委員","kind":"意見","question":"一言だけ。青色であっても、結局、特例扱いなのです。だから、原則、家族や身内は昔の判例に基づいてずっと続いているということなのだと思います。今の社会の仕組みの中で、これはまったくもって合わないと私は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":275,"id":"exchange-091"},{"speaker":"塚本副委員長","kind":"意見","question":"そういった男女共同参画とかという、女性の人権とか、そういうことで言えば、それはそれでしっかり議論する必要があると思いますけれども、第５６条がそれだから廃止だという論理には、ちょっと違和感を感じているので、私としてはそういうふうには思えないというところであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":276,"id":"exchange-092"},{"speaker":"中塚委員","kind":"質問・要望","question":"切実な願いですので、直ちに結論をとるということと、所得税法第５６条の廃止を求める意見書を上げるべきだと思いますので、採択を主張したいと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":281,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":283,"id":"exchange-094"}]},{"id":"topic-09","title":"平成２６年請願第１９号 政治活動用ポスター自粛に関する決議を求める請願","agenda":"平成２６年請願第１９号 政治活動用ポスター自粛に関する決議を求める請願","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ皆様の意見も伺いたいと思いますけれども、冒頭少し説明がありましたけれども、この政治活動用ポスターの掲示を自粛する決議を今回の請願は求めているわけですけれども、区議会事務局長に伺いたいのは、議会の決議というのは、憲法が認め現に行われている自由な政治活動に対して、冒頭説明のあった演説会開催の案内ですか、これを自粛しなさいと何らかの制限をかけると。","respondent":"原区議会事務局長、工藤選挙管理委員会事務局長","answer":"決議の種類につきまして幾つかあろうかと思いますけれども、今回の決議というところで捉えてみますと、事実上の意思表示といわれるもので、そういった意味では法的な拘束力はないというふうに理解をしています。私ども選挙管理委員会といたしまして、政治活動という部分に関してコメントしますと、政治活動は、政治上の主義、施策を推進し、支持し若しくはこれに反対し、又は公職の履行者を推薦し、支持し。","voiceIndex":292,"id":"exchange-095"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん自由だと言って他人の自由を奪うことは当然許されませんけれども、先ほど、品川区に聞いたのは、この区民憲章や人権尊重都市品川宣言、これに照らして今回の内容は人権侵害ではないかと、自由な市民活動、政治活動を侵すものではないかと、むしろそういう認識はないのですか。そこを伺いたい。それを自粛を求める決議が求められているときに、区はけしからぬという立場に立たないのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-096"},{"speaker":"中塚委員","kind":"質問・要望","question":"この中身は、議員を拘束するだけでなく、これから議員を目指そうとする人、まずは当選した人、それにもかかわる問題ですから、これは議員だけの議論ではなくて、区の民主主義としての立場も問われるという角度ですので、ぜひ説明をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-097"},{"speaker":"中塚委員","kind":"質問・要望","question":"結論は、第一義的に意見書を出すかどうかの結論は、この委員会が決めることです。この中身は民主主義にかかわる問題ですから、先ほどから紹介している区民憲章や憲法や人権宣言や、区はこういう立場を表明しているわけです。それに照らしておかしいのではないですかと説明を求めているのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-098"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけれども、それには政党団体用のポスターは認められている。目黒なども自粛をしているわけですけれども、これもお話を伺ったら、住宅街とかでさまざまポスターが張られているときに、そこにも書いてあるように、ポスターの撤去、処理とか、美観とか、そういうことで、それはいかがなものかという形で区議会に話があった。別に自粛の決議ですから、先ほども言った法的根拠はない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-099"},{"speaker":"中塚委員","kind":"質問・要望","question":"初めに、この民主主義の問題で、区が態度を示すべきだと思います。そういう意見があるから、お互いそうしませんか、議員同士、会派同士、それぞれで話し合い、断り、協力し合い、それは政治活動ですから、私がそうしろああしろとか言うべきことでもないし、ましてや議会が決議をもってああしろこうしろと言うべき性格のものでは全くないと思います。ポスター自粛を求めるとはまったくもって大反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":302,"id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"全て政治活動を制限する、抑制するということならば、私は、これは賛成はできないですけれども、やはり一部の人が立ち上がって、皆様、少なくとも品川区内はこれをやってみませんか、自粛しませんかという呼びかけですから、それは区民の皆様からこういう請願が出てきましたけれども、私は実際、一般の区民の方ならこういうふうに思われるということは私は自然ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-101"},{"speaker":"石田（秀）委員","kind":"提案","question":"そういうところはみずから理解をして、議員としてしっかりやっていきましょうと、それが例えば２３区であれば、台東区とか目黒区とか、いろいろなご意見があって、みずからそれはやっていきましょうということで自粛を求めるというか、自粛をしていきましょうという決議を上げているわけで、私らはそういうことも一歩踏み出してやっていくべきではないのかということを言っているということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":304,"id":"exchange-102"},{"speaker":"中塚委員","kind":"質問・要望","question":"私が問題にしているのは、それを議会の本会議の決議で求めるということに問題があると言っているわけです。ただし、それを本会議の決議で自粛しましょうと求めるのがおかしいということなのです、私の言っているのは。そういう活動の自粛を求める、制限を求めることが地方自治の発展の一翼を担う二元代表制の議会として、まさにみずから首を締める行為だと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":305,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"台東区、目黒区の話も出ました。請願者の方にもお尋ねしてきました。ですから、少なくとも自由度を与えられた権利といいますか、許可されているものに対して、それを抑えるようなことをやはり民主主義という観点から言うと、今やるべきではない、やるのであったらそれなりの同意を求めながら、品川区議会としての見解をきちんと出しながら皆様と決めていかなければならないものであろうというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":306,"id":"exchange-104"},{"speaker":"石田（秀）委員","kind":"意見","question":"請願者の方々がどういうふうにというのは、これは請願行為なので、時期はいつでもいいわけで、それについては、我々も知らない方ではないので、この時期に、これから張られてくるだろうということだと、お気持ちもあってということだから、そこについては、時期とかそういうものが出たら、別にいつであってもいいわけで、それはそれでいい。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":307,"id":"exchange-105"},{"speaker":"いながわ委員","kind":"質問・要望","question":"政治活動用ポスター自粛に関する決議を求める請願ということで、恐らく請願者の方は、公職選挙法にのっとったさまざまな部分、要は、政治活動の自由、言論の自由も含めた中で、ご理解をして提出をされたと私は認識しております。もちろん私たち議員として、重々理解しています。それはもちろん私たち政党人として会派をつくっている７人のうちの６人は政党人であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":308,"id":"exchange-106"},{"speaker":"須貝委員","kind":"意見","question":"今回、請願を出された方も、地域で代表として活動されている、活躍されている方で、さまざまな町会のほうでも、やはりいろいろ美観上どうなのかとか、まだ張っているとか、そういう話をよく聞きます。品川区内を見ると、本当に品川区の努力で、道路もきれいだし、公園を含めてさまざまな施設が美しく形成されている町だと考えています。それを最後に申し上げて終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":309,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"しかしながら、今どうですか、張っていますよね。ポスター。まさに政治というポスターですか。張っています。そういう追求をするのであれば、品川区はそういうポスターは一切だめと、自粛しろという形まで徹底しないと、完全な品川区の、どこまでのレベルを皆様おっしゃっているかわかりませんけれども、そこまでやる必要があるのではないかと私は逆に思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-108"},{"speaker":"石田（秀）委員","kind":"質問","question":"だけれども、その認められているものをどういう形で我々が区議会としてやれるのですかと、みずから先ほども律するというか、我々は区民の付託を受けて議員として活動をしているのであれば、まず区議会議員からやっていこう、それが都議会の人たちに波及するかもしれないし、国会議員の人たちも波及をするかもしれないし、品川区議会議員は、こういう形でやりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":311,"id":"exchange-109"},{"speaker":"中塚委員","kind":"質問・要望","question":"今も残っている政党のポスターは、顔写真が２つついている、だから、演説会開催案内ですか、ありますけれども、それは議会の決議で求めるのではなくて、それぞれが、「あそこ、残っていたよ」とか、町からこういう声が上がっているとか、そういう中で対処すべきであって、憲法のもとでも認められている活動を、区政における本会議の決議というのは、まったくもってけしからぬ話だし。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-110"},{"speaker":"塚本副委員長","kind":"意見","question":"ただ、それについても、確かに自粛、だから、張ること自体やめようというのは、さすがにそこまでの考えは至らなくて、それはここにしっかり自粛ではなくてみずから律することで区民の理解を得ていくというレベルでまず対応すべきではないかというふうに思っておりまして、やはり自粛の決議というところまでは、現状では考えるには至らないということであります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":313,"id":"exchange-111"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だけれども、演説会とかのこの部分があれば、それは認められる、それはもう全然それは構わないけれども、そういう意味では、区民の方にとっても、説明が紛らわしいことをみずからが行うことは、私はそこは改革できるところは改革していくべきだと思っているし、我々は区民の皆様から付託を受けて議員として活動しているその中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":315,"id":"exchange-112"},{"speaker":"いながわ委員","kind":"意見","question":"本日、結論を出すで、先ほど申し上げましたように、請願書の一部を理解する部分はあるのですけれども、最後のところでどうしても受け入れられないということで、不採択を主張します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":317,"id":"exchange-113"},{"speaker":"中塚委員","kind":"質問・要望","question":"憲法が認める政治活動の自由に対して、これに制限をかけることは憲法に反するし、本会議にそうした決議を求めることも許されないと思いますし、本会議自体、そうした権限を持っていません。この意見書を求めることは、結論を出すということと、不採択ということです。あわせて、自分で張ったら自分で剥がすと、本会議の決議を求める、制限を求めるものではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":318,"id":"exchange-114"},{"speaker":"西本委員","kind":"意見","question":"本日、結論を出すということで、先ほども意見を申し上げさせていただきましたが、議会改革という意味で言うと、やはりもう少し品川区議会という形の中で議論するべきものであろうと。それと、政治活動用ポスター、これは選挙違反ということなのですが、これは今までもやっている方はいらっしゃらない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":320,"id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1996#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":96830,"voices":327}},{"id":"h26-20141028-6","meetingId":"h26-cm10","date":"2014年10月28日","dateIso":"2014-10-28","committee":"区民委員会","time":"午前１０時００分～午後 ２時５６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を50件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"ＭＥＴＡＬＥＸ２０１４品川パビリオンの出展","agenda":"ＭＥＴＡＬＥＸ２０１４品川パビリオンの出展","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区でも、本当に高品質と高技術の製造業が頑張っているのだなという思いなのですけれども、このタイのバンコクで行われる出展のところに、去年は２,７００社ということなのですけれども、これは各国からで２,７００社、それで、日本では何社ぐらいどのようなところから行っているうちの品川区の６社なのかなというところを教えていただきたいのと、あとはこういう形で。","respondent":"山崎ものづくり・経営支援課長","answer":"品川区の本社のほうも、そのタイの現地工場と連携しながら双方で発展をしていくような形の海外支援の展開で、区としてもそういう意味での応援ができた１つのいい事例かなと思っています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いしますが、まず目的が書いていないのですけれども、前に委員会でも説明を受けましたけれども、改めて目的についてお伺いします。","respondent":"山崎ものづくり・経営支援課長","answer":"目的としましては、それぞれの企業の製品の販路を開拓し、その製品の売り上げ、あるいは受注などを増やすことによって、品川区に残っていらっしゃる本社機能の、いわゆる会社として成長していただきつつ、区の産業の活性化に寄与するということを目的に。","voiceIndex":7,"id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"そういう目的で海外にというのは、私は賛成なのですけれども、１社につき５０万円という話だったのですけれども、その５０万円の主要なものは現地への郵送だとか通訳だとかいうお話なのですが、実際はこの６社で分かれると思うのですけれども、大体企業がこうやって行くのに、１社当たり実質はどのくらいかかっているのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"おっしゃるとおり、郵送で少し重い金属機器を運ばなくてはいけないものと、パンフレット的なものでというような、企業によっては多少ありますけれども、平均しまして１００万円から１３０万円が総トータルコストで、区のほうの助成が先ほどの上限５０万円ということですので。","voiceIndex":9,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"４割から５割ということですけれども、そういうことが根拠で５０万円と決めたのでしょうか。実質的にかかる金額がそのぐらいだから、大体半分の５０万円でいいかなという根拠で５０万円と決めたのですかという、根拠をお伺いしたいのと、私はもう少しこの額を増やしたほうがいいのではないかという思いがあるもので、その辺も含めて答弁いただけますか。","respondent":"山崎ものづくり・経営支援課長","answer":"基本的に今までのそうした国内の展示会にかかる経費と、海外のＭＥＴＡＬＥＸも出展料としてはほぼ同額なのですけれども、そこに海外だからこそかかる経費をプラスの算定にしまして。","voiceIndex":11,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"私はこの助成額を上げていってもいいのではないかという思いで質問したのですけれども、今後のこの助成に対しての考え方というのは、今６社ですけれども、増やしていくとか、そういう意味において、今後の課題と対策、その辺について最後にお伺いします。","respondent":"山崎ものづくり・経営支援課長","answer":"区の産業振興の事業の支援として常に一番考えなくてはいけないことが、そうした企業のいろいろな自主的な、企業活動ですので自主的というのは当然なのですけれども、そこに公の区としての助成ということは、貴重な税金をそこにかけるわけですので。","voiceIndex":13,"id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"先ほどの説明の中で、何点か質問させていただきたいのですが、出展企業６社のうち、新規が３件で継続が３件と聞いたのですけれども、この継続の企業というのは、何年間継続できるのかとか、また新規のところは募集をかけるのか、希望を伺ってやるのか、どのような形でこのような企業の選定が６社に限られているのか、増やす可能性もあるのかも含めて教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"枠の６社といいますのは、予算の編成の段階で、昨年度の実施の状況ですとか来年度の見込みなども踏まえて、５０万円の６社ということで、昨年度もそうですけれども、今年度も引き続きということで一応枠設定をさせていただきました。","voiceIndex":15,"id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"先ほど、来場者が７万人ぐらいあると伺ったのですけれども、実際にこの６社で品川パビリオンですけれども、どのぐらいの方が見えているのか、いろいろ見ながら名刺交換などをされるのでしょうけれども、その数というのはどのぐらいの規模になるのかなというのをまず１つ教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"昨年のデータですけれども、同様の４日間の会期中におきます成果ということで、名刺の交換件数につきましては、６社合計で４７５件ございました。そのうち、何らかの商談が成立といいますか、４７５件のうち２１４件、成果のある商談が一応成立しております。","voiceIndex":17,"id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"これだけの商談が多いか少ないかというのは、評価するのは基準がなかなかないかと思いますけれども、これだけの機会があるということは、やはりほかの品川区内の企業にとってもこれはビジネスチャンスという見方も出てくると思いますので、今後こちらの地域におきましても、さらに拡大するかしないかということも見計らいながら、事業規模も検討しながら、区内産業の発展に努めていただければと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問","question":"来場者は大体何カ国ぐらいから来られるのか、把握していれば教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"出展のほうが、先ほどタイを中心としましたＡＳＥＡＮ諸国、中でも近隣のシンガポールですとかタイ、中国、韓国、こうしたアジアの部分と、それからＥＵ諸国のパビリオンが、各国７エリアでパビリオンができておりまして。","voiceIndex":20,"id":"exchange-009"},{"speaker":"本多委員","kind":"質問","question":"重なるのですけれども、（３）のその他支援メニューで、ビジネスマッチングという支援があるのですけれども、その事業展開を図る具体的な内容、区がここまでの支援を具体的にやるとか、その辺の役割を教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"それぞれ製造業ですので、必ず同じ相手とマッチングするわけでもありませんので、このＭＥＴＡＬＥＸを機会に、さまざまいろいろな企業が集まっておりますので、区としましては品川区という一つのブランドではないですけれども、区としての産業支援の振興の中で。","voiceIndex":22,"id":"exchange-010"},{"speaker":"井上委員","kind":"質問・要望","question":"いろいろとお聞きしたいことは委員の中から出てきたので、それを補充しながらお聞かせいただきたいと思うんですけれども、まず、先ほど出展６社のほうに補助の金額というような予算が出ていたのですが、その他支援メニューのところで、１７日に現地入りをして１８日に視察というような日は、誰がどういうことをするのかというのをちょっと説明していただいて。","respondent":"山崎ものづくり・経営支援課長","answer":"現地に行っていろいろな行程を計画させていただいてというようなことにつきましては、ソフト事業を現地で展開するわけですけれども、そこは区のほうの事業と、一部今年から品川ビジネスクラブに海外展開のソフト事業の委託をしておりまして、そこが予算では２００万円で。","voiceIndex":24,"id":"exchange-011"},{"speaker":"井上委員","kind":"質問","question":"この事務事業概要で、ＭＥＴＡＬＥＸ２０１３の出展費助成というのが、実績が１８８万９,０００円となっているのですが、これがさっき言われたソフトの部分の予算ということなのか、５０万円掛ける６の３００万円だったらちょっと違うなと思ったのですけれども、この経費というのは何を載せているのでしょうか。","respondent":"山崎ものづくり・経営支援課長","answer":"このＭＥＴＡＬＥＸの海外の委託については、ビジネスクラブのほうの支出のカテゴリーの中の一つに入っておりまして、それは平成２６年度からということで、事務事業概要のほうは平成２５年度のものですので、決算額については２９ページのとおりでございまして。","voiceIndex":26,"id":"exchange-012"},{"speaker":"井上委員","kind":"質問","question":"それとあと一つ、事務事業概要の３１ページに海外進出推進事業というのが３００万円ぐらいで、ちょうどこれが補助の予算なのかと勝手に私は思ったのですが、そういう資料のつくりではないのですか。","respondent":"山崎ものづくり・経営支援課長","answer":"それは手続上の問題で、区のほうの支援の一つとしてそれをやらせていただいているのですけれども、単体の企業が１つのブースに出たときには、それも必要経費として必ず入る部分でありますので、先ほどのトータルコストというのは。","voiceIndex":28,"id":"exchange-013"},{"speaker":"井上委員","kind":"質問","question":"先ほど目的というところで、やはり一番最初にありましたけれども、日本の企業をこういった形でアピールさせていただいて元気になるということは、すごく評価できると思うのですけれども、品川と日本をアピールするというお話がさっきありまして、そこで品川をアピールしていくということが、国内での支援とバランスを考えて、本当に先ほどもおっしゃったとおり。","respondent":"山崎ものづくり・経営支援課長","answer":"というのは、あのブースに入っている６社共通の、例えばパビリオンと同じカラーのＰＲをするようなパンフレットをつくったりしまして、そこの役割は、あのパビリオンをつくった品川区なりそこの行政として、パビリオン全体を東京の品川区から来ていますということで。","voiceIndex":33,"id":"exchange-014"}]},{"id":"topic-02","title":"番号制度導入に係る住民基本台帳事務における「特定個人情報保護評価」の実施","agenda":"番号制度導入に係る住民基本台帳事務における「特定個人情報保護評価」の実施","exchanges":[{"speaker":"浅野委員","kind":"質問","question":"多岐にわたっていて、なかなかこの場で理解するのが難しいところなのですけれども、内容としては個人情報を漏えいしないための手続をしっかりとやっていくという、簡単に言うとそういう内容かなと認識しているのですけれども、この中で２つほどお伺いしたいのですけれども、品川区情報公開等審議会という名前と、あと特定個人情報保護委員会の２つが出てきたのですけれども。","respondent":"井浦戸籍住民課長","answer":"ただいまのお尋ねの品川区情報公開等審議会と、それからまた新しい委員会として、特定個人情報保護委員会というものをご案内いたしましたが、まず、第三者点検を行います品川区情報公開等審議会につきましては。","voiceIndex":40,"id":"exchange-015"},{"speaker":"浅野委員","kind":"質問","question":"この品川区情報公開等審議会は昭和６２年に条例で設置されたというのですけれども、実際にどのようなことをされてきたのかというのを、今回また審議会にかけるということなので、ちょっとそこら辺の過去の経緯とか、また行ったことをお伺いしたいのと、あと品川区もこの内閣府の特定個人情報保護委員会に、今回の一連の作業をした後に結果をかけるということになると思うんですけれども。","respondent":"井浦戸籍住民課長","answer":"１点目の品川区情報公開等審議会につきましては、まず大きく２つ役割がございまして、１つは行政不服審査法の手続について、諮問を受けて区長に答申を行うということで、情報公開あるいは非公開について、法的な手続で不服申立てが出た場合に。","voiceIndex":42,"id":"exchange-016"},{"speaker":"浅野委員","kind":"質問・要望","question":"こういうセンシティブな内容ですので、区民の方が広く意見を出せるような環境は、これはぜひともつくっていっていただきたいと思います。それと、今回は黄色のところで区民の皆様の意見を伺うということなのですが、品川区の中での体制というのは何か特別な形を、今回のこれを皮切りにつくられていくのかどうかということについて、お尋ねしたいと思います。","respondent":"井浦戸籍住民課長","answer":"２点目の品川区での実施体制ですが、企画部が中心になりまして、４月ぐらいに全事業部長を構成員とするプロジェクトをつくりまして、全庁的に漏れなくこの番号制度の進捗が進むように、区として取り組んでいるところです。","voiceIndex":44,"id":"exchange-017"},{"speaker":"浅野委員","kind":"質問・要望","question":"そのような体制も組まれているということですが、前にも私どもの会派から質問をさせていただきましたけれども、情報統括管理者ですね。庁舎内では、やはり今後個人情報もそうですけれども、さまざまな課題というのがこれから出てくるというのは想定されるところでありますので、そういう意味ではこのような体制、ＣＩＯですとか補佐官ですとか、これをぜひとも構築していっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に複雑な仕組みで、全く新しい仕組みなので、いろいろと資料を読んでもなかなか理解できないところがたくさんあるのですけれども、この特定個人情報保護評価は、この日程表だと１０月までに評価書の素案を作成するということになっていて、今日は１０月２８日なのですが、まだできていない段階ということなのでしょうか。","respondent":"井浦戸籍住民課長","answer":"作成中です。それから、２点目の中身そのものにつきましては、こちらは１１月２１日より、所定の公表方法をもちまして公表を行う予定です。インパクトアセスメントの手続、影響評価ですので、そのような定められたルールの中で内容については公表していく考えです。","voiceIndex":47,"id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"例えば、確定申告にもこの個人番号をつけるようになる、いろいろな手続のところに番号がついてくるようになるのではないかと思うのですけれども、そこら辺では、この番号がつくものは、そもそもどういうところに番号がついていくのか、そしてこの本人確認情報ファイルの中身というのはどういうものなのか、また送付先情報ファイルというのは。","respondent":"井浦戸籍住民課長","answer":"１点目の評価書そのものにつきましては、全庁で順次評価を行ってまいりますので、現在は先ほど答弁したとおりですけれども、今後の課題として考えていきたいと思います。それから２点目です。","voiceIndex":49,"id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"そういうところで言うと、この特定個人情報保護評価というのは、今回こういう形で出てきましたけれども、この特定個人情報保護評価が今回は戸籍住民課ということで、戸籍住民課の住基ネット関連だけが出てきていますが、さらに社会保障分野、税分野、災害対策分野、それから独自の区条例で定める分野というところは、改めてこの特定個人情報保護評価というのがそれぞれに出てくるという考え方なのでしょうか。","respondent":"井浦戸籍住民課長","answer":"３つございまして、今回、それ以外の２つについては対象外なので説明はいたしませんでしたが、今後、社会保障や税のシステムについては、規模に応じた形で番号法の定める特定個人情報評価手続を行っていくという形になります。","voiceIndex":51,"id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうなると、ちょっとここの管轄ではないのかもしれないのですけれども、そういう情報管理というところでは、どういうスケジュールで税や社会保障の分野、今回の住基ネット以外のところの番号が使われる、その範囲ではプライバシーの保護をする個人情報保護評価のような形で、また区民にパブリックコメントで意見を求めてきちんと手続をしていくみたいなシステムにはなっていないということでしょうか。","respondent":"井浦戸籍住民課長","answer":"戸籍住民課で保有している住民記録システムの氏名・住所・性別・生年月日等が税や社会保障のシステムに連動しているといいますか、基礎になっておりますので、まず一番大もとの区で保有している行政情報の行政中の行政である住民記録システムにつきまして。","voiceIndex":53,"id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特定個人情報保護評価は、評価実施機関が特定個人情報ファイルの取扱いにおいて個人のプライバシー等の権利利益の保護に取り組んでいることを自ら宣言し、どのような措置を講じているかを具体的に説明することにより、国民・住民の信頼を確保することを目的とするものである」と書かれていますので、私はぜひ区民への説明会を実施していただいて。","respondent":"井浦戸籍住民課長","answer":"２点目の区民への説明会ということですが、今回、公募手続をする中で、広報紙等々でＰＲをしまして、どのように個人情報が守られているのかということについて周知をしてまいりたいと考えてございまして、説明会の開催は考えてございません。","voiceIndex":55,"id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"私たちがこういうふうに説明を受けても本当に理解するのは、こういうやり取りをしてもなかなか理解が難しいという段階で、広報紙で理解されると考えているのか、ちょっとその点についてはいかがでしょうか。","respondent":"井浦戸籍住民課長","answer":"広報紙でのご案内と同時に、ホームページでは評価書全文の掲載、あるいは用語の説明、あるいは概要的なものにも触れられればと考えていますので、できるだけ区民の方に安心・安全を確保していただくために区を挙げて取り組みたいと考えています。","voiceIndex":57,"id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここの指針の中でも、やはり具体的に説明することにより信頼を確保するということで、具体的に説明することによりと書いてあるので、この指針にも私は合わないのではないかと思うのですけれども、ほかの自治体では説明会とか何かはやっていないのかどうか、そこのところもお聞きしたいと思います。","respondent":"井浦戸籍住民課長","answer":"他の自治体で説明会を開催したということは、聞いてはございません。２点目のシステムの予算につきましては、情報システム課の所管ですので把握してございません。","voiceIndex":59,"id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にこういうシステムをつくるということでの説明ですので、そこのところはぜひ把握をしていただいて、改めて教えていただきたいと思いますので、よろしくお願いいたします。","respondent":"井浦戸籍住民課長","answer":"ホームページ、広報紙のほかに、東京都あるいは国も広報活動については力を入れていくですので、さまざまな媒体を通じまして説明に取り組んでいきたいと考えています。","voiceIndex":61,"id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"実際に不利益をこうむるというところにもつながっていくという問題ですから、私は区民にしっかりと説明をして、区民からの声もしっかりと受けとめるという姿勢こそ必要だと指摘をしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問・要望","question":"今の議論の中で、評価のシステム、税のほうはこれからのスケジュールが出ているのですけれども、社会保障については先ほど来規模というようなことを言われていて、国の指針が出ていないのでということだったのですけれども、規模という、それは努力義務なので、必要な評価というのは全て品川区ではやっていただきたいと思うのですが、でもそれは確実に評価をしていただけますでしょうか。","respondent":"井浦戸籍住民課長","answer":"戸籍住民課の所管ですので他の課のことについては答弁できる立場にはございませんが、区としては法律にのっとりまして、必要な評価については的確・着実に行いまして、区民周知に努めてまいりたいと考えています。","voiceIndex":64,"id":"exchange-028"},{"speaker":"井上委員","kind":"質問","question":"ちゃんとトータルで連携がとれていないですよと言っているようなものなので、ちゃんとそのプロジェクトで、戸籍住民課と情報システム課が部会をつくっているけれども、戸籍住民課長はちゃんとしたところにいるのですから、それは国の予算がまだついていないということに自治体は相当危惧をして、このぐらいかかるということしか言えませんとか、そういう状況だと思うのですけれども。","respondent":"井浦戸籍住民課長","answer":"システム改修につきましては別紙１の日程でございまして、全体的に平成２７年度の予算で執行するものですので、情報システム課サイドで見積もりは当然とってありますが、その見積もりについて財政当局で現在査定中ですので。","voiceIndex":66,"id":"exchange-029"},{"speaker":"井上委員","kind":"質問","question":"それで、基本的なことなのですけれども、今まで住基カードで番号が一応区民には報告されていまして、今回新たに個人番号が通知をされて交付が来るのですけれども、使い方としては住基カードの番号はもう何も使いませんよということで、これからの個人番号も、カードの交付は申請した人に配るという状況だと思うのですけれども、申請しなければ別に何も区民にとってはメリットもデメリットもなく。","respondent":"井浦戸籍住民課長","answer":"個人番号カードについては申請に基づいてお配りするものなのですけれども、今後、平成２９年以降につきましては、個人番号カードの利用の幅も国としてかなり拡大するということが予定として組まれておりますので、コンビニ交付等々の社会基盤も整ってありますので。","voiceIndex":68,"id":"exchange-030"},{"speaker":"井上委員","kind":"質問","question":"個人番号というのが行政から一方的にあなたは何番ですよというふうに、多分関連づけてでも何でもない番号が来るのだと思うのですけれども、そうするとこちら市民側で言えば、いろいろなときにその番号を使うときには、自分の関連した番号だから覚えられるというものを使うわけですが、そうではなくて、カードがなかったときにはそういう番号を覚えていなくてはいけないものなのか。","respondent":"井浦戸籍住民課長","answer":"紛失等々の事故につきましては、ご相談を聞きながら対応してまいります。","voiceIndex":70,"id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そうすると、この個人番号というのは、忘れてしまったら区役所に問い合わせをして、自分の個人番号をどういう形で、一番初めに通知カードが来年１０月に送られてきますね。そうした場合どうするのか。そこら辺の個人番号を書かなければいけないのはどういうところなのか、そこら辺の具体的なところで、あと個人番号というのはちなみに何桁なのかというのを教えてください。","respondent":"井浦戸籍住民課長","answer":"したがいまして、通知カードをご覧いただくですとか、個人番号カードをご覧いただきながらという形になろうかと思います。その運用につきましては、また区として課題を抽出して、区民の皆様がお困りにならないような手立てを検討していきたいと考えています。","voiceIndex":72,"id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的にどういうところに個人番号を書かなければならないという状況になっていくのか、そこら辺の具体的なところを教えてください。","respondent":"井浦戸籍住民課長","answer":"税分野につきましては、給与所得の源泉徴収票というものも所得税法で個人番号が記載されるというふうになってありますので、それぞれの局面で使われるのではないかと考えています。","voiceIndex":74,"id":"exchange-033"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それからあとは、例えば保育園の申込みとか、いろいろな申請とか、そういう手当を受けるだとか、そういうものも全てこの個人番号というのを付してその手続をとるという形に、多分健康保険も年金も、年金番号は今ありますけれども、そのほかに個人番号も、それから国民健康保険にしても個人番号もプラスでついていって、個人番号で全部その人の情報はとろうと思えばとれるという形に。","respondent":"井浦戸籍住民課長","answer":"さまざまな民間事業者、あるいは行政機関で個人番号は取り扱われますが、先ほどもご案内いたしましたとおり、個人情報の保護については各行政機関がしっかりとシステムでセキュリティをかけておりますので。","voiceIndex":76,"id":"exchange-034"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところでは、本当に改めて、一度漏えいされたら本当に取り返しのつかない状況になるというところで、そういうことが絶対にないように、システムをつくるとこととあわせて、今、各国でも先にやっているところでいろいろ問題になっていて、国によっては既に廃止をしていくというところもありますので、慎重にやるべきだし、そういうところを改めて区民にきちんと説明をしてやっていくということも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-035"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"質問なのですけれども、都市型観光アクションプランというこの１枚をいただいたのですけれども、ここの「品川の都市型観光に光を当てると、まるでプリズムを通した光のように、地域固有の様々な魅力を映し出す」と本当に何かすばらしい言葉で書かれておりますが、文学的な表現で書かれているなという思いで読ませていただいたのですが、この観光アクションプランというのは平成１８年にできて。","respondent":"米田商業・観光課長","answer":"そんな中では、１年かけてつくったわけなのですけれども、その間に商業・観光課ができたり、あるいはしながわ観光協会がかねてから路面に出ての観光案内だったりというようなこと、それからサイトの充実ということでは多言語対応していこう。","voiceIndex":87,"id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"平成１８年ということなので、かなり前の計画だということなのですが、そういう形で経過を追って、年を経て、では今後どうしていくのかというようなところでは、都市型観光というところでは、方針というか、そういう計画は今後つくっていくとか、そこら辺の策定の意思があるのかどうなのか、そこら辺のところはどういうふうに考えられているのかをお聞かせください。","respondent":"米田商業・観光課長","answer":"最初の１ページで説明しました都市型観光アクションプランのいわゆる４つの取り組みということについては、現在でも色あせてはいないだろうと考えています。","voiceIndex":89,"id":"exchange-037"},{"speaker":"井上委員","kind":"質問","question":"都市型観光というところから少しずれるかもしれないのですけれども、これは観光というものを考えたときの区としながわ観光協会のかかわりというか、区が観光に対してどこをやるのかというところがすごく疑問がありまして、それは委員会の中での皆さんとのトークという部分かもしれないのですけれども、私が考えてきた、多分商店街が観光であると捉えると、そこと連携するとかというのですけれども。","respondent":"米田商業・観光課長","answer":"あれも地域のお声を踏まえながら進めているというものですので、行政としてはそういった部分での私どもの部分とハードの部分の連携、また別の形でまちづくりのご要請等もあろうかと思いますので、そういったものを広く共有していくということが。","voiceIndex":91,"id":"exchange-038"},{"speaker":"井上委員","kind":"意見","question":"そこにまちづくり事業部隊も入らないと、開発とかでもあるので、そういう連携を品川区はもっと強くして、残すことがいいとは思っていないから、再生もありだと思うのですけれども、そういうところに力を入れたほうがいいのではないかなという意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-039"},{"speaker":"本多委員","kind":"質問","question":"資料６ページの外国人観光客誘致事業で、これまでやってきたもので、品川区の魅力を発信する４ページに掲載したＰＲとか、こういうのは継続的にやったり、例えば区民にもこういうのがあるというのを周知したり、そういうふうに拡大させていかないものかなと思うのですけれども、その辺はいかがでしょうか。","respondent":"米田商業・観光課長","answer":"今後もそのような形で進めていきたいと思っています。","voiceIndex":95,"id":"exchange-040"},{"speaker":"本多委員","kind":"意見","question":"羽田空港は大田区だから、なかなか品川区がそこに入っていくのは困難なのかどうかはわからないのですけれども、海外へ行っても大体中でパンフレット・冊子を見て、そういうのがまた空港をおりてもやはりくどいほどＰＲされていると思うので、できればそういった空港とかも、品川区を代表する来てほしいというようなところがたくさんあると思いますけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":97,"id":"exchange-041"},{"speaker":"浅野委員","kind":"質問・要望","question":"説明いただきまして、随分前からこのようなことをやられていたのは理解させていただきました。今後、このシティプロモーションと合わせた観光というのをどのように考えていかれるのか、また方針ごと、向こう１０年とかありましたら、教えていただきたいと思います。","respondent":"米田商業・観光課長","answer":"そういった形で、私どもの部門だけのものではないと思いますけれども、これから示されるものについては、観光としても一つの指針として、ともにＰＲをしてまいりたいと考えています。","voiceIndex":98,"id":"exchange-042"},{"speaker":"浅野委員","kind":"質問","question":"今、ご答弁いただいたとおりだと思います。ここについてどう取り組まれるのか、お考えを聞かせていただければと思います。それとあと、いろいろ聞きたいことがあるのですけれども、「しながわ百景」というのがあると思うのですけれども、最近あまり見ていないなと自分自身も思うのですが、この管轄はここのところでよろしいのでしょうか。違うのですか。１００から少し減ったと聞いております。","respondent":"米田商業・観光課長","answer":"そういった意味では、ダウンロードも一つの方法ですが、それ以外の方法で誘導するような取り組みができないかというような提案がありましたので、まだでき上がっておりませんけれども、現在そのような形で使いやすい。","voiceIndex":100,"id":"exchange-043"},{"speaker":"浅野委員","kind":"提案","question":"いろいろありがとうございました。１つ気になっているのは、立会道路の桜並木ですけれども、季節が春の時期はいいのですけれども、秋とかそういう時期になるとどうしても桜というのは見られなくなってしまう。私も思いつく限りは何かと提案しますけれども、ぜひとも調査しながら、来ていただく方におもてなしができるように、そういう工夫はぜひともこれからもお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":102,"id":"exchange-044"},{"speaker":"沢田委員","kind":"意見","question":"３つほどあるのですけれども、まず、４ページの海外からの国別の訪日外客数を見ると、先ほどもいろいろお話がありました中国とか韓国とか台湾、香港はかなりもう以前から来ているのでいいとしまして、これからタイとかマレーシア、フィリピン、ベトナム等がすごく大きな伸び率を示していて、先ほどＶＪ（ビジットジャパン）地方連携事業の中でも、今年度はタイ、マレーシア。","respondent":"米田商業・観光課長","answer":"訪日外客数の関係ですと、私どもも例えば上位のところの言語に対応しているのだろうかということで、常々このデータを見ながら考えております。","voiceIndex":103,"id":"exchange-045"},{"speaker":"沢田委員","kind":"質問・要望","question":"それからあと、今のクレジットカードのお話で、品川区商店街連合会も検討されたということで、海外から欧米の方とかも、特にアメリカはもうほとんどカード社会ですし、そういった方がいらしたときに小さいところでもカードが使えるというのは、そういったお店としても商売につながることだと思いますので、当時から時間がたっているということですが、ぜひまた進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-046"},{"speaker":"藤原委員","kind":"質問・要望","question":"そもそも論からまずお伺いしたいのですが、私の記憶なのですけれども、都市型観光というのが出てきたのは、たしかまだ産業振興課という１つの課のときだったから１０年前ぐらいかな、都市型観光は本当に意味がわからなかったのです。改めてお伺いしますが、都市にあるから都市型観光と呼ぶのですか。いわゆる京都とかは観光じゃないですか。もちろん品川区だけでも、どこに連れていきますでしょうか。","respondent":"米田商業・観光課長","answer":"２点目の私のほうで東京を案内するならということですけれども、まず多分どこか行きたいところがあるかしらというようなことでその辺のご希望を承って、やはり年齢であるとか、あるいはどういう形で、団体とかでいらっしゃるのかによっても大分違うかと思いますので。","voiceIndex":106,"id":"exchange-047"},{"speaker":"藤原委員","kind":"質問","question":"なぜそういうふうに伺ったかというと、前段の質問で都市型観光をどう思いますかという話で完璧に要点を押さえていらっしゃるので、本当にさすがだなという思いがあるのですけれども、３年前でしたか、区民委員会の視察で鹿児島市に行ったのです。それで質問で、東京都だったらどこへ行きたいですかと聞いたときに、しながわ水族館とかその辺を言ってくれるのかなと思ったら、スカイツリーに行きたい。","respondent":"米田商業・観光課長","answer":"そういった意味でも、品川区は商店街を大事にして、それはそれでまた別の政策かもしれませんが、進めていければと考えています。","voiceIndex":108,"id":"exchange-048"},{"speaker":"藤原委員","kind":"質問・要望","question":"要望も含めてなのですけれども、担当の課長としてそこを割いていただいて、区民一人一人が自信を持って、誇りを持ってというのも、みんなよく言うことですけれども「光を観る」というので「観光」といいますので、具体的にこうやって見て、今日出してくれた資料も見ると、品川区都市型観光の対象者とあるではないですか。７番でカップルなどと出てくるのはいいですね。あまりなかったですよね。そうですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":110,"id":"exchange-049"},{"speaker":"木村委員","kind":"質問・要望","question":"東京オリンピックが６年後にはやってくるということで、そういう意味ではまた海外の方々にも何か強くアピールができる。東京オリンピックを利用して、この品川区でも競技が行われる。多分そういうことだと思うのですけれども、いかがでしょうか。僕の考えは、藤原委員の後だからちょっと間違えているかもしれませんけれども、あまりおもしろくないでしょうけれども、いかがですか。","respondent":"米田商業・観光課長","answer":"そういった意味ではこういうものが絵になるんだということは、担当なりあるいはしながわ観光協会なりが勉強するとともに、やはり外国人の方の招致ということですと。","voiceIndex":111,"id":"exchange-050"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2710#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":57848,"voices":124}},{"id":"h26-20141028-7","meetingId":"h26-cm10","date":"2014年10月28日","dateIso":"2014-10-28","committee":"厚生委員会","time":"午前１０時００分～午後 ３時３９分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"はじめに、(1)の（仮称）東五反田四丁目認知症高齢者グループホーム等の整備および運営事業者の決定","agenda":"はじめに、(1)の（仮称）東五反田四丁目認知症高齢者グループホーム等の整備および運営事業者の決定","exchanges":[{"speaker":"山元委員","kind":"質問・要望","question":"前、現場を見に行ってきたことがあるので、すごいのができるんだなと思うのですが、１つは、この平面図を見たときに、こちらは駐車場とか、自転車置き場というのですか、あの辺は住宅街ですので、スタッフの方たちの通いというか、その辺はどんなふうに対応を考えていらっしゃるのかなということ。","respondent":"大串福祉計画課長","answer":"なかなか専門の形で駐輪設備をというのが難しいところかなと思っておりまして、平面図をつけさせていただいたところで、右側の面で身障者用の駐車場というのをしつらえておりますが、こちらが基本的には。","voiceIndex":14,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問","question":"２つの事業者から選定の申し出があったということを聞いているのですけれども、新生寿会ともう一つはどこだったのでしょうかということのお話。それから、新生寿会のほうが優れているという評価はいただいたのですけれども、選定した最も大きな理由を教えていただければと思います。","respondent":"大串福祉計画課長","answer":"結局はその２事業者でございました。もう一つの事業者のほうは、まずは提案内容としては２ユニットで１６名ということで、定員数が若干少なかった。それから、こちらの新生寿会のほう、先ほど説明の中でも触れましたけれども、１階に多目的室を設けています。","voiceIndex":16,"id":"exchange-002"},{"speaker":"伊藤委員","kind":"意見","question":"簡単なことですけれど、こういうプロポーザル方式で選定を行うことについては、それはそれでいいと思うのですけど、たまたま今回が２つのところだけの申込みであったと思うのですけれども、単純に何で２つなのかなと。例えばちょうど今、北品川の幼稚園の跡のところでしたか、今、つくっていますよね。単純になぜここが２者だけだったのかなということをお聞かせいただければと思います。","respondent":"大串福祉計画課長","answer":"この運営事業者の公募のときの報告のときにもご説明をしたかと思いますが、そうした条件に当てはまるのが区内では１５法人ほどいらっしゃったところです。","voiceIndex":18,"id":"exchange-003"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"これはまだ総事業費とか補助金の率とかはまだ決まっていないのでしょうか。","respondent":"大串福祉計画課長","answer":"今まだご提案をいただいたという段階です。今、そちらの事業費等については算定を行っているところでございまして、いずれは予算のほうでご提示をさせていただき、その中でご審議をいただければと考えているところです。","voiceIndex":20,"id":"exchange-004"}]},{"id":"topic-02","title":"の平成２６年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）の入居待機者の募集」","agenda":"の平成２６年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用・２人用）の入居待機者の募集」","exchanges":[{"speaker":"たけうち委員","kind":"確認","question":"募集の資格のところで、黄色い紙の申請資格のところで、(4)に独立して歩行、食事、着脱衣、入浴、排せつ、自炊可能な方（介護保険サービスを利用されていない方）とありますけれども、例えば登録して、空きが出て入るまでの間、場合によっては１年ぐらいかかってしまう場合があるかなと思うのですけれども、一応これを見る限りは、申請のときと入居が決まって入居するときの状況なども。","respondent":"白鳥高齢者いきがい課長","answer":"委員のご指摘がございましたように、これはお申込み時の段階でということで、身体機能の衰えというものは確かにありますので、そのときにお入りになる、空きが生じたときにご案内をする段階におきまして。","voiceIndex":27,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"そういう場合に、場合によってはまた別のところに移るということもあるとは思うのですけれども、そういう中で、以前に課長にも個別にご相談したのですが、例えばこの裏面の調理設備等のＩＨの器具もあれば、そうじゃない電磁式のものもあれば、ガスコンロのところもあるという中で、この辺はやはり区としては建設型などの場合にはある程度区のほうで考えてやれるのだと思うのですけれども。","respondent":"白鳥高齢者いきがい課長","answer":"確かに委員ご指摘の区立型のわかくさ荘につきましては、それぞれの法人のほうで手当てをしていますし、また、民間の借上型のほうの付帯設備につきましても、家主のほうの持ち分ということになりますので、そちらにつきましては、区のほうとも相談をしていただきながら。","voiceIndex":29,"id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問・要望","question":"その中でケース・バイ・ケースだと思うのですけれども、今、電磁式のものとかＩＨの場合というのは、スイッチを入れて熱くなっているのをわからなくなってしまって、置いてしまって、逆に火事になってしまったケースが多いみたいで、逆にガスコンロの場合は新しいやつだと、燃えると自動的に止まるというふうになっているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-007"},{"speaker":"伊藤委員","kind":"質問","question":"今の話にちょっと重なる部分があるのですけど、少しだけ認知症になった方が、やはりご自宅で空焚きをして、もうもうとした煙の中でひとりで座ってテレビを見ていたという話も聞いたことがあります。明治生まれの人で、こういうところに入居する年齢の方がいらっしゃるのかなと思ったのですけど、どうなのでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"古い方ではやはり９０歳を超えているという方もおられますけれども、お申込みの中で平均的なところにつきましては、７０歳代の方が多く、次いで６０歳代、８０歳代という方々が、ここ数年のお申込み状況からしますと、そのような年代の方がお申込みをされているという状況です。","voiceIndex":32,"id":"exchange-008"},{"speaker":"向委員","kind":"質問・要望","question":"私からは１点だけ。おおよそ募集内容はわかりました。このあたりは、今後改善されるご予定はあるのかどうか。ちょっとこのあたり、見やすく、ご家族とかが一緒に見て安心できるようにしていただけるのかなと、ちょっと要望なのですけどいかがでしょうか。","respondent":"白鳥高齢者いきがい課長","answer":"こういったことで、今回、一例としては平面図は載せしていますけれども、実際にはご自身の目で、ご家族の目でご覧になっていただいた上で、これまでの家財道具が入るのかどうかということも含めまして。","voiceIndex":34,"id":"exchange-009"},{"speaker":"向委員","kind":"意見","question":"わかりました。入るときはもちろん、どんな方でも借りるときは足を運んでサイズを測ってとすると思うのですけれども、あくまでもこの募集要綱というのは１つのバロメーターになると思うので、ちょっと間取り図については、今後ぜひ検討していただけたらと思います、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":36,"id":"exchange-010"}]},{"id":"topic-03","title":"の品川区障害者計画・障害福祉計画の素案","agenda":"の品川区障害者計画・障害福祉計画の素案","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"自立支援協議会というのの構成、どういうメンバーで構成されているか、あと日常的な役割みたいなものがあったら教えてください。","respondent":"中山障害者福祉課長","answer":"現在の部会の中に、実は児童の部会がないので、来年度以降は児童についても新たにその部会のメンバーとして加えていく予定になります。","voiceIndex":42,"id":"exchange-011"},{"speaker":"たけうち委員","kind":"質問・要望","question":"細かいことはまたいろいろあると思うのですけれども、また何か出てきたら、また後でお聞かせいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-012"},{"speaker":"伊藤委員","kind":"質問","question":"先ほどサポートブックの説明がありまして、厚生委員会の行政視察の千歳市の内容が、その前から言っていたかもしれませんが、実現されてよかったと思うのですけど、千歳市でもいろいろ勉強してきましたけれども、つくったはいいけれど活用されていないという話も聞いてきましたので、せっかくサポートブックを使うとあるならば、これを例えば区内の学校等々との連携とか。","respondent":"中山障害者福祉課長","answer":"この自立支援協議会の下にあります療育支援ネットワーク、子ども部会のところでは、区内の関係機関、教育委員会をはじめ、保健センター、そして障害者福祉課、児童学園、こういったところが一堂に会しまして、実際につくる作業からつくった後の活用方法。","voiceIndex":45,"id":"exchange-013"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もう１点だけ、先日ダウン症児を持つ親の会の方々とお話し合いをする機会があって、私も聞きかじりであれですけれども、確かに１つの障害の例に分類されるのだろうけれども、また別な対応なり計画を、ダウン症児の子どもたちのために展開していく必要があると聞いたのですけれども、今の障害福祉計画の中でダウン症児にはどういう対応をしていらっしゃるのでしょうかということが１点。","respondent":"中山障害者福祉課長","answer":"やはり障害があっても地域で育てる仕組みの構築と、それから障害児を育てる親のための子育て支援の充実、こうした中でダウン症を含む障害者のお子さんに対してきちっとした対応をしていくのが重要なんだというふうに思っています。","voiceIndex":47,"id":"exchange-014"},{"speaker":"伊藤委員","kind":"質問","question":"２３ページにも書かれていますように、医療の進歩によりＮＩＣＵを退院してくる重度の云々、要は相当早い段階からそういう現状はわかるわけですから、やはりそれについては、せっかく計画をつくる以上は、さまざまな障害に応じたお子さんの相談窓口と、その後のサポート体制と合わせて、これもサポートブックをつくるわけですから、ここにもとても重要な情報が載せられるわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-015"},{"speaker":"山元委員","kind":"質問・要望","question":"別紙２のところの、先ほど課長のほうからもご説明がありました7)の移動支援事業、先ほどフレンドリー事業の拡大ということもありました。この見込量としても、利用時間数が倍のように時間数が増えてくるようなのですけれども、もう少し何か詳しくというか、もしご説明していただけるのであれば教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"移動支援についてのお尋ねです。こちらのほう、通常の今までの移動支援の伸びでいきますと、例えば平成２７年度が５,８８０で、平成２９年度には６,５８０ぐらい、今までも移動支援というのは実は徐々に伸びつつあるので、その伸びを伸ばしていくとそのぐらいの数字になります。","voiceIndex":50,"id":"exchange-016"},{"speaker":"松永委員","kind":"質問・要望","question":"２３ページになるのですが、レスパイト事業というのがありまして、これを受けるための条件と、そしてどのくらいの支援をしてくれるのかという質問です。もう一つが、２７ページの障害のある方やその家族も地域において顔の見える関係づくりと書いてありますけれども、主にどういったことをやられているのか、ご説明いただきたいと思います。","respondent":"中山障害者福祉課長","answer":"今、それがうまくいっているかというと、なかなか地域差もありますし、全ての障害者の方がどういったところに、地域で過ごされているかとか、あるいは個別にどういった方がいらっしゃるかということが具体的にできているわけではないと思うのですけれども。","voiceIndex":52,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"４３ページの福祉計画の件ですけれども、真に施設入所を必要としている人や入所待機者の存在、待機者の状況や障害の重度化の状況等を考慮し云々と書きながら、この入所施設から地域生活への移行というところなのですけど、今、入所施設から地域生活への移行をしていった場合に、どういうふうに具体的になっていくのかというのが。","respondent":"中山障害者福祉課長","answer":"そういったことを目指すところです。それから、「真に」と書かせていただいたのは、実は国のほうは、この入所というのはどんどん減らしていきなさいと、地域移行をしていきなさいというのが国の大方針になっています。","voiceIndex":54,"id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そういうもとで傷ついて帰ってくると、もう行きたくなくなるというような話も見聞きするのですけれども、企業側への改善というか指導というのは、区としてはそういった権限はないのでしょうか。","respondent":"中山障害者福祉課長","answer":"そのときに、就労移行を使っているときには、就労移行だったり、あるいは就労支援センターのほうから職員が入ることもありますし、全体の場合は区からも企業のほうに電話をして、実際にそこの就労の担当者の方とお話をしたり。","voiceIndex":56,"id":"exchange-019"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうですね。やはりあったら相談する。それから、これから新しくできる児童学園にしろ、心身障害者福祉センターにしろ、直営でやってほしいという話は引き続き届いているのですね。これをしていかないと、障害を持たれた方の地域への移行であったり、そういったもののサポートというのがなかなか困難なのではないかなと思うのですけれども、そこら辺はどうお考えでしょうか。","respondent":"中山障害者福祉課長","answer":"それが直営なのかどうかというところはあるかと思いますが、現在は福祉職はもうかなり専門性が高くなってきていて、行政職員がそこに入ることで、専門性を逆にもらってくるということもあると思いますので、そういったような派遣研修。","voiceIndex":58,"id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"旗の台のところは別ですけど、それ以外のところは比較的品川地域や大井地区に比べて少ないような気がするのですけれども、何かそういう声とかで荏原地域のほうに施設をみたいな、施設というか拠点の整備みたいなお声がこの計画策定の中であったかどうかだけ教えていただけますか。","respondent":"中山障害者福祉課長","answer":"窓口をやる中でも荏原地域にというような話も私の耳にはまだ届いてはおりませんが、確かにどうしても海側に寄っているというところはありますので、この辺については移動の便も含めて今後の課題ということで考えさせていただければと考えています。","voiceIndex":60,"id":"exchange-021"}]},{"id":"topic-04","title":"の「しながわ健康プラン２１」の概要","agenda":"の「しながわ健康プラン２１」の概要","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"まだ素案だと思うのですけれども、それはもうちょっと主な呼びかけはもう少しほかのことが必要なのではないかと思ったのが１つ。もう一つは、妊娠期の両親の健康意識を高めるということで、この前の一般質問でも行ったのですけど、ぜひ妊婦の方に生肉を食べないようにということを、必ずこれを入れていただきたいと思うので、これは僕からの要望ということでお願いしたいです。","respondent":"川島健康課長","answer":"こころのほうも、少し入れるもの、どういう取組みを入れるかというのが、ぼやっとした部分にはなってしまうのですが、全て今のご意見を取り入れられるかはわからないのですけれども、素案の策定の中で少しご意見のほうを反映できればと考えていますので。","voiceIndex":66,"id":"exchange-022"},{"speaker":"向委員","kind":"質問","question":"何でそう思ったかというと、6)のほうは過度な飲酒はしないと結構ダイレクトに書いてあるのですよね。ちょっとこの２つ、かなり結構、５のほうはぼんやりというか、そういう柔らかいですけれども、６は結構鋭くぴしゃっと過度な飲酒は控えると書いてあるので、そのあたりのお考えをお伺いしたいのが１つ。もう一つは、この３の対象を明確にした健康づくりへの支援というのは、もっともだと思うのですよね。","respondent":"川島健康課長","answer":"対象を明確にしたという部分につきましては、最初、私どものほうが働き盛りの男性というような形で骨組みを考えていったのですが、委員の中からいろいろな検討の中で、これは働き盛りの問題ということになると、男性に限ったことではないだろうということで。","voiceIndex":69,"id":"exchange-023"},{"speaker":"向委員","kind":"質問・要望","question":"よくわかりました。なので、そのあたりもぜひ要望としてお伝えしますので、何とぞよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-024"},{"speaker":"伊藤委員","kind":"確認","question":"コンビニのものを買ってきて温めてそのまま出てきたりとか。だから、食育も結構掘り下げていくと深い感じがするので、そういうことについての品川区の計画となるわけですから、そのことの方向性を確認したい。せっかくいいモデル事業をやって実績が上がっているわけだから、それを品川区の健康づくりプランとしていくならば、参考にするべきだと思うのですが、いかがでしょうか。","respondent":"川島健康課長","answer":"過去、保健センターのほうでも、そういった取組みをまとめて庁内の連絡会というか、開催していることがありましたので、そういった形の会議を開催するのかどうかというのはあるのですけれども、このプランの策定をきっかけに、庁内に１つ串を刺すというか。","voiceIndex":72,"id":"exchange-025"},{"speaker":"伊藤委員","kind":"質問","question":"まさに今、横串を刺すとおっしゃったので、だからこそさっき言った文部科学省のモデルの事業があったり、恐らくいろいろな部署でやっているはずなのですよ。私たち、全部わからないけれども。だけど、まさにそれらに横串を刺していけば、このプランに対してすごく効果的なお話し合いができると思うのですよ。なので、それをやると言っていただけるとありがたいのですが、いかがでしょうか。","respondent":"川島健康課長","answer":"私のほうも不勉強で、具体的な国の取組みのどういったものが取り組めるのかというのはわからないのですけれども、実際に動いている事業で参考にできるものとかというのはどんどん取り込んでいければというふうに考えてあります。","voiceIndex":74,"id":"exchange-026"},{"speaker":"たけうち委員","kind":"質問","question":"国とか都で先んじて計画ができているわけですけれど、国の第２次のあれを受けて、そこでいろいろな数値目標なども出ているわけですけれども、ここのご説明の１.(3)の2)で、国や都で定められている指標を踏まえつつ、分野や項目をなるべく絞ってというふうになっているので、ここに出ている具体的な数値目標などもありますけど、これは絞ってこれだけしかとらないということになるのでしょうか。","respondent":"川島健康課長","answer":"国や都の指標目標値との関連性というか、整合性というお話だと思いますが、東京都の健康プランですと、１４項目ほど目標値の設定がありまして、現状とどのようにしていくかというところですが、これは都でとれる数字が区で全部とれるわけでもない部分もありまして。","voiceIndex":76,"id":"exchange-027"},{"speaker":"たけうち委員","kind":"提案","question":"わかりました。ここには出ていませんけど、さっきから出ている、入れるか入れないかはわかりませんけど、例えば視察した健康男子プロジェクトとか、また、我々もマイレージみたいなものも提案していますけど、そういう具体的な施策は冊子には載ってくるのですか。多分パブリックコメントのときには、そこまで載らないと思うのですけれども、冊子にはそういう何か具体的な施策というのは出てくるのでしょうか。","respondent":"川島健康課長","answer":"このプランの中で、直接的にちょっとどのような形で文章に書くかというのは、まだ何とも言えないのですけれども、企業との連携を進めていきたいというのが私たちの思いでもありますので、そういったものを落とし込んでいきたいと考えています。","voiceIndex":78,"id":"exchange-028"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"私も要望なのですけれども、歯と口の健康を保つというところで、健康意識を高めるのところにも、ぜひ歯と口の健康のところをちょっと書いていただきたいなと思います。生活習慣病の１つに歯周病などもやはり入ってくると思うのですね。さっきの障害者の策定委員会のように議事録なんかは公表されるのかをちょっと伺いたいと思います。","respondent":"川島健康課長","answer":"広くいつ委員会やりますよというお知らせをしているものではないのですが、もし、傍聴したいということであれば、拒むものではございませんので、それから、議事録もご要望でありましたらお渡しできますので、事務局のほうにお声かけをいただければと考えています。","voiceIndex":80,"id":"exchange-029"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"それで、パブリックコメントなのですけれども、この健康プランにかかわらずパブリックコメントをいろいろとられているのですが、どれぐらい集まったら区民の意見を聞けたというふうになるという、区としての目標というか、そういうものはないのかなと感じています。ですので、このパブリックコメントのあり方というのは、ちょっと今後考えていただきたいなと、これは意見ですけれども、思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-030"}]},{"id":"topic-05","title":"の「東京都大気汚染医療費助成制度」の改正","agenda":"の「東京都大気汚染医療費助成制度」の改正","exchanges":[{"speaker":"たけうち委員","kind":"質問","question":"ちょっとわかりづらいので、簡単に言うとこういうことでいいのでしょうか。来年の４月１日から施行されるのですけど、実際に今、認定されていて、ここに書いてあるとおり、認定されている方は平成３０年の３月３１日までは全額今までどおり変わらずで、平成３０年４月１日からは自己負担が６,０００円になる方が１８歳以上の方は対象になると。そういうことでいいのでしょうか。","respondent":"川島健康課長","answer":"説明がわかりにくくて申し訳ございませんでしたが、今のお話で結構なご理解だと思います。","voiceIndex":88,"id":"exchange-031"},{"speaker":"鈴木（博）委員","kind":"質問","question":"２つぐらいお聞きしたいのですけど、１つは全額負担が自己負担額６,０００円ということは、今要するに大気汚染というのは、ぜんそくにかかわって認定されたお薬だけ公費の補助が出ているのですけれども、それが６,０００円までは自己負担だということですか。","respondent":"川島健康課長","answer":"治療とお薬の分、合わせて６,０００円まではご自身で負担して、それを超える分を都が負担するような形に変わりますです。","voiceIndex":90,"id":"exchange-032"},{"speaker":"鈴木（博）委員","kind":"質問","question":"それは来年の４月１日以降ということですか。要するに今現在、気管支ぜんそくの公費負担の患者さんというのは、例えばお腹の病気で来た場合というのは保険診療で公費の負担というのは全くないのですよ。そのぜんそくで今まで無料でかかっていた分が、今度は６,０００円までは自己負担ということになるということなのですか。","respondent":"川島健康課長","answer":"ただ、この平成３０年３月３１日までどのような形で動いてくるかというのは未定なようでして、というのは、この自己負担額の金額とかその辺の話というのは、条例で定めているのではなくて規則みたいな形で定めているそうですので。","voiceIndex":92,"id":"exchange-033"},{"speaker":"鈴木（博）委員","kind":"意見","question":"わかりました。まだこれから詳しく詰められてくるということで理解しました。１点だけ、この一番最後の医療券の有効期限まで使用ができ云々というふうに２.(2)に書いているのですけれども、医療券の有効期限というのは、今たしか１年でしたか、３年でしたか。その期間で終わりだということなのですね。","respondent":"川島健康課長","answer":"期限は２年ですね。それで、この１８歳を超えた時点でもう更新ができなくなるというような形になるという予定です。","voiceIndex":94,"id":"exchange-034"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"本当にこの条例で、公害患者を見放すようなものだなということで、共産党も都議会ではいろいろと反対討論もさせていただいていますけれども、品川区で今、認定を受けている区民というのはどれくらいいるか、把握はされているでしょうか。そういったものを受けて、区ではどれぐらいそういった方がいるのかはわからないですけれども、こういう現状を受けて、区としてはどう思われますか。","respondent":"川島健康課長","answer":"こちらは、本来的には都、国のほうの責任でやる部分であって、区は認定ですとか、医療券の交付というのを担っている部分なので、なかなか具体的に区が何かできるかというと範疇は狭まってくるとは思うのですが、今回の改正を受けまして。","voiceIndex":96,"id":"exchange-035"}]},{"id":"topic-06","title":"視察の前に、予定表５のその他","agenda":"視察の前に、予定表５のその他","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"私どもは１０月２４日、鈴木真澄委員長がご質問になられた高齢者施策の中で、特別養護老人ホームの入所の考え方ということで、今までの在宅重視というよりは、施設ですとか、そういったところに入所しているほうを少し比重を上げていくような、それも比較的早い時期にそういう方向でというような答弁があったかと思いますので、その辺の考え方の経緯ですとか、また、いつ頃からそのようになるのかとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-036"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"日付順にいきますと、２３日の一般質問、飯沼議員の特養ホームの質問のところで、適地の検討をしている旨の答弁があったと思うのですが、どのような検討がされてきたのか、土地などが具体的に挙げられて検討されたのかを伺いたい。それから、たけうち委員と同じ入所調整会議のところで、入院者・入所者に配慮した入所調整をしてというところも、私も具体的に教えていただきたいと思います。","respondent":"永尾高齢者福祉課長、大串福祉計画課長","answer":"もう一つの紙おむつのことですけれども、紙おむつにつきましては、現状いろいろなニーズの調査等をしている中、また社会福祉協議会の意見、民生委員の方々のご意見。そうした中で並行して、特養をつくるのであれば適地が必要になってまいりますので、これの検討も併せて行っているです。","voiceIndex":106,"id":"exchange-037"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そうすると、次のということですから、３月ということで、やはりもう直近と言っていいぐらいの感じなので質問させていただいたのですけど、そうすると、基本的にはこの調整会議で、例えば残念ながら入れなかった方のところには、区のほうで何かお知らせというか文書で、こういう事情でというのはいっているのかどうかということと。我々議員の方もそうでしょうけど、やはりいろいろ要望されるわけですね。","respondent":"永尾高齢者福祉課長","answer":"ただし、そこで例えばＣ判定などになった場合、やはりその方はその先のことも予定しなければいけないので、必ず在宅介護支援センターだとか、区のほうにお問い合わせがありますし、ケアマネジャーもその後のケアについてのご相談も適宜承っておりますので。","voiceIndex":111,"id":"exchange-038"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"入所調整のところは本当によかったなと思っています。そうすると、入所調整にかかる方も増えてくると思うので、やはり特養ホームの増設をさらに進めていくことも必要だなというふうに思います。これは要望です。もう一つ、特養ホームの適地のところですけれども、そうすると、増設が必要ならば適地を検討していくということですか。もう１回確認をお願いします。","respondent":"大串福祉計画課長","answer":"特養の整備につきましても、先ほど申し上げたとおりです。第６期の介護保険事業計画の中で策定をしていく。それと並行しながら、もし特養をつくるのであればというところでの適地の選定、これも同時に行っていくといったところです。","voiceIndex":114,"id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3400#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":42786,"voices":125}},{"id":"h26-20141028-8","meetingId":"h26-cm10","date":"2014年10月28日","dateIso":"2014-10-28","committee":"建設委員会","time":"午前１０時００分～午前１１時３４分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"中延二丁目旧同潤会地区の共同建て替え計画","agenda":"中延二丁目旧同潤会地区の共同建て替え計画","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"ご説明によると、あくまでもまだ固まった状況ではないし、参考、イメージ図というところのご説明だったので、わかる範囲でお答えいただきたいのですけれども、ようやく形になって見えてきたというイメージを受けるのですけれども、高さが１３階建てということで、上に伸びるのだろうという思いはあったのですけれども、周辺の状況から見ると、あの周辺の建物は大体４階建てぐらいですか。","respondent":"鈴木建築課長、寺嶋木密整備担当課長","answer":"高さの規制についてのご質問については、私からご説明します。当地域につきましては、用途地域上、第一種住居地域というところでございまして建蔽率６０％、容積率が２００％のところです。それ以外のご質問に対してですが、まず、駐車場の形態ということです。これは先ほどもご説明したとおり、まだ案という段階なので、あくまでも図面に示されたものということです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なことで、この間も聞いたのかもしれませんけれども、改めまして、ここの旧同潤会地区の地権者の数と準備組合加入者の数に変化があるのかどうか、その辺を教えてほしいのと、総事業費とか、補助金はまだですよね。いつの時点でわかるのかというのを教えていただきたいのと、ここは防災街区整備事業という名のもとで、どういう補助金とかが該当するのかも教えてください。","respondent":"寺嶋木密整備担当課長","answer":"説明会の内容です。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"今の段階では、建設の形が固まっていないので、日影の影響とか、風の影響とか、そういった説明はまだ先ということですよね。その点が１点と、あと改めまして、コンサルタントを教えてください。","respondent":"寺嶋木密整備担当課長","answer":"日影の関係です。おっしゃるとおり、まだ案の段階、ただ、この案を出す以上、この案に対しての日影の設定は当然されておりまして、もし、この案のままいけば、時間当たりこういう日の移りがあるといった資料、説明は、我々は受けております。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"風環境も日影と同じくらいにわかっているのでしょうか。","respondent":"寺嶋木密整備担当課長","answer":"風のほうは、まだ報告は受けておりません。","voiceIndex":12,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１２月上旬の地区内の関係者の方々への説明会に、私などは参加しても大丈夫なのでしょうか。この間、すごく長い時間がかかっているし、いろいろなご意見がいっぱい出ていて、ちょっと参加させていただきたいなと思いますけれども、大丈夫でしょうか。","respondent":"寺嶋木密整備担当課長","answer":"先ほど説明会について２通りのご案内を差し上げました。都市計画法第１６条の説明会、区が主催するものにつきましては、権利者の方が対象と決まっていますので、まずこちらは限定されているということが一つ。","voiceIndex":14,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ということは、今の点ですが、準備組合に問い合わせをすればいいということでしょうか。区で確認してくださるということなのでしょうか。普通にしていたら、参加させていただきたいので、可能かと思っていますけれども、いかがでしょうか。","respondent":"寺嶋木密整備担当課長","answer":"説明会の日時が正式に決まりましたら、その報告が当然こちらに来ますので、その際、どういう方が対象になるかというのは、こちらでは情報を把握できます。それに応じてお答えできると考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"たたき台ということで、先ほどお話しいただいて、事業期間が平成１９年から２８年ということで、今、平成２６年ですから、もう既に５年以上たっている中で、事業の進捗状況は、そういう意味では、意識も変わりまして、この地区内には建て替えて、改築されている方が何世帯かあると思うのですけれども、そこらはどのように状況を把握されているのか。","respondent":"寺嶋木密整備担当課長","answer":"ただ、今度、全体としての計画として進めていくということなので、改めてこちらの事業の趣旨をご案内しつつ、今後、どういった形で協力が得られるかということにつきましては、時間をかけて懇切丁寧にご説明しながら進めていきたいと考えています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"こういう形で、防災井戸が書いてあるというのは大変珍しいのですけれども、この防災井戸はどれぐらいの規模を想定しているのですか。簡単にがっちゃんがっちゃんとできるような、井戸が出ましたというのではないと思うのですけれども、この辺は何か聞いているでしょうか。","respondent":"寺嶋木密整備担当課長","answer":"大変申しわけございません。これはいろいろな地区の情報をとって、こういったものがあるといいなと、あくまでもイメージ図ですので、具体的にどれぐらいの井戸がつくれるかというところまでを想定したものではなく、そこまで詳細な説明は受けておりません。","voiceIndex":20,"id":"exchange-008"},{"speaker":"松澤委員","kind":"質問・要望","question":"ここに書かれたということは、ぜひとも大規模な井戸を掘ってもらいたいのです。深井戸というのでしょうか、２００メートルぐらいをぐっと掘りますと、くめども尽きず水が出てきますので、飲料水に適さなくても、防災の貯水槽としては相当使えますので、東京消防庁などもこういう大きな深井戸をつくる場合には、助成金を出しているのです。よろしくお伝えください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-009"},{"speaker":"大沢委員","kind":"提案","question":"建設とは別なのでけれども、そこのところの歴史的な意義を伝えるべく、せっかくこの町並みをきれいに、概要のところでできているのですけれども、歴史を伝えるという部分では何かお考えになられてはいかがでしょうかという提案なのですけれども、それについてご意見を伺いたいと思います。","respondent":"寺嶋木密整備担当課長","answer":"ただ、ご指摘のとおり、検討に当たるときの資料で、実は東京大学の工学部がこちらの同潤会の写真とか歴史を入れた資料を説明会の場で提供されたというので、私も一度見せていただいたことがあるのですけれども、非常に興味深い白黒写真とか。","voiceIndex":23,"id":"exchange-010"}]},{"id":"topic-02","title":"大井一丁目南第１地区再開発事業","agenda":"大井一丁目南第１地区再開発事業","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１０月に組合設立認可を受けたということですけれども、改めて地権者数と本組合に参加された人数を教えていただきたいのと、総事業費、補助金の額も教えてください。","respondent":"溝口都市開発課長","answer":"事業費につきましては、約２６１億円が事業費、組合の事業になりますので、市街地再開発事業の補助金といたしましては、約３８億円の補助金が出るという計画になっているものです。","voiceIndex":29,"id":"exchange-011"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今日の資料の中で、施設用途のところに生活支援施設、子育て支援施設と店舗等と書いてあるのですが、子育て支援施設でわかっているところまで具体的に教えていただきたいのと、店舗等というのは、店舗数というか、フロアはどのぐらいあって、地元の方がここに戻られるというケースがあるのかどうか、そこもわかったら、教えてください。","respondent":"溝口都市開発課長","answer":"平米数なのですけれども、基本的に低層部、１階の部分に入れる予定になっておりまして、生活支援施設という形でくくっておりますので、子育て支援施設と店舗等一緒の面積になるのですが、約９６０m2の面積を確保するような形の計画になっております。","voiceIndex":31,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問・要望","question":"生活支援施設のところは９６０m2ということは、１フロアで、１階とか２階とか３階とか広がるという感じではなくて、例えば、１階部分とか、そういう感じなのでしょうか。","respondent":"溝口都市開発課長","answer":"今後具体的な計画にいきますと、多分工事の着手の前になると思いますが、中高層の開発指導要綱に基づく近隣説明会、要は工事説明会、どういう形で工事車両が搬入するか、工事期間がどうなるか、また工事期間中の騒音対策をどうするのかを含めて。","voiceIndex":33,"id":"exchange-013"},{"speaker":"飯沼委員","kind":"質問","question":"最後になります。補助１６３号線の支線１と書いてある、この支線というのは、どういう意味なのか教えてほしいのと、区画道路１号と２号がありますけれども、この道路がどのぐらいの道路幅になるのかも教えてください。","respondent":"溝口都市開発課長","answer":"それが補助１６３号線、この本線と補助２０５号線を結ぶ路線ということで、支線というのがついて、支線１、都市計画上の区切りの考え方になりますので、都市計画道路としては、同じ都市計画道路になりますが、名称として、位置づけが変わることによって。","voiceIndex":35,"id":"exchange-014"}]},{"id":"topic-03","title":"の事業系ごみ排出実態調査結果","agenda":"の事業系ごみ排出実態調査結果","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"事業系のところは、中身がなかなかわからない中で、いい調査だったと思います。ちょっとお伺いしたいのですけれども、１ページ目、図表１－１ですけれども、区収集ごみの資源持ち込みごみ量の推移ということなので、持ち込みも入っているので、事業系の資源回収もここに入っているということなのでしょうか。そういう部分も入っているものなのかどうかというのを教えてください。","respondent":"小林品川区清掃事務所長","answer":"そこが今後のごみの減量化、リサイクル推進の一つのターゲット、改革すべき分野と考えています。","voiceIndex":42,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問","question":"さっきコストの話もあって、別ルートをつくっても、安くないとなかなか利用できないというところがあると思うのですけれども、生ごみの資源化というのが、大きなところはすごく独自で進んでいるとは思うのですけれども、その辺の事業系でやられている部分と、あとやはり中小の小さなお店で、今、消費税などの問題で厳しい中で、生ごみを減らしていくというのはなかなか難しいかとは思うのですけれども。","respondent":"小林品川区清掃事務所長","answer":"具体策としては取り組みがなかなか難しい。基本的には、大規模のチェーン展開している店舗では、それを一定のルールで、中に不燃物ごみの混入を防ぐことができるので、それを堆肥、あるいは飼育飼料としてのリサイクルが具体的にシステム化されております。","voiceIndex":44,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問・要望","question":"多分中小のところは、なかなか前に進まないところがあると思うのですけれども、ぜひ共同の工夫とか、システムの構築とか、アドバイスとか、ご支援をしていただいて、少しでも前に進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問","question":"２点ほどお伺いしたいと思います。先ほど事業系のごみで、有料のごみ処理券を貼っていないというアンケートでの回答があったということがありましたけれども、再三指導されているところもあるということだったのですが、これはもう区としても、そういうところはもうかなり明らかな形で把握をされているということでよろしいでしょうか。","respondent":"小林品川区清掃事務所長","answer":"今ご指摘の適正排出の中で、主に組織的に対応しているのは、商店街区を中心に、全体の動きを把握しておりまして、貼るべきところが貼っていない場合には、警告し、時には周りの環境に配慮しながら、あえて取り残しをする中で。","voiceIndex":47,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"質問","question":"わかりました。多分ベテランの収集員の方が見ればすぐにわかることだというところで、取り組んでいただければと思います。その次のページだと、寝屋川市では、事業系の古紙を住民団体が回収するところに出した場合に報奨金を出すということもやっている。あえてこの二つを掲載されているというところで、今後こういった工夫を何か考えられるのでしょうか。どういったお考えなのでしょうか。","respondent":"小林品川区清掃事務所長","answer":"あるいは、今後許可業者と連携して、情報提供やルートづくり等を一緒にやっていくことによって、面的な拡大を考えていきたいという着眼点、あるいは資源については、例えば、紙であれば、一定の制約はありますが、事業所も。","voiceIndex":49,"id":"exchange-019"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろなご意見も出ているというところでしたけれども、ちょっとした工夫で、組み合わせで事業系ごみ処理が進むというところで、ぜひ進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-020"}]},{"id":"topic-04","title":"の補助１６３号線（東急大井町線ガード下区間）用地測量説明会","agenda":"の補助１６３号線（東急大井町線ガード下区間）用地測量説明会","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今の「品川区からのお知らせ」の下の図の赤線で囲われた事業範囲なのですけれども、この中に区役所の向い方に店舗がありますね。この方々はここからどくことになるのか、セットバックをしたりいろいろするのか、どういうふうになるのか教えてください。","respondent":"稲田道路課長","answer":"こちらのチラシの下段についてご覧ください。役所の向かい方、こちら側なのですけれども、計画線にかかるところは道路を整備していくという状況でございまして、建物が当たるところは下がっていただくという状況です。","voiceIndex":61,"id":"exchange-021"}]},{"id":"topic-05","title":"の台風第１８号・第１９号の対応","agenda":"の台風第１８号・第１９号の対応","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"今回もマンションは７０世帯ぐらいあるのですけれども、たまたまそのアプリが入っていたから、ああ、自分のうちだということに気づいたけれども、ほかの方はだれも知らなかったというところもありまして、チラシも入っていなかったというところもあるのですけれども、今後、例えば、防災スピーカーで吹鳴するとか、何かそういったことをお考えになられるのか、以上、５点。","respondent":"鈴木建築課長","answer":"今回この１６カ所のうち、建物等の立地状況等を勘案して、例えば、一つわかりやすくご説明しますと、大きい病院が指定区域に入っていたのですけれども、実際確認しますと、自然斜面なのですけれども、その自然斜面の直接近くにあるところが。","voiceIndex":69,"id":"exchange-022"},{"speaker":"あくつ委員","kind":"質問・要望","question":"せっかくやっても、届かない方というのがやっぱりいらっしゃる。先ほど、個別に状況を見て、チラシを入れる入れないというご判断がありましたけれども、道路一本隔ててということもあるかもしれませんので、周知の方法をまたお知らせいただきたいということと、段階について、避難準備情報とは一体何だということで、私も一瞬驚きましたけれども、そこについての周知もよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-023"}]},{"id":"topic-06","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"本当に龍馬が大好きで、鈴木防災課長も大好きだということを伺ったこともあるのですけれども、呼びかけ人がどなたなのかというところだけ、１点だけ教えてください。","respondent":"鈴木防災課長","answer":"呼びかけの事務局をしていただいているのは高知市です。以前、数年前に龍馬にちなんだ龍馬サミット等を実施した事務局が今回のきっかけです。","voiceIndex":88,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4122#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":28478,"voices":90}},{"id":"h26-20141028-9","meetingId":"h26-cm10","date":"2014年10月28日","dateIso":"2014-10-28","committee":"文教委員会","time":"午前１０時００分～午後 ４時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を74件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の平成２６年度小・中学校移動教室実施結果","agenda":"の平成２６年度小・中学校移動教室実施結果","exchanges":[{"speaker":"石田（し）委員","kind":"質問","question":"参加人数がそれぞれ出ているのですけれども、参加しなかった子の人数を教えてほしいのと、参加できなかった子の主な理由は何があるのでしょうか。","respondent":"野呂瀬学務課長","answer":"申しわけございません、手元に参加しなかった人数はないのですけれども、移動教室前健康診断をやっていまして、当日や直前になって体調不良で参加しないという児童・生徒は何人かいましたけれども、ほとんどはこの人数と同じくらいの参加者です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"つる委員","kind":"確認","question":"今の質問に関連して、人数の確認だったと思うのですが、体調以外で経済的な理由等、そうしたところでの児童・生徒、人数は特にあれですけれども、そういったことがあったかどうか、これがもしわかれば教えてください。","respondent":"野呂瀬学務課長","answer":"経済的な理由でというのは、教育委員会にもそういう声は入っておりません。就学援助の中でそのような補助はありますので、経済的な理由で参加を見合わせたという例はないと学務課では考えております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"高橋委員","kind":"質問","question":"中学校のほうですけれども、いろいろ状況があって２カ所になっていると思いますが、今後どちらかだけになるかとか、あるいは、このままこういう形で２カ所でやるのかというその見通しといいますか、もともとその二つという意味ですか。","respondent":"野呂瀬学務課長","answer":"今回５校で、来年度につきましては、まだ確定はしていませんけれども、１０校近くの中学校で実施するという話を聞いております。２年ぐらいのスパンで、全部、福島県に戻そうということで中学校移動教室の担当校長からは情報を得ております。","voiceIndex":9,"id":"exchange-003"},{"speaker":"南委員","kind":"質問・要望","question":"それで、結構、不登校の子供が横ばい状況であるという状況の中で、不登校の子どもも含めて参加できている状況なのかどうか、あるいは、できない方についてはどういう対応をしているのかというところを教えていただきたいと思います。","respondent":"渋谷指導課長","answer":"ただ、そういったイベント的な行事をきっかけに登校刺激を与えて、それをきっかけに登校するケースもあります。通常、不登校等で行かれない場合については、学校で補習をやるとか、別室で先生方が対応するというようなことで対応しているのが現状です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"そうすると、今年度については、そういう実態はあったということなのですか。不登校が数的には具体的な数字は、今までの横ばいということなので、その延長で考えているのですけれども、そういう学校等での補習も含めた、行けなかった実態はどの程度あるのか、数だけでも全校に一般的にあるのかも含めてわかるような形で報告いただけないかと考えています。いかがでしょうか。","respondent":"渋谷指導課長","answer":"後ほど調べてご回答さしあげたいと思います。","voiceIndex":13,"id":"exchange-005"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"移動教室の目的は、なぜこういう教室をやっているかということと、場所は、福島県は３.１１の後でいろいろ状況があったのだと思いますけれども、今、区全体、あるいは風評被害を防ごうというので、食品だの何だのをできるだけそういうところの物をという雰囲気が出てくるときに、教育委員会として、できるだけもとの姿に早く戻すように努力していただきたいと思いますが、そのあたりと、それから。","respondent":"野呂瀬学務課長、村尾学校支援担当課長","answer":"できるだけもとの姿に戻すということですけれども、緊急避難的に菅平方面をやって、もともと福島県のほうがいろいろメニューや、雨天時の代替メニューも多いことがありまして、評判が、今まで行った学校からの評判もありまして。例えば気候であったり、植物であったり、そういうものを踏まえながら現地に行って、さまざまな学習の成果を確認したり、または人間関係づくり等を含めながら、子供たちが楽しむところです。","voiceIndex":15,"id":"exchange-006"},{"speaker":"須藤副委員長","kind":"質問・要望","question":"ですから、いろいろな経緯があって受入れ側もそれなりに努力をしてきていると思うので、そういったことも歴史として承知しておいて、また３.１１という特別な状況がある。だから、そのあたりも同一のところでいいのかという話も当然出てくると思う。普通の学校の授業と違って、移動教室はいろいろな思い出が残ってくる場所だと思うので、ぜひこのこと自体はしっかりと取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"}]},{"id":"topic-02","title":"の平成２７年度小・中学校における土曜日の授業の実施","agenda":"の平成２７年度小・中学校における土曜日の授業の実施","exchanges":[{"speaker":"須藤副委員長","kind":"質問・要望","question":"今の説明で、地域祭礼等の関連でということで、これは土曜日授業を再開するときに、我々議会のほうで、地域でもお休みだったというのでお子さんたちの連携をとっている地域があっているので、そのあたりも配慮してくださいということに続けて応えてくれていると思いますけれども、ただ、基本的には学業が先になってくると思うので、このあたりも地域の方と話をしながら、第１・第３土曜日は基本的に勉強する。","respondent":"渋谷指導課長","answer":"大変ありがたいお言葉だと思っています。これも３年目になりまして、地域や地域のスポーツの関係者の方たちも十分ご理解いただいているところではありますが、引き続き十分協議を進めながら、混乱のないように進めてまいりたいと考えています。","voiceIndex":23,"id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"そういう中で土曜日の授業ということも出てくるのであれば、私は違うと思うので、先ほど言ったように、地域との協力、保護者が、自分の子供がどのような姿で学校の友達との関係があるのか、先生との関係はどういう姿を見せるのかということをしっかり見ていくという点で、土曜日に行事をして、そこに父母が参加できる状況をしっかり保っていただけることは大事なことだと思いますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-009"},{"speaker":"須藤副委員長","kind":"意見","question":"だからといって、地域のお祭りだ、クラブのスポーツだ云々ということにシフトするということではなくて、本来の目的に沿ってやってくださいというお話をしているだけなので、今のゆとりをどうのというのは、私はまた今の意見とは違いますということをはっきりお願いしておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-010"},{"speaker":"高橋委員","kind":"意見","question":"１７日出勤される先生方のこの日に出勤したときの処理のことですけれども、１学期に５日か６日ぐらいやって、その次の長期休業中に処理していく状況なのかということで、それが確保していただけているのかということです。特に中学校だと、長期休業だとクラブなどもあるので、とりにくい側面がありますけれども、そのあたりの各校の状況をお願いします。","respondent":"渋谷指導課長","answer":"前２カ月、後ろ４カ月の間の中で確実に振り替えをするということで、品川区の場合は電子できちっと休暇を処理しておりますので、土曜日出勤の場合については必ず振り替えるよう設定しているということは管理職も徹底しておりますので。","voiceIndex":27,"id":"exchange-011"}]},{"id":"topic-03","title":"の「平成２５年度保護者アンケート」「平成２５年度児童・生徒アンケート」の報告","agenda":"の「平成２５年度保護者アンケート」「平成２５年度児童・生徒アンケート」の報告","exchanges":[{"speaker":"南委員","kind":"質問","question":"一つは、先ほどの説明にもありましたように、学校選択制について伺いたいと思いますけれども、保護者対象にとったアンケートでは、地域行事とかボランティア活動に参加させていることについては、小学校、中学校とも５０％程度いて、通っている学校と地域の連携は８５％ぐらいとれているという認識を持っている保護者の方ということで、そうなのだと思ったのですけれども。","respondent":"野呂瀬学務課長","answer":"今後も同様の該当者、また、その親御さん等も含めて、ＰＲにはこれからも充実して図ってまいって、誤解のないような形で今後とも学校選択制を進めていきたいと、このように考えているところです。","voiceIndex":33,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"そういう方たちの意見を聞いて改善させることも含めてきちんと、せっかくアンケートをとったわけですから、聞きっぱなしでなくて次につなげることも含めて真摯に向き合っていくべきなのではないかと思いますけれども、そこについてはどうでしょうか。","respondent":"野呂瀬学務課長","answer":"例えば地域との連携が薄れるのではないか、そういうご意見もいただきまして、学校選択制は学校選択制の制度の中で進めていくけれども、またそれは一方でそういう課題につきましては、その課題をいろいろな事業や方法でクリアしていきたい、このように考えているところです。","voiceIndex":35,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"４・３・２年についても、子どもの学びや発達に合っているのかという質問をされているのですけれども、「合っている」と回答しているのが５０％で、逆に、合っているとは必ずしも思っていない保護者が半数近くいる点について、これはどういうふうに受けとめているのか伺いたいと思います。","respondent":"渋谷指導課長","answer":"今後、そういった意図的にまとまりをつくって、教育効果をその子どもたちの発達段階に合わせて、より効果的に行っていくさまざまな取り組みについては、きちっと保護者、また児童・生徒にも説明して効果的に進めていきたいと考えているところです。","voiceIndex":37,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"長い日本の戦後の歴史の中である節目を、それなりの必要性があってそういう教育の制度にしているわけですから、それはそれとして大事にしていただきたいと思っています。それとの関係で、ぜひ再度見解を伺いたいと思います。","respondent":"渋谷指導課長","answer":"この４・３・２年のまとまりにつきましては、今後、義務教育学校、小中一貫教育学校が法制化等々されます。そうなると、９年制の義務教育を考える新たな仕組みを検討しなければならないと思っています。","voiceIndex":39,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"設問３８ですが、「他地区より授業時間を増やしていることについては良いことだと思う」と、そういう設問ですが、８割の保護者の方が「良い」と答えておられて、一方、設問５では、家庭学習の習慣は、先ほども説明がありましたけれども、小学校で８１％、中学校では６０.５％となっている、ここについてのこの関係は、どういうふうに教育委員会としては見ているのか、その辺について伺いたいと思います。","respondent":"渋谷指導課長","answer":"一つは、きちっと質の高い授業、また、一定時間の授業の中でしっかり学力を身につけさせること、あともう一つは、そういったものを受けて、きちっと家庭で自学自習に取り組む習慣づけをしっかり行うことが重要だと考えているところです。","voiceIndex":44,"id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"がんがんやれば机に向かうというものではないわけですから、なぜ勉強することが大事なのか、勉強して物事がわかったときの喜びを子どもに体験させることがなくては、勉強に自発的に向かわないと私は思うのです。そういうところの働きかけや考え方についてどうなのかを最後に伺って終わりにしていきたいと思います。","respondent":"渋谷指導課長","answer":"ただただ「勉強、勉強」と言うことではなくて、何のために学ぶのかのような、そういったことについては引き続きしっかりと指導して、学習ができるような環境づくりに取り組んでいきたいと考えています。","voiceIndex":46,"id":"exchange-017"},{"speaker":"吉田委員","kind":"質問","question":"「平成２５年度保護者アンケート」「平成２５年度児童・生徒アンケート」ですけれども、私、聞き逃してごめんなさい、前にもほかの年度でもやっていたのかということをお聞きしたいのと、今後もやっていくのかをお願いします。","respondent":"渋谷指導課長","answer":"全保護者アンケートを実施しているのは、平成２４年度から正式にはやっておりまして、平成２４年度のアンケート結果については、もう既に区のホームページにデータをアップロードさせていただいているところです。","voiceIndex":48,"id":"exchange-018"},{"speaker":"吉田委員","kind":"意見","question":"それは、例えば計画的に具体的に今後もとおっしゃって、例えば毎年やっていくのか、でも、毎年といっても、なかなかその成果があらわれないのではないかと思いますけれども、５年後とか、そういうご計画があるなら、最後に一つお願いいたします。","respondent":"渋谷指導課長","answer":"来年度のアンケート項目等々についても既に検討しています。したがいまして、予定ではありますが、来年度もまた毎年、継続してとっていきたいと考えているところです。","voiceIndex":50,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"時間もあれなので、概略的にお答えいただければと思いますけれども、５点ほどあります。これは人間の集まりですから、そういった考えのお子さんがいるのは、それがある中で、今ままでも、これまでもずっと取り組んできたことも含め、こうした数字を出した中、どういったアプローチをさらに考えていく必要があるのかということ、以上５点を教えてください。","respondent":"渋谷指導課長","answer":"最後、５点目のいじめに関してですが、確かに１００％というのは、こういうデータでは難しいところですが、でも、１００％を目指して豊かな子どもの人間性、いじめを許さない、そういったものをしっかりと考えられる子どもを育てるように。","voiceIndex":52,"id":"exchange-020"},{"speaker":"渡辺委員","kind":"質問","question":"そういう中で、もちろん先ほどの質疑にもありましたように、毎年の必要性は十分ありますし、逆に答える側も、マークシートということもあって年に１回ということであれば、それほどの負担感はないであろうと。これは３月。いろいろな考えがあって３月だとは思いますが、それはそれでいいと思います。これはやむを得ないことなのか、もうちょっと前倒しができるものなのか、まずその点を教えてください。","respondent":"渋谷指導課長","answer":"児童については、時間の中でぱっと子どもたちに配って、そこで書いてもらって回収するということで、一人ひとり持ち帰りではなくて、学校の教育活動の中でアンケートを実施して回収しているというやり方をしています。したがって、非常に回収率は高い形になっているです。","voiceIndex":54,"id":"exchange-021"},{"speaker":"渡辺委員","kind":"質問","question":"最後に１点だけ。児童・生徒のアンケートは今年からということで、これも非常に大切なデータだという中で気になったのが回答率、学校で教室内でやっている中で、細かい話ですが、１００％に行かないところ、これで言うと４.５％、僕はこれがすごく学内でやっていて回答ができないのはなぜだろうと。これはどのようなことが想定されるのか教えてください。","respondent":"渋谷指導課長","answer":"これもマークシートの関係で、きちっと塗れなかったとか、設問１個のところを２つ以上回答してエラーになってはじかれてしまったとか、または、やりたくなくて白紙で出したりだというところが若干あったのかなです。","voiceIndex":56,"id":"exchange-022"},{"speaker":"高橋委員","kind":"質問","question":"２点お伺いするのですが、保護者のほうは設問３５で「小中一貫教育に期待する」というところで、「学力向上」、あるいは「学習意欲の向上」がトップにあって、それがどのような状況かという検証のすべは、どういうふうにして期待に応えてこうなったというのを示す、そういう方策、今、小中一貫教育の検証をされていると思いますけれども、期待がこれだけあるので。","respondent":"渋谷指導課長","answer":"１点目の学力向上と小中一貫教育との関連性については、具体的にどういうふうに見ていくかというご質問については、これは非常に難しいと思っています。","voiceIndex":58,"id":"exchange-023"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、保護者の方は学力向上に期待をすごくしているのですけれども、今のようなお答を保護者の方にしても、余り理解していただけないというか、こういうことだったから学力向上しましたというような形で材料をそろえていく必要があるのではないかということです。今のお話は、すごく質問の中でこの選択肢が入るのはあれだと思うのです。期待に応えるというか、そういう意味で。","respondent":"渋谷指導課長","answer":"こういった保護者のほうでそういったさまざまな施策の中でも、特に学力面でしっかりと力をつけてくれというご期待はしっかり受けとめさせていただいて、小中一貫教育という仕組みの中で、例えばステップアップ学習であるとか、習熟度別学習であるとか、教科担任制であるとか。","voiceIndex":60,"id":"exchange-024"},{"speaker":"高橋委員","kind":"質問","question":"１年生は、質問を簡単なものでもいいので、例えば学習時間とか１年生でも答えられるような設問を、全部ではなくてもいいからピックアップしてやっていくと、例えば学習時間であったら１年生は何時間で２年生は何時間、そういうのもこのアンケートは非常に貴重で、いいチャンスだと思うので、いろいろ担任の先生方のご苦労もあるかと思いますが、幾つでも質問して。","respondent":"渋谷指導課長","answer":"そうすると、説明をすることで、担任の先生の説明の仕方によってバイアスがかかってしまって、アンケートの結果にかなり大きな影響が出てしまったり、そういったことを勘案すると、対象として１・２年生を入れることはどうかという意見が大多数だった。","voiceIndex":62,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"先ほどの引き続きですけれども、わかる学習をしっかりつけることと、そういう点で先ほど質問したら、市民科でなぜ勉強が必要なのかを学ぶ、そういう授業を通して身につけるというお話だったのですけれども、私は、それはそれであり得ることだとは思うけれども、そうではなく、もう少し子ども自身が学ぶ、例えば算数でこういうふうにやると答えが出るとか、その道筋がわかるとか。","respondent":"渋谷指導課長","answer":"ご質問が抽象的なので、具体的にお答えしにくいですけれども、授業でわかることを目指して取り組む、一人ひとりの子どもたちがわかる成就感を達成していくのは、教師の本来業務で、そもそも論のところですので、教育改革、小中一貫教育とかそういったことを除いたとしても。","voiceIndex":64,"id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"そうすると、具体的な授業の中だとか、あるいは放課後の時間だとか、いろいろな学校生活の中でそういう体験をどれだけ子どもにさせるか、そういう姿勢は全ての教師が持っていますと、それは持っていると思います。その条件整備について、どういうふうに考えて図っているのかをはっきり見ていきたいと思っているので、質問をするわけです。漠然とはしていますけれども。","respondent":"渋谷指導課長","answer":"習熟度別学習については、品川区は指導助手という区費をつけて、積極的に取り組んでまいりました。","voiceIndex":66,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"要望だけにとどめたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-028"},{"speaker":"須藤副委員長","kind":"意見","question":"一生懸命アンケート自体は、今、皆さん、評価したようにすばらしい結果で、いろいろな方向で活用できると思いますけれども、そういうアンケートをとるときの仕組みというか、そのあたりを、普通、僕らが学校で「回答してください」と言ったら、「はい」と、みんな子どもたちがやると思うのだけれども、それが、回答しなかった、それから、回答した中で適切でなかったというのが。","respondent":"渋谷指導課長","answer":"アンケートについては、無記名で子どもたちもとっていますので、一旦集めてしまってマークミスがあったら、それを戻してやり直すのはなかなかできないというようなことがありますので、最初に配る段階できちっとマークミスがなかったり。","voiceIndex":69,"id":"exchange-029"},{"speaker":"須藤副委員長","kind":"質問","question":"それと同時に、無回答が６０４人いたというのはどういうことなのでしょう。調査する日にそれだけ休んでいたということなのですか。","respondent":"渋谷指導課長","answer":"これは欠席者等々、実は対象者がいたのだけれども、当日、何らかの理由で休みだったりして、調査用紙が配れなかったし、回収できなかった数だと理解しております。","voiceIndex":71,"id":"exchange-030"},{"speaker":"須藤副委員長","kind":"質問","question":"ですから、できるだけこの数値が１００％になるように、休んでしまったら、無記名だから次の日に書いてくれというやり方があると思うので、できるだけ多くのデータを集めていかないと、教育自体がきちんと児童・生徒に伝わらないというあらわれだと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-031"}]},{"id":"topic-04","title":"の平成２６年特別区および東京都人事委員会勧告の概要","agenda":"の平成２６年特別区および東京都人事委員会勧告の概要","exchanges":[{"speaker":"南委員","kind":"確認","question":"１５年間も上がっていなかったという実態を改めて確認できたのですけれども、今回、久々に引き上げをすることについては、それはそれとして受けとめておきたいと思います。全体的には引き上げをすることで、こういう時代ですので、一定の評価はしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":78,"id":"exchange-032"}]},{"id":"topic-05","title":"の通級指導学級（言語障害）の新規開設","agenda":"の通級指導学級（言語障害）の新規開設","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"学級が１つ増えて職員も増員される、それでこういう通級指導が一層よくできるという点は評価したいと思っています。それで台場小学校がその学級の場所になるわけですけれども、ここに「教室空調などの工事」となっているので、一定、リニューアルされてそんなに日がたっていないのに、こういう工事はどういうことなのか、その点だけよくわからないので、教えていただきたいと思います。","respondent":"村尾学校支援担当課長","answer":"現在、難聴のクラス、通級の学級はあります。そこに１クラス増えるために、もともとそこは通常の授業では使っていない教室だったものですから、エアコンがまだついていないというのがありましたので、子どもたちの学習の場所にもなりますので、空調等の工事を予定しています。","voiceIndex":84,"id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"空調のついていない教室があったというのは、私的には驚いたのですけれども、改修されてきれいになって、どこの教室も空調設備が整っていると思っていたのだけれども、一般論では、そういう新しくされた学校でも当初の予定ではついていないことがあり得るということですか。","respondent":"田村教育次長","answer":"使っていない教室だったのです。だから、ほかの用途で使っていたのでしょうけれども、使っていないと。だから、教室として使っていないので空調をつけていないので、今後、使うようになるので、空調の設備を設けると、そういう話です。","voiceIndex":86,"id":"exchange-034"}]},{"id":"topic-06","title":"(6)平成２５年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"(6)平成２５年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１枚目の家庭あんしんセンター、表面の下にある「マニュアルの情報量が増えると、本来の機能を発揮しづらくなる恐れがあるため」という、ここの「マニュアルの情報量が増えると」の意味がよくわからなかったのですけれども、とりわけ説明もなかったので、どういうことなのか教えていただきたいと思います。","respondent":"伊崎子育て支援課長、竹田保育課長","answer":"家庭あんしんセンターのマニュアルについて、私からご説明申し上げます。ただ、保育士の不足等の関係から、経験ある中堅職員等を採用したなどの点から、人材確保のため、例年より若干、支出が増えているところです。","voiceIndex":96,"id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"それと家庭あんしんセンターのマニュアルですけれども、いろいろな問題が出たときにマニュアルどおりにということが求められ、特にＩＳＯでしたか、環境何とかという、そういうものがずっと以前、何年か前に強く求められ、公立保育園でも全てマニュアル化されていると聞いていますけれども、同じような指導の中でマニュアルが情報量が増えるというふうになっているのかと。","respondent":"竹田保育課長、伊崎子育て支援課長","answer":"組織の運営上、一定程度、人の退職がありますので、適切な補充も必要です。その抜けた職員の経験年数等を勘案しながら、適切な人材補給に努めているところです。当然、データでも持っているとは思いますけれども、基本は誰でもすぐに見られるように、紙ベースでの蓄積がされているです。","voiceIndex":99,"id":"exchange-036"},{"speaker":"須藤副委員長","kind":"質問","question":"それは、教育はある程度お金は必要なので、それはどこでもあれば、それなりの効果は出てくるという話で、運営費の見直しを行うということですけれども、それはどういう基準をしようとしているのか。ほかの保育園だとかそういうところと同一の状況に合わせようとするのか、もっとプラスして、この「特色ある事業」を拡大しようとするのか、そのあたりはどうなのでしょうか。","respondent":"竹田保育課長","answer":"委員おっしゃられたとおり、そうはいっても、ほかの幼稚園、保育園等とのバランス等も十分加味しながら、適切な運営あるいは効率的な施設の見直し等を今後も図っていきたいと考えております。","voiceIndex":102,"id":"exchange-037"},{"speaker":"須藤副委員長","kind":"質問","question":"そのあたりの調整はどういうふうにしようかというところだろうと思うのですが、そうすると、ここがモデルだから、どんどんレベルを上げていきます、みんな、ＮＰＯのメンバーもやる気は十分だから、いろいろな事業をやってくれれば、それはお子さんたちや保護者は喜んでくれると思いますけれども、それはどんどん拡大していってしまうだろうと思いますけれども。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、余りにもそれが過大になり過ぎると、幾ら特色といっても、コスト的にも膨大になってまいりますので、私どもとしては、基準を区立のところに合わせるということではありませんけれども、一定程度の目安で上限を考えながら、その事業のできる範囲内ということを。","voiceIndex":104,"id":"exchange-038"},{"speaker":"南委員","kind":"質問・要望","question":"実は、年度が変わるときに、たしか３日ほど閉園になっているはずですけれども、その問題は鋭意協議を進めて、解消の方向で区も求めてきているけれども、なかなか折り合っていないという状況を聞いていますけれども、それについてはどうなのかということを、この際、伺っておきたいと思います。","respondent":"竹田保育課長","answer":"この移行期の３日間をインターバルとして設けているものですが、この期間が預かり保育等を希望している方につきましてはお受けしている状況ですので、この考え方につきましては、区としても、今後、十分指定管理者と協議していきたいと考えております。","voiceIndex":106,"id":"exchange-039"}]},{"id":"topic-07","title":"「居住実態が把握できない児童」に関する調査の結果","agenda":"「居住実態が把握できない児童」に関する調査の結果","exchanges":[{"speaker":"石田（し）委員","kind":"確認","question":"１点だけ確認したいのですけれども、裏面に調査方法が出ていて、その中で、例えば保育園の在籍とか、児童相談所で現認されたとか、家庭訪問で確認したり、なぜその前にはこの子たちは実態が把握できなかったのでしょうか。","respondent":"伊崎子育て支援課長","answer":"ですので、全く何もせずいた子が３８人ということではなく、各所管で対応していた、あるいは連絡をとっていたけれども、連絡がつかなかったり、現認ができたお子さんにつきましても、お子さんに連絡がとれずに、訪問をしても家にいないというところで。","voiceIndex":112,"id":"exchange-040"},{"speaker":"石田（し）委員","kind":"質問","question":"そうすると、調査はしていたけれども会えなかったりというので、実態が把握できなかったけれども、今回、その調査方法をさらに拡充して調査をしたら、実態把握をすることができたということでよろしいのですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":114,"id":"exchange-041"},{"speaker":"南委員","kind":"質問・要望","question":"その他は、ゼロから５歳が１０人ということで、１４人もの子どもがわからなかったわけですけれども、それが調査を広げていく中でわかったということですけれども、先ほどのご質問も含めてですけれども、親子ともに日本国籍の方がゼロから５歳は１１人いたけれども、そのうちの３人の所在が最終的にわかったということなのだけれども、これは具体的にどこを、この３人は。","respondent":"伊崎子育て支援課長","answer":"居住実態に対する対策会議の連絡調整部会のメンバーですが、連絡調整部会のメンバーといたしましては、子ども未来事業部長を部会長といたしまして、総務課、戸籍住民課、子ども未来事業部の３課長、品川区保健所の各センター長、それと教育委員会は学務課長。","voiceIndex":115,"id":"exchange-042"},{"speaker":"南委員","kind":"質問・要望","question":"できたら、その１４人の中のそれぞれ、国籍が日本にある人の６歳から１１歳の１人は、ここに１人ですからわかるけれども、その他のところの１０人を知りたいと思ったのですけれども、先ほど、それも含めて教えてもらいたいと言ったつもりですけれども、差し支えない範囲でいいのですけれども、教えていただきたいと思います。","respondent":"伊崎子育て支援課長","answer":"今、その数値は後ほど。","voiceIndex":117,"id":"exchange-043"},{"speaker":"南委員","kind":"質問","question":"わかりました。では、詳しく聞くつもりは全然ないですけれども、「警察にて現認」というのはゼロから５歳なので、どういうことなのかわからないのですけれども、それ以上の先は教えられない、公表できない、そういうことで理解するしかないのですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-044"},{"speaker":"吉田委員","kind":"質問","question":"乳幼児健診を受けていなかったり、それぞれ経過が違うというお話を今日聞いたのですが、このお子さんたち、ゼロ歳から５歳の出国なさった方以外で就学に向けての例えばフォローとか、何せ見つかったからよかったではなくて、その先に何か、例えば対処の方法とかがあったりするのではないかと思いますけれども、そういうことに関してのフォローはどうなのでしょうか、教えてください。","respondent":"伊崎子育て支援課長","answer":"この調査は、そもそも養育支援が必要な家庭の中に居住実態が把握できない世帯があることから発しているものでございまして、当然、家庭環境に問題がある、課題がある家庭につきましては、子育て支援センター、場合によっては児童相談所できちっと。","voiceIndex":120,"id":"exchange-045"},{"speaker":"つる委員","kind":"確認","question":"今の話も含むかもしれませんけれども、出国については、日本以外にというところだと問題なのですが、あと国内にいらっしゃる中で、今、課長から答弁もありましたけれども、その辺の確認というのですか、お子さんのより安全の確認はできているという認識でいいのかどうかをまず教えてください。","respondent":"伊崎子育て支援課長","answer":"出国された方は外国にいらっしゃるということで確認していることですが、国内に在住しているお子さんにつきましては、当然、品川区内にいらっしゃるお子さんでしたら、今申し上げました要支援家庭、要保護世帯ということで認識いたしまして、対応はとってまいります。","voiceIndex":122,"id":"exchange-046"},{"speaker":"つる委員","kind":"確認","question":"すみません、確認でした。その中で２３区の一覧もあって、品川区が５人という数字が出ていて、他区の取り組みが自治体独自の取り組みとして出ているのですけれども、この辺の関係性は、国からやってくださいということで自治体としてやったことと、今、この報道の中で出ている取り組みとの関係がわかれば教えてください。","respondent":"伊崎子育て支援課長","answer":"今回、平成２６年４月の通知の以前にも、養育支援を特に必要とする家庭についてきちんと取り組みを進めることという通知が来ておりまして、昨年度から、保健センターとの連携を特に密にして対応は進めていたところです。","voiceIndex":124,"id":"exchange-047"},{"speaker":"つる委員","kind":"意見","question":"一般紙で報道されていた部分を含めて、今、ご答弁いただいた形で今後の対応ということで、対策会議の中の連絡調整部会の中で、今のことも含めてきちっと今後、対応、体制を含めていただける、そういう理解でよろしければ、答弁は要りません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":126,"id":"exchange-048"}]},{"id":"topic-08","title":"品川区子ども・子育て計画（素案）","agenda":"品川区子ども・子育て計画（素案）","exchanges":[{"speaker":"石田（し）委員","kind":"質問・要望","question":"１歳児で例えば平成２７年度だと、１,６９４人という数字が出ているではないですか。さらに１歳児を預けていないけれども、２歳児になったら預けようという人はいるかもしれないけれども、要は増える可能性はあっても、減る可能性はないのではないかと思いますけれども、その辺はどういう算出方法でこういう数字が出てくるのですか。そこだけ教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"品川区の場合、今回、人口の算出根拠といたしましたものが、品川区長期基本計画の改訂の際に保育需要調査を行いまして、昨年度も保育需要調査の結果は当文教委員会の報告にさせていただいたのですが、その品川区長期基本計画の数字自体が、１歳刻みですると。","voiceIndex":131,"id":"exchange-049"},{"speaker":"南委員","kind":"確認","question":"４５ページの「放課後児童健全育成事業」ですけれども、この間、私たちも、すまいるスクールの中に学童保育事業も含まれているという説明をしてきているのですけれども、学童保育クラブ、その事業そのものは、専門的な専有スペースが確保されていなければいけないことになっているのですけれども、ここは量の関係だけの計画なので、そこまで出ていないと言われてしまえばそれまでですけれども、しかし。","respondent":"伊崎子育て支援課長","answer":"放課後児童健全育成事業につきましては、今おっしゃられたように、すまいるスクールの中で実施をしている事業です。この放課後児童健全育成事業の基準につきましては、国の指針では放課後専有ができるところであればよいと。","voiceIndex":133,"id":"exchange-050"},{"speaker":"南委員","kind":"質問・要望","question":"要するに平成２５年３月時点では、登録数が低学年が６,３１７人で、高学年が３,００３人で、１校平均２４５人と、こういうことなのですけれども、この中に学童保育クラブ事業の子どもたちが何人かいるわけで、その数は示されていないからわからないのですけれども、しかし、放課後、家に帰っても誰もいない学童保育児童ということで放課後を学校で過ごす子どもたちにとって。","respondent":"伊崎子育て支援課長","answer":"こちらの計画はどういう見込みの計画ですといったようなものは、掲載はしておりません。資料につきましては、特にご提示するという形では、今、おつくりしているものは特にございません。","voiceIndex":135,"id":"exchange-051"},{"speaker":"南委員","kind":"質問・要望","question":"だから、そういうふうに口頭だけで何回聞いても、何回でも満たしているということで私たちも検証できるものがないので、私たちの側からすると、繰り返し取り上げて確認するしかないということになるわけです。それをぜひ要求したいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":137,"id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"そうですね。したがって、本来であればきちんとした資料的なものを持っているべきだと思っています。それについてのお考えというか、ご回答があれば言っていただきたいけれども、ないということであれば、了解していただけると理解したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":141,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"私、文教委員会としては、そういうことをしっかり把握できるようにしろと求めて当然のことだと思うので、だから、今の委員長のご発言では、その辺を読まなければいけないかという気持ちにさせるように私は理解したので、改めてこのことを発言させていただいたのですけれども、当然、持っていなければいけないものだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":145,"id":"exchange-054"},{"speaker":"つる委員","kind":"質問・要望","question":"１点教えてください。３９ページの地域型保育給付事業の中の居宅訪問型保育、先ほどざっとこういう障害者が対象でということでお話がありましたが、このところの確認の部分を含めて教えていただきたいのと、品川区の今後の考え方のようなものが今現在あれば、それも教えてください。","respondent":"今井制度改革・待機児童対策担当課長","answer":"事業者からの提案も含めて検討しています。今後の計画につきましては、まずはニーズ、事業者等の運営、継続的な運用が図れると見込まれましたら、この計画は今後、この計画を改めていくものですので、その時点で計画の中に乗せていきたいと考えております。","voiceIndex":148,"id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"確認で、そうすると、今、このパブリックコメントを直前にした中では、ずっと平成３１年度まではゼロ、ゼロ、ゼロという数字が出ていますけれども、今ご答弁いただいたように、障害者福祉課との連携の中で、ニーズと実施が可能な事業者との調整のマッチングで合ったときに、それを検討の中に入れてこの計画の中に盛り込んでいく検討材料の中の一つに入る、こういう考え方でいいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":150,"id":"exchange-056"},{"speaker":"高橋委員","kind":"質問","question":"「認定こども園」という名称を使う場合は、認定こども園にのっとった仕組みとかそういうものしかできないというふうにあるのですが、この４つの認定こども園、区立のですが、「認定こども園」という名称を平成２７年４月から使って保育・幼児教育がされていくのでしょうか。私が読んだ法令の読み方が間違っていたり、ほかの法律によって可能ならば、そのようにご説明いただければと思います。","respondent":"今井制度改革・待機児童対策担当課長","answer":"区立につきましては、品川区で幼保一体施設等を持っておりますが、先日も本会議で答弁申し上げた内容にもかかわりますけれども、施設基準ですね、園庭の面積ですとか、あと、新たな幼保連携型認定こども園では、保育教諭という職の設置が求められますので。","voiceIndex":151,"id":"exchange-057"}]},{"id":"topic-09","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"食育の、特に学校教育のところで聞きたいのですが、ある程度基本的な知識、市民科と家庭科でこれを基本だととらえたときに、家庭も、僕らもそうなのですけれども、どうしても全てがきっちり年間を通してとか、毎月きっちりというのは、食事に限ったら難しいと思います。その点、今、そういう点の目立った取り組みはあるものなのでしょうか。","respondent":"村尾学校支援担当課長","answer":"なので、食べなかったらいいというものではなくて、健康的には食べること、それは運動すること、寝ることということについては、結構、特に高学年になったり中学校の女子については、十分話をしています。","voiceIndex":159,"id":"exchange-058"},{"speaker":"渡辺委員","kind":"質問","question":"これは特にどなたというか、カリキュラム、テキストがどうこうではなく、結構、個々にもよるので、例えば担任の先生のちょっとした日常会話の中の影響力が非常に大事だと思っていますし、正解があるものでもないと思うのです。この辺などは、何か児童・生徒や保護者が知る機会は、ダイエットとは関連もしながらメインテーマとしてあってもいいのかと思っているので、取り組みが何かあるのか、教えてください。","respondent":"野呂瀬学務課長","answer":"それを実践の成果を、例えば研究会なり何なり養護教諭部会なりで情報共有をして、各学校に持ち帰ってどういうふうな形で成果に上げていくかは、またこれから食育を充実させていく一つの課題であるかと考えております。","voiceIndex":161,"id":"exchange-059"},{"speaker":"石田（し）委員","kind":"質問","question":"歯磨き指導ですけれども、この間、視察に行ったときに、その小学校では歯磨き指導をやっていて、では、その子どもが行く学区内の中学校はどうなのという話をしたら、中学校としてはやっていないけれども、小学校でやっていたので、自然に中学校でもやっていますという話を聞いて、非常に連携がとれているというか、うまくスムーズに連結されているのかという印象はあったのですけれども。","respondent":"村尾学校支援担当課長","answer":"ここに書かれている小学校１３校と、中学校１校、小中一貫校１校というのは、いわゆる学校として取り組んでいる学校です。","voiceIndex":163,"id":"exchange-060"},{"speaker":"石田（し）委員","kind":"意見","question":"ぜひ進めていっていただければと思います。特に品川区の場合は小中一貫教育の中でやっているので、その辺の連結はうまくいくのかと思うので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":165,"id":"exchange-061"},{"speaker":"つる委員","kind":"質問","question":"小・中学校で、給食の中で地場産物の給食で「区内産の農産物を給食に使用することは困難だが」とあるのですけれども、だから、一括して全校でどーんとやるのは、食材の数量だとかという課題はあると思いますが、これまでの中で、特に品川区で、昔、産出されていたとか、とれていたというものを含めたり、学校でやっているところがあったのかと思いますけれども、もしその辺がわかれば教えてください。","respondent":"野呂瀬学務課長","answer":"例えば浅間台小学校は品川カブを栽培して、それを給食の中に入れるような取り組みはしていますけれども、何せここで言う地場産物、要は七尾市のようなレベルをというのはやっていない、そういう意味ですので、確実にそういうのがあったとか、物の由来だとか。","voiceIndex":166,"id":"exchange-062"},{"speaker":"つる委員","kind":"質問・要望","question":"自分の地元などでもタケノコということで、これは地元の商店街が一生懸命やられてタケノコを混ぜるとか、そういったところで地域でやっている。もう一つが郷土料理のところで、これは一例だと思いますけれども、八丈島が挙げられていて、室鯵と明日葉とありますけれども、これは八丈島を使うのは、どこかの学校だと思いますが、やったその理由は何かあるのでしょうか。","respondent":"村尾学校支援担当課長","answer":"八丈島の部分については、５年生で水産業をちょうど学習したタイミングでそれを一緒に入れたと聞いております。","voiceIndex":168,"id":"exchange-063"},{"speaker":"つる委員","kind":"質問","question":"水産業を学んだときに八丈島で、もう一回詳しく教えてください。","respondent":"村尾学校支援担当課長","answer":"５年生の社会科で水産業をやるときに、さまざまな漁業関係のお話をしたときに、そこでイコール八丈島を学習したわけではないかもしれないのですが、漁業で魚を勉強したときに、では、魚料理ということで、たまたまこのトビウオを教材に使ったと聞いております。","voiceIndex":170,"id":"exchange-064"},{"speaker":"つる委員","kind":"提案","question":"これは一つ言ったのは、文京区だったか、どこかの小学校で伊豆大島の大島牛乳を使っていらっしゃるそうなのです。全部ではないですけれども、一部だったですか、全地区だったか忘れてしまいましたが、そういう話を聞いたものですから、私も小さいときから非常になれ親しんでいる牛乳でして、大変おいしい。これは提案で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":172,"id":"exchange-065"},{"speaker":"南委員","kind":"確認","question":"先ほどのアンケートでも、朝食をとっているのが、そういう数字が出ているぐらい、意外に高くてほっとしたのですけれども、この食育の大事さは一番最初に書いてあるように、本当に食事を通していろいろな自分の暮らしの問題から、健康の問題から、社会の問題から、産業の問題から、ものすごく発展していくもので、本当に大事なことを日常的な生活の中から実感する、また。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":173,"id":"exchange-066"},{"speaker":"吉田委員","kind":"質問","question":"こういう栄養素とかいろいろ計算し尽くされて、一定のお子さんの年に応じて一定量が出てくると思いますけれども、私が聞いたところによると、残飯が子どもの好みによって好きなもののときにはなくなるし、そうでないときには残飯が結構残って返ってくるというような話がありますけれども、古い話ですけれども、私の子どものころは泣きながら、昼休み、全部終わるまで食べていたような時代もありますけれども。","respondent":"村尾学校支援担当課長","answer":"今は残してまで無理やり食べさせるという指導は行っておりません。どちらかというと、苦手なものはちょっと減らして盛りつけてもらうとか。ただし、最後まできちんと食べましょうという指導はしているところです。","voiceIndex":174,"id":"exchange-067"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう意味で、今おっしゃったように、盛りつけを工夫なされているというのですけれども、つくっていただく方のご努力も、または、その食材をいただくことでのそういう指導もなるべく残さないでというのは、泣きながらというのはもう昔の話なのはよくわかりましたけれども、そういうご指導等もやっていただけたら、成長段階にあるそういう量的なこともあると思うので。","respondent":"村尾学校支援担当課長","answer":"今、委員がおっしゃるとおりで、学校でも結構、「いただきます」というのは命をいただきますというような指導も各学校で行いながら、また、子どもたちに、そのものを食べるという行為もすごくきちっとした礼儀があるということで進めているところではあります。","voiceIndex":176,"id":"exchange-068"},{"speaker":"須藤副委員長","kind":"質問","question":"何点か。それはまたリサイクルして肥料にするとなっているのだけれども、そういうふうなことは、食の量というか、子どもたちの体と、大きい子はよく食べる、小さい子は残してしまうのは当たり前なのだけれども、そのあたり、都会の子どもがそれだけしっかり食べているという数字が出てくれれば頼りになると思いますけれども、そのあたりはどうなのでしょうか。３点お願いします。","respondent":"野呂瀬学務課長、村尾学校支援担当課長","answer":"当然、量によっては、それしかないようなことがあります。ですけれども、基本的には上がっておりませんし、一部、保護者のお母さんからのそういう声も一切学校には上がっていないと聞いております。３点目、残飯の量等ですが、学校では残飯が多い日は、一体なぜこれが残ったのかということで、味つけであったり、または今後少し工夫をして変えてみようというようなことについても、学校では取り組んでいるところなので。","voiceIndex":178,"id":"exchange-069"},{"speaker":"高橋委員","kind":"質問・要望","question":"今、小学校、中学校、保育園ですけれども、幼稚園で何か食育があって、先ほどイベントというのがあったのですが、それ以外に何か働きかけていることがあれば、保護者の方が中心になるのかもしれませんけれども、何かありましたら、教えていただきたいと思います。もし所管事務調査で予定に入っていないならば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-070"}]},{"id":"topic-10","title":"その他に参ります。 初めに、(1)の所管質問","agenda":"その他に参ります。 初めに、(1)の所管質問","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"昨日も聞いたのですけれども、多くはダブらないつもりで質問したいと思っていますけれども、若干ダブることはお許しいただきたいと思います。私は、来年４月、待機児ゼロにするべきだと、そこに目標を置いて解消策を図るべきだと思っていますけれども、その点についての見解を改めて一番最初に伺っておきたいと思います。いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-071"},{"speaker":"南委員","kind":"質問・要望","question":"それに関して、一つは、年末の締め切りにはどのくらいに上ると予想しているのか、そこを伺いたいと思います。６園で足りるかどうかはわからないですけれども、予想の数とにらめっこをするべきだと思いますけれども、その６園の内容、今現在、どういうふうな状況にあるのかを教えていただきたい。その６園で足りると予想しているのかについても、あわせて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":193,"id":"exchange-072"},{"speaker":"南委員","kind":"質問・要望","question":"昨日の質問でも私もさせていただきましたけれども、昨日の答弁では、区立保育園は来年の７月にできる五反田第二保育園で最後ですかと質問したのですが、「公・私立合わせてつくっていく」、それから、「その他の総合的な対策をとっていく」という答弁で、平行線で終わったのですけれども、改めて公立もつくる姿勢はあると、私は昨日の答弁で確認をしたい。","respondent":"今井制度改革・待機児童対策担当課長、渋谷指導課長","answer":"区立認可保育園の今後の考え方ですが、私、昨日申し上げましたのは、区立の認可保育園に公・私立も含めまして、今後、開設について検討していくと申し上げましたので、来年度、五反田第二保育園を開設して以降は。今回、６年生の卒業式をやるといった検討の経緯についてですが、１３地域センターを回る「教育に関する意見交換会」、また、地域教育懇談会が名称を変えて今年度実施しておりますが、そこで何人かの町会関係の方からご要望があったこと。","voiceIndex":194,"id":"exchange-073"},{"speaker":"南委員","kind":"質問・要望","question":"引き続きよろしくお願いしたいと思います。大事なことは、それほど努力したけれども、結果的に進まずに、来年の４月です、６月・７月のオープンはあるにしても、４月の時点で待機児にならないような対策をとっていただきたいと思います。３歳以上になると、幼稚園も認定こども園も含めてそれなりの枠はあるわけですけれども、３歳未満が本当に厳しい状況なので、ここについてしっかりとやっていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-074"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4838#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":68524,"voices":204}}]);
